(window.GIM_TS=window.GIM_TS||{})["Bava Metzia.2"]={"from":48,"a":[["\u0003דשתיך טפי\u0004 \u0005[ש\u0006היה \u0005חלוד הרבה],\u0006 שברור שהוטמן שם לפני זמן רב.","שנינו במשנה כי המוצא דבר \u0003בכותל חדש, מחציו ולחוץ\u0004 — \u0003שלו, מחציו ולפנים\u0004 — \u0003של בעל הבית.\u0004","לענין מציאת דבר בחור שבכותל \u0003אמר רב אשי:\u0004 אם היתה זו \u0003סכינא\u0004 \u0005[סכין],\u0006 הבעלות עליה נקבעת \u0003בתר קתא\u0004 \u0005[לפי הקת],\u0006 שאם קת הסכין לצד פנים — מן הסתם בני החצר הניחוה שם, ואם קתה לחוץ — מסתמא מישהו מן החוץ הניחה כך. \u0003ו\u0004כן הבעלות על \u0003כיסא\u0004 \u0005[כיס]\u0006 נקבעת \u0003בתר שנציה\u0004 \u0005[אחר השנצות],\u0006 החוטים שבהם קושרים את פי הכיס.","ושואלים: \u0003ואלא מתניתין דקתני\u0004 \u0005[משנתנו ששנה בה]\u0006 \u0003מחציו ולחוץ\u0004 — \u0003שלו, מחציו ולפנים\u0004 — \u0003של בעל הבית,\u0004 מה טיבו של סימן זה? \u0003ולחזי\u0004 \u0005[ונראה],\u0006 \u0003אי קתא לגאו אי קתא לבר, אי שנציה לגאו אי שנציה לבר\u0004 \u0005[אם קת\u0006 הסכין \u0005לפנים, אם הקת לחוץ, אם שנציו\u0006 של הכיס \u0005לפנים אם שנציו לחוץ]!\u0006 ומשיבים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 מדברת בדברים שאין להם צורה וצדדים מוגדרים, וכגון \u0003באודרא ונסכא\u0004 \u0005בסמרטוטים או טבלת מתכת].\u0006","\u0003תנא\u0004 \u0005[שנה החכם]:\u0006 \u0003אם היה כותל ממולא מהן,\u0004 כגון במטבעות — \u0003חולקין\u0004 המוצא שמבחוץ ובעל הכותל. ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שכך הדין, שהרי לפי האמור במשנה רואים שהדבר שייך לשני הצדדים! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקום שהיה הכותל \u0003משפע בחד גיסא\u0004 \u0005[משופע בצד אחד],\u0006 \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי מתחילה היו המטבעות בצד הגבוה, ומשם \u0003אשתפוכי אישתפוך\u0004 \u0005[נשפכו]\u0006 ולכן הכל שייך למי שהצד הגבוה הוא בחלקו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שבכל זאת אינו כן, שכיון שאי אפשר להוכיח שכך היה, הולכים על פי המצב בהווה.","שנינו במשנה ש\u0003אם היה\u0004 בעל הבית \u0003משכירו,\u0004 את ביתו, \u0003לאחרים, אפילו מצא\u0004 אדם דבר \u0003בתוך הבית\u0004 — \u0003הרי אלו שלו. ו\u0004שואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 נאמר כן? \u0003ליזיל בתר בתרא\u0004 \u0005[נלך אחר\u0006 האיש \u0005האחרון]\u0006 שהיה בבית, שמסתבר שהוא איבד את החפץ.","\u0003מי\u0004 \u0005[האם]\u0006 \u0003לא תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003מעות שנמצאו לפני סוחרי בהמה\u0004 בירושלים — \u0003לעולם מעשר,\u0004 שיש לשער שאין אלה כספי חולין אלא כספי פדיון מעשר שני, כיון שהרבה מאד אנשים מביאים לירושלים סכומים גדולים של פדיון מעשר שני שלהם, ובכסף זה קונים בהמות לזבחי שלמים, ולכן המעות הן תמיד מעות מעשר. אם נמצאו מעות \u0003בהר הבית\u0004 — הרי הן \u0003חולין,\u0004 שמן הסתם כבר הוציא הבא למקדש את כספי המעשר שלו לפני בואו להר הבית, והכסף שנשאר ברשותו כסף חולין הוא.","\u0003ו\u0004אם מצא כסף בשאר מקומות \u0003בירושלים,\u0004 אם היה זה \u0003בשאר ימות השנה\u0004 — מן הסתם זהו כסף \u0003חולין,\u0004 אם היה זה \u0003בשעת הרגל,\u0004 שרוב המצויים בעיר עולי רגל הם ומביאים כספם בידם — כל מה שמצא \u0003מעשר.\u0004","\u0003ואמר ר'\u0004 \u0003שמעיה בר זעירא: מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 מדוע אומרים שמיד לאחר הרגל כספי חולין הם? — \u0003הואיל ושוקי ירושלים עשוין להתכבד\u0004 (להיות מנוקים במאטטאים) \u0003בכל יום,\u0004 ובוודאי כבר נמצא כל הכסף שאבד ביום אתמול. ולענייננו: \u0003אלמא אמרינן\u0004 \u0005[מכאן שאנו אומרים]\u0006 \u0003קמאי קמאי אזלו, והני אחריני נינהו\u0004 \u0005[ראשונים ראשו\u0006 \u0005נים הלכו להם ונמצאו, ואלה אחרים הם].\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בבית נאמר: \u0003קמא קמא אזל והני דבתרא נינהו\u0004 \u0005[ראשון ראשון הלך ו\u0006המעות \u0005הללו של האחרון\u0006 שהיה בבית \u0005הן]!\u0006","\u0003אמר ריש לקיש משום\u0004 \u0005[בשם]\u0006 \u0003בר קפרא: כגון שעשאו\u0004 את הבית \u0003פונדק לשלשה\u0004 מ\u0003ישראל,\u0004 וכיון שהיו רבים, כל מה שאיבדו שם נעשה כהפקר.","ומעירים: \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003הלכה כ\u0004שיטת \u0003ר'\u0004 \u0003שמעון בן אלעזר\u0004 שהמוצא במקום שמצויים בו רבים רשאי לקחת לעצמו \u0003אפילו ברוב ישראל,\u0004 ותיפתר בעיה שעד כה לא מצאנו לה פתרון!","ודוחים: אין הכרח לפרש כך, \u0003אלא אמר רב מנשיא בר יעקב: כגון שעשאו פונדק לשלשה גוים\u0004 ואנחנו מניחים שהם שאיבדו את החפץ.","\u0003רב נחמן אמר\u0004 בשם \u0003רבה בר אבוה: אפילו תימא\u0004 \u0005[תאמר]\u0006 שהיו שם \u0003שלשה\u0004 מ\u0003ישראל\u0004 ובכל זאת לא תיפתר השאלה העקרונית, כי כאן יש מצב מיוחד, \u0003מאי טעמא\u0004 \u0005[ומה טעם\u0006 הדבר\u0005]?\u0006 — האדם \u0003ההוא\u0004 ש\u0003נפל מיניה מיאש\u0004 \u0005[שנפל ממנו\u0006 הכסף ודאי \u0005מתייאש]\u0006 במצב זה, ומדוע? \u0003מימר אמר\u0004 \u0005[אומר הוא]\u0006 בלבו: \u0003מכדי איניש אחרינא\u0004 \u0005[הרי אדם אחר]\u0006 \u0003לא הוה בהדי\u0004 \u0005[היה איתי]\u0006 \u0003אלא הני\u0004 \u0005[\u0006שני אנשים \u0005אלה],\u0006 \u0003אמרי קמייהו\u0004 \u0005[אמרתי לפניהם,\u0006 להם\u0005]\u0006 \u0003כמה זמני ליהדרו\u0004 \u0005[פעמים שיחזירו]\u0006 \u0003לי, ולא הדרו\u0004 \u0005[החזירו]\u0006 \u0003לי,\u0004 \u0003והשתא ליהדרו\u0004 \u0005[ועכשיו יחזירו]?!\u0006 \u0003אי דעתייהו לאהדורה אהדרוה ניהלי\u0004 \u0005[אם היה בדעתם להחזיר\u0006 היו כבר \u0005מחזירים אותה לי],\u0006 \u0003והאי\u0004 \u0005[וזה]\u0006 ש\u0003לא אהדרוה\u0004 \u0005[החזירוה]\u0006 \u0003לי\u0004 ודאי \u0003בדעתייהו למיגזלה\u0004 \u0005[בדעתם\u0006 היה \u0005לגזול אותה],\u0006 וכיון שאינו יכול לעשות להם דבר ממילא התייאש מן המטבע. ולכן אם מצא הבא אל הבית דבר היה זה בודאי כבר לאחר יאוש.","ומעירים: \u0003ואזדא\u0004 \u0005[והולך]\u0006 \u0003רב נחמן לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר רב נחמן: ראה סלע\u0004 (מטבע)"],["\u0003שנפל משנים\u0004 — \u0003חייב להחזיר. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — האדם \u0003ההוא\u0004 ש\u0003נ\u0004 \u0003פל מיניה\u0004 \u0005[ממנו]\u0006 הכסף \u0003לא מיאש\u0004 \u0005[מתייאש],\u0006 שכן \u0003מימר אמר\u0004 \u0005[אומר הוא]\u0006 בליבו: \u0003מכדי איניש אחרינא\u0004 \u0005[הרי אדם אחר]\u0006 \u0003לא הוה בהדאי\u0004 \u0005[היה איתי]\u0006 \u0003אלא האי\u0004 \u0005[זה],\u0006 \u0003נקיטנא ליה ואמינא ליה\u0004 \u0005[אחזיק בו ואומר לו]:\u0006 \u0003אנת\u0004 \u0005[אתה]\u0006 \u0003הוא דשקלתיה\u0004 \u0005[שלקחתו],\u0006 את הכסף, ואף שלבסוף יתברר שלא הוא לקח, מכל מקום המאבד איננו מתייאש, ומשום כך חייב המוצא להחזיר.","ואולם אם נפל הכסף מאחד \u0003משלשה אינו חייב להחזיר. מאי טעמא\u0004 \u0005[מה טעם הדבר]?\u0006 — \u0003ההוא דנפל מיניה ודאי מיאש\u0004 \u0005[זה שנפל הכסף ממנו ודאי מתייאש],\u0006 \u0003מימר אמר\u0004 \u0005[אומר הוא]\u0006 בליבו: \u0003מכדי תרי הוו בהדאי\u0004 \u0005[הרי שניים היו איתי],\u0006 \u0003אי נקיטנא להאי אמר\u0004 \u0005[אם אתפוס את זה, יאמר]:\u0006 \u0003\"לא שקלתיה\u0004 \u0005[לקחתיו]\u0006 \u0003\", ואי נקיטנא להאי אמר\u0004 \u0005[ואם אתפוס את זה, יאמר]:\u0006 \u0003\"לא שקלתיה\u0004 \u0005[לקחתיו]\u0006","\u0003\",\u0004 וכיון שאינו יכול לתבוע בחוזקה ודאי מתייאש מיד. \u0003אמר רבא: האי דאמרת\u0004 \u0005[זה שאתה אומר]\u0006 כי \u0003בשלשה אינו חייב להחזיר\u0004 — \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 הלכה זו \u0003אלא\u0004 באופן \u0003דלית ביה\u0004 \u0005[שאין בה]\u0006 באבידה \u0003שוה פרוטה לכל חד וחד\u0004 \u0005[אחד ואחד],\u0006 \u0003אבל\u0004 אם \u0003אית\u0004 \u0005[יש]\u0006 \u0003ביה שוה פרוטה לכל חד וחד\u0004 \u0005[אחד ואחד]\u0006 — \u0003חייב להחזיר. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003אימור שותפי נינהו ולא מיאשו\u0004 \u0005[אמור\u0006 שמא \u0005שותפים הם\u0006 אלה \u0005ואינם מתייאשים]\u0006 והם אינם חושדים זה בזה. אבל אם היתה האבידה פחות משווה שלוש פרוטות, שוב אין כאן שווה פרוטה לכל אדם, ואין כאן סכום הראוי להשבה כי המטבע שייכת לכולם.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שכך \u0003אמר רבא: אף על גב דלית ביה\u0004 \u0005[אף על פי שאין בו]\u0006 במטבע שאבד \u0003אלא שוה שתי פרוטות\u0004 — \u0003חייב להחזיר, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003אימור שותפי נינהו\u0004 \u0005[אמור\u0006 שמא \u0005שלושתם שותפים הם]\u0006 \u0003וחד מנייהו אחולי אחליה למנתיה גבי חבריה\u0004 \u0005[ואחד מהם מחל,\u0006 ויתר \u0005על חלקו לגבי חבירו],\u0006 ונמצא שיש לשניים מהם כדי שווה פרוטה לכל אחד, וכיון ששותפים הם לא התייאשו.","כסיכום של הבעיה בענין מציאת מטבע, \u0003אמר רבא: ראה סלע\u0004 (מטבע) \u0003שנפלה,\u0004 אם \u0003נטלה לפני יאוש\u0004 הבעלים \u0003על מנת לגוזלה,\u0004 שלא התכוון כלל להחזירה — \u0003עובר בכולן,\u0004 בכל האיסורים הבאים: עובר \u0003משום \"\u0004ו\u0003לא תגזול\"\u0004 (ויקרא יט, יג) \u0003ו\u0004עובר \u0003משום\u0004 מצות עשה של \u0003\"השב תשיבם\"\u0004 (דברים כב, ב) \u0003ו\u0004עובר \u0003משום\u0004 מצות לא תעשה של \u0003\"לא תוכל להתעלם\"\u0004 (דברים כב, ג). \u0003ו\u0004יתר על כן, \u0003אף על גב דחזרה\u0004 \u0005[ואף על פי שהחזיר את המטבע הזו לבעליה]\u0006 \u0003לאחר יאוש,\u0004 לא תיקן בכך את העבירה, כי מבחינת ההלכה \u0003מתנה הוא דיהיב ליה\u0004 \u0005[שנתן לו],\u0006 שהרי כבר התייאשו הבעלים וכאילו הפקירו את החפץ, \u0003ואיסורא דעבד\u0004 \u0005[ואיסור שעשה]\u0006 — \u0003עבד\u0004 \u0005[\u0006\u0005עשה]\u0006 ועבר משום כל עבירות אלה.","אם \u0003נטלה\u0004 המוצא \u0003לפני יאוש על מנת להחזירה,\u0004 שבשעת הימצאה התכוון להחזיר, ונמצא שלא עבר לא משום איסור גזילה ולא משום איסור התעלמות מאבידה, אולם עבר זמן וכבר נתייאשו הבעלים \u0003ולאחר יאוש נתכוין לגוזלה\u0004 שאינו מחזיר את החפץ שבידו, אז \u0003עובר\u0004 הוא רק \u0003משום \"השב תשיבם\"\u0004 שהרי לא עשה מעשה כדי להשיב את האבידה לבעליה.","ומקרה נוסף: ראה שנפל מטבע מאדם, \u0003המתין לה\u0004 ולא לקחה \u0003עד שנתיאשו הבעלים, ונטלה.\u0004 אם כן, כיון שבשעת נטילה היה זה לאחר יאוש אינו עובר משום גזילה, וכיון שבשעה שלקח כבר לא היתה חובת השבה, אף אינו עובר משום \"השב תשיבם\", ואם כן \u0003אינו עובר אלא משום \"לא תוכל להתעלם\" בלבד.\u0004 שהרי התעלם מן האבידה ולא דאג להשיבה.","ועוד \u0003אמר רבא: האי מאן דחזי\u0004 \u0005[מי שרואה]\u0006 ש\u0003נפל זוזי מחבריה בי חלתא\u0004 \u0005[מטבע מחבירו בין החולות]\u0006 \u0003ואשכחיה ושקליה\u0004 \u0005[ומצא אותו ולקח אותו],\u0006 \u0003לא מיחייב לאהדורי ליה\u0004 \u0005[אינו חייב להחזירו לו],\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — האדם \u0003ההוא\u0004 ש\u0003נפל מיניה מיאש\u0004 \u0005[מתייאש]\u0006 \u0003הוא\u0004 בוודאי, שיודע שבין החולות קשה עד מאוד למצוא מטבע. ויתר על כן, \u0003אף על גב דחזייה דאייתי ארבלא וקא מרבל\u0004 \u0005[אף על פי שרואה אותו,\u0006 את המאבד \u0005שמביא כברה וכובר בה]\u0006 את החול, גם אז יש להניח שהמאבד כבר התייאש, אלא \u0003מימר אמר\u0004 \u0005[אומר הוא\u0006 בליבו\u0005]:\u0006 \u0003כי היכי דנפול מינאי דידי הכי נפול מאיניש אחרינא ומשכחנא מידי\u0004 \u0005[כפי שנפלה מטבע ממני\u0006 בחולות \u0005כך\u0006 ודאי \u0005נפלה\u0006 גם \u0005מאדם אחר ואמצא משהו],\u0006 ומעשיו אינם מוכיחים איפוא שלא נתייאש.","\u0003מצא בחנות\u0004 דברים שאין בהם סימן — \u0003הרי אלו שלו,\u0004 לפי שרבים מצויים שם והמאבד ודאי כבר נתייאש. מצא דבר \u0003בין התיבה\u0004 (הדלפק) של החנווני \u0003ולחנוני\u0004 — האבידה \u0003של\u0004 ה\u0003חנוני,\u0004 לפי ששם אין הרבים מצויים אלא החנווני בלבד, ומן הסתם ממנו נפלה. וכן אם מצא דבר \u0003לפני שולחני\u0004 (מחליף מטבעות) — \u0003הרי אלו שלו.\u0004 מצא \u0003בין הכסא\u0004 שיושב על ידו השולחני \u0003ולשולחני\u0004 — \u0003הרי אלו של\u0004 ה\u0003שולחני.\u0004","\u0003הלוקח\u0004 (קונה) \u0003פירות מחבירו, או ששילח לו חבירו פירות\u0004 במתנה, \u0003ומצא בהן מעות\u0004 (כסף) — \u0003הרי אלו שלו\u0004 שוודאי נפל הכסף לשם במקרה וכבר נתייאשו ממנו הבעלים. \u0003אם היו\u0004 המטבעות \u0003צרורים\u0004 — הרי זה \u0003נוטל ומכריז\u0004 שהרי יש בהן סימן.","על דברי המשנה \"לפני שולחני הרי אלו שלו\": \u0003אמר ר'\u0004 \u0003אלעזר:\u0004 \u0003אפילו\u0004 מצאם \u0003מונחין על גבי\u0004 ה\u0003שולחן\u0004 עצמו.","ומקשים: הלא \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 מצא מטבעות \u0003לפני שולחני\u0004 — \u0003הרי אלו שלו,\u0004 ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם מצא \u0003על גבי\u0004 ה\u0003שולחן\u0004 עצמו — שייך הכסף ל\u0003שולחני!\u0004 ומשיבים: \u0003אימא סיפא\u0004 \u0005[אמור את סופה]\u0006 של המשנה וראה להיכן מוביל הדיוק שם: \u0003בין הכסא ולשולחני\u0004 — \u0003של שולחני,\u0004 ואם נדייק בלשון: \u0003הא\u0004 \u0005[הרי]\u0006 אם היה זה \u0003על גבי\u0004 ה\u0003שולחן\u0004 — הרי אלו \u0003שלו, אלא\u0004 יש להסיק כי \u0003מהא ליכא למשמע מינה\u0004 \u0005[מזו אי אפשר לשמוע ממנה]\u0006 הלכה, שאין להוציא מסקנה הלכתית בנושא זה ממשנתנו בדרך הדיוק.","ושואלים: אם כן, \u0003ור'\u0004 \u0003אלעזר, הא מנא ליה\u0004 \u0005[\u0006הלכה \u0005זו מנין לו]\u0006 אם איננו יכול למצוא את מקורה במשנה? \u0003אמר רבא: מתניתין קשיתיה\u0004 \u0005[משנתנו היתה קשה לו]\u0006 ומתוך פתרון הקושי הגיע למסקנה זו. כי \u0003מאי אריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 \u0003דתני\u0004 \u0005[ששנה]\u0006 בה \u0003\"בין הכסא לשולחני\u0004 — \u0003של שולחני\"? ליתני\u0004 \u0005[שישנה]\u0006 בנוסח: \u0003\"על\u0004 ה\u0003שולחן\". אי נמי\u0004 \u0005[או גם כן]\u0006 בנוסח: \u0003\"מצא בשולחנות\", כדקתני רישא\u0004 \u0005[כמו ששנה בתחילה]\u0006 \u0003\"מצא בחנות\u0004 — \u0003שלו\". אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 מדיוק הלשון ש\u0003אפילו\u0004 היו הכספים \u0003מונחין על גבי שולחן\u0004 — \u0003הרי אלו שלו,\u0004 של המוצא, שאין השולחני מניח מעותיו אלא במגירה ולא על גבי השולחן, ומעות שעל השולחן — מאחד הלקוחות הם.","שנינו במשנה ש\u0003הלוקח פירות מחבירו\u0004 ומצא בהם מעות — הרי אלו של המוצא. \u0003אמר ריש לקיש משום\u0004 (בשם) \u0003ר' ינאי: לא שנו\u0004 הלכה זו \u0003אלא\u0004"],["\u0003בלוקח\u0004 (קונה) \u0003מן התגר\u0004 (סוחר) שקנה את הפירות מאנשים רבים, ואין ידוע ממי מהם האבידה, \u0003אבל בלוקח מבעל הבית\u0004 — \u0003חייב להחזיר.\u0004 ומסופר, \u0003וכן תני תנא קמיה\u0004 \u0005[שנה חוזר המשניות לפני]\u0006 \u0003רב נחמן: לא שנו אלא בלוקח מן התגר, אבל בלוקח מבעל הבית\u0004 — \u0003חייב להחזיר.\u0004","על כך \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן:\u0004 ומדוע יחזיר אף לבעל הבית, \u0003וכי בעל הבית בעצמו דשן\u0004 (דש אותן) את אלומות התבואה הללו? הלא מן הסתם פועליו הם שעשו זאת, ואם כן יתכן מאוד שמן הפועלים אבד החפץ, ולא ברור ממי! \u0003אמר לו\u0004 חוזר המשניות: \u0003איסמיה\u0004 \u0005[\u0006האם \u0005אמחוק אותה],\u0006 את הברייתא הזו? שאשמיטנה מגירסתי לפי שאינה נכונה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא,\u0004 ואולם \u0003תתרגם מתניתא\u0004 \u0005[תרגם, הסבר,\u0006 את \u0005הברייתא]\u0006 \u0003כגון\u0004 ש\u0003דשן על ידי עבדו ושפחתו הכנענים\u0004 שרכושם הוא רכושו, וכל מה שאיבדו שייך לבעל הבית.","משנה זו היא קטע של מדרש הלכה בדיני מציאה. \u0003אף השמלה היתה בכלל כל אלו\u0004 החפצים שנמנו בתורה במפורש כאבידות, כאמור \"וכן תעשה לחמורו וכן תעשה לשמלתו\" (דברים כב, ג), \u0003ולמה יצאת\u0004 (יצאה) מן הכלל להיאמר בכתוב במפורש? — \u0003להקיש\u0004 (להשוות) \u0003אליה\u0004 דברים אחרים, ו\u0003לומר לך: מה שמלה מיוחדת, שיש בה\u0004 כרגיל \u0003סימנין ויש לה תובעין,\u0004 כלומר, יש לה בעלים, שהרי לא יתכן שתיווצר מעצמה, \u0003אף כל דבר שיש בו סימנין ויש לו תובעים\u0004 — \u0003חייב להכריז\u0004 עליו.","תחילה שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"בכלל כל אלו\",\u0004 מה הוא כלל זה שמדובר בו? \u0003אמר רבא: בכלל\u0004 הכתוב בדיני מציאה \"וכן תעשה לחמורו וכן תעשה לשמלתו וכן תעשה ל\u0003כל אבדת אחיך\u0004 אשר תאבד ממנו ומצאתה לא תוכל להתעלם\" (שם).","בקשר לפסוק זה \u0003אמר רבא: למה לי דכתב רחמנא\u0004 \u0005[מדוע כתבה התורה]\u0006 בדין אבידה גם \u0003\"שור\"\u0004 (שם א), גם \u0003\"חמור\"\u0004 (שם ג), גם \u0003\"שה\"\u0004 (שם א) \u0003ו\u0004גם \u0003\"שמלה\"\u0004 (שם ג), מדוע לא היה די בדוגמא אחת בלבד?","והשיב: \u0003צריכי\u0004 \u0005[נצרכו כולם]\u0006 משום שיש בכל אחד מהם צד מיוחד ללמוד ממנו. \u0003דאי כתב רחמנא\u0004 \u0005[שאילו היתה כותבת התורה]\u0006 \u0003שמלה\u0004 בלבד, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים שיש להחזיר אבידה \u0003בעדים דגופה,\u0004 שהעדים מעידים שהם מכירים את האבידה עצמה ויודעים למי היא שייכת, או \u0003סימנין דגופה. אבל\u0004 להחזיר \u0003חמור\u0004 רק \u0003בעדים דאוכף\u0004 או ב\u0003סימנין דאוכף,\u0004 שאין בחמור עצמו סימנים מיוחדים אך תובעים אותו משום שיש סימנים באוכפו, \u0003אימא לא מהדרינן ליה\u0004 \u0005[שמא אין מחזירים אותו],\u0006 שהרי הסימן איננו בגוף החמור, על כן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"חמור\",\u0004 לומר ש\u0003אפילו חמור בסימני\u0004 ה\u0003אוכף\u0004 מחזירים.","וממשיך רבא: \u0003\"שור\" ו\"שה\" דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003למה לי?\u0004 והשיב: \u0003\"שור\"\u0004 — \u0003אפילו לגיזת זנבו,\u0004 שגם אם גזזו שיער מזנבו של שור שנמצא צריך להחזיר את השיער לבעלים, \u0003ושה\u0004 — \u0003לגיזותיו,\u0004 שאת הצמר שגוזזים ממנו יש להשיב לבעלים. ומקשים: \u0003ולכתוב רחמנא\u0004 \u0005[ושתכתוב התורה]\u0006 \u0003\"שור\",\u0004 ונלמד מכאן ש\u0003אפילו לגיזת זנבו\u0004 מחזירים, \u0003וכל שכן\u0004 שמחזירים \u0003שה לגיזותיו,\u0004 שהרי רוב הרווח שיש בצאן הוא מן הצמר, ואין זה רק רווח צדדי כשיער מזנב השור!","\u0003אלא אמר רבא: \"חמור\"\u0004 הכתוב בדיני ה\u0003בור ל\u0004שיטתו של \u0003ר' יהודה\u0004 (שאינו דורש כחכמים, ואינו לומד מדוגמה זו להלכה), \u0003ו\"שה\"\u0004 שכתוב בדיני \u0003אבידה, לדברי הכל קשיא\u0004 \u0005[קשה].\u0006 כלומר, לא מצאנו דרך מספקת להסביר לשם מה נחוצים אלה.","ושואלים: \u0003ואימא\u0004 \u0005[ושמא]\u0006 הדבר הנוסף ללמד שצריך להחזיר את ה\u0003גללים הוא דאתא\u0004 \u0005[שבא]?\u0006 ודוחים: \u0003גללים\u0004 מן הסתם \u0003אפקורי מפקר להו\u0004 \u0005[מפקיר\u0006 הוא \u0005אותם]\u0006 ואין בעל האבידה מקפיד שיאסוף המוצא את כל הגללים שהטילה הבהמה אחריה (אף שיש להם ערך מסויים). ושואלים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 הכתוב הזה \u0003לסימנין הוא דאתא\u0004 \u0005[שבא],\u0006 ללמדנו שמחזירים אבידה בסימנים. \u0003דאיבעיא לן\u0004 \u0005[שנשאלה לנו]\u0006 השאלה הבאה: כשמחזירים אבידה על פי \u0003סימנין,\u0004 האם דבר זה הוא \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003או\u0004 רק \u0003דרבנן\u0004 \u0005[מדברי סופרים].\u0006 ונאמר שעל כן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"שה\"\u0004 שאינו בא ללמד לגופו, והוא מיותר איפוא כדי ללמוד ממנו, ש\u0003אפילו בסימנין מהדרינן\u0004 \u0005[מחזירים אנו]\u0006 ולא רק בעדים, \u0003ו\u0004אם כך נוכיח כי \u0003סימנין דאורייתא\u0004 \u0005[מן התורה\u0006 הם\u0005].\u0006","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בדחיית הסבר זה: \u0003מדקתני להו\u0004 \u0005[מכיון ששנה אותם]\u0006 ה\u0003תנא,\u0004 את ה\u0003סימנין גבי\u0004 \u0005[אצל]\u0006 \u0003שמלה, דקתני\u0004 \u0005[שהרי שנה]:\u0006 \u0003מה שמלה מיוחדת שיש בה סימנין ויש לה תובעין\u0004 — \u0003חייב להכריז, אף כל דבר שיש בו סימנין ויש לו תובעין\u0004 — \u0003חייב להכריז. שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003\"שה\"\u0004 שנאמר \u0003לאו\u0004 \u0005[לא]\u0006 \u0003ל\u0004למדנו לענין \u0003סימנין הוא דאתא\u0004 \u0005[שבא],\u0006 אלא ללמדנו ענין אחר, אבל אנו איננו יודעים מה הוא.","ומביאים עוד מדרש הלכה על אותם הכתובים. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 על מה שנאמר \"וכן תעשה לכל אבידת אחיך אשר תאבד ממנו ומצאתה לא תוכל להתעלם\" (שם ג), דורשים: \u0003\"אשר תאבד\"\u0004 — \u0003פרט לאבידה שאין בה שוה פרוטה,\u0004 שמפני מיעוט ערכה אינה קרויה אבידה כלל ואינה בכלל המצוה. \u0003ר' יהודה אומר: \"ומצאתה\"\u0004 — \u0003פרט לאבידה שאין בה שוה פרוטה,\u0004 שדבר שנמצא ואיננו שווה פרוטה אין בו חובת השבה.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל למעשה \u0005ביניהם]?\u0006 שהרי לכאורה שניהם מסכימים בעיקר הדין שבפחות מפרוטה אין דין השבת אבידה? \u0003אמר אביי:\u0004 אין הבדל ביניהם בהלכה, אלא \u0003משמעות דורשין איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 מאיזה פסוק מוציאים הלכה זו. \u0003מר נפקא ליה\u0004 \u0005[חכם זה,\u0006 חכמים, \u0005יוצא לו],\u0006 לומדים הם את הדבר \u0003מ\"אשר תאבד\", ומר נפקא ליה\u0004 \u0005[וחכם זה,\u0006 ר' יהודה, \u0005יוצא לו,\u0006 הוא לומד\u0005]\u0006 \u0003מ\"ומצאתה\".\u0004","ושואלים: \u0003ולמאן דנפקא ליה\u0004 \u0005[ולמי שיוצא לו,\u0006 לומד\u0005]\u0006 \u0003מ\"אשר תאבד\", האי\u0004 \u0005[זה\u0006 הכתוב\u0005]\u0006 \u0003\"ומצאתה\" מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו],\u0006 מה למד הוא ממנו?","ומשיבים: \u0003ההוא מיבעי ליה\u0004 \u0005[אותו כתוב נצרך לו]\u0006 \u0003ל\u0004כמו שדרשו \u0003רבנאי,\u0004 ש\u0003אמר רבנאי: \"ומצאתה\"\u0004 פירושו — דבר \u0003דאתאי לידיה\u0004 \u0005[שבא לידו]\u0006 ממש \u0003משמע.\u0004","ושואלים עוד: \u0003ולמאן דנפקא ליה\u0004 \u0005[ולמי שיוצא לו\u0006 הדבר\u0005]\u0006 \u0003מ\"ומצאתה\", האי\u0004 \u0005[זה הכתוב]\u0006 \u0003\"אשר תאבד\" מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו]?\u0006","ומשיבים: \u0003מבעי ליה\u0004 \u0005[נצרך הוא לו]\u0006 \u0003ל\u0004כמו שהסביר \u0003ר' יוחנן.\u0004 ש\u0003אמר ר' יוחנן משום\u0004 \u0005[בשם]\u0006 \u0003ר' שמעון בן יוחאי: מניין לאבידה ששטפה נהר שהיא מותרת\u0004 לכל אדם אף על פי שיש בה סימנים? \u0003שנאמר: \"\u0004ו\u0003כן תעשה לכל אבדת אחיך אשר תאבד ממנו ומצאתה\".\u0004 וכך יש להבין: חובת ההשבה היא על \u0003מי שאבודה הימנו\u0004 בלבד \u0003ומצויה אצל כל אדם,\u0004 כלומר, שיכולה להימצא על ידי כל אדם. \u0003יצתה\u0004 (יצאה) \u0003זו\u0004 האבידה שנגרפה על ידי הנהר \u0003שאבודה הימנו ואינה מצויה אצל כל אדם,\u0004 שהרי כרגיל היא טובעת בנהר ולכן היא נעשית הפקר, ואין חובה להחזירה.","ושואלים: \u0003ואידך\u0004 \u0005[האחר],\u0006 \u0003הא\u0004 \u0005[אותה]\u0006 הלכה של \u0003רבנאי מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא לו,\u0006 נלמד הדבר\u0005]\u0006 \u0003מ\"ומצאתה\"\u0004 שנאמרה המלה בתוספת האות וא\"ו, ו־\"ו\" יתירה זו באה ללמד הלכה נוספת זו.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמר \u0003ר' יוחנן מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא לו\u0006 הדבר\u0005]\u0006 ממה שנאמר \u0003\"ממנו\",\u0004 שהוא בא להדגיש ממנו בלבד ולא מכל אדם. ושואלים: \u0003ואידך\u0004 \u0005[והאחר],\u0006 מדוע איננו לומד מכאן? ומשיבים: \u0003\"ממנו\"\u0004 כהדגשה במובן זה \u0003לא משמע ליה\u0004 \u0005[אינה נשמעת לו],\u0006 שאיננו סבור שאפשר לדייק מכאן בלימוד נוסף.","\u0003רבא אמר : פרוטה שהוזלה,\u0004 כלומר, דבר שהיה שווה פרוטה והוזל במחירו \u0003איכא בינייהו\u0004 \u0005[יש\u0006 הבדל \u0005ביניהם]\u0006 בין חכמים ור' יהודה. \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שהלימוד הוא \u0003מ\"אשר תאבד\"\u0004 — \u0003איכא\u0004 \u0005[יש]\u0006 בכך משום אבידה, שהרי בשעת אבידה היה שווה פרוטה. \u0003ומאן דאמר\u0004 \u0005[ומי שאמר]\u0006 \u0003מ\"ומצאתה\"\u0004 — \u0003ליכא\u0004 \u0005[אין]\u0006 בכך משום מציאה, שהרי בשעת מציאה לא היתה שווה פרוטה.","\u0003ו\u0004מקשים: \u0003ו\u0004הלא אף \u0003למאן דאמר\u0004 \u0005[לדעת מי שאומר]\u0006 שהלימוד הוא מ\u0003\"אשר תאבד\"\u0004 — \u0003הא בעינן\u0004 \u0005[הרי צריכים אנו]\u0006 שיהיה \u0003\"ומצאתה\",\u0004 כלומר, שיהא זה דבר בעל ערך הראוי להיקרא מציאה, \u0003וליכא\u0004 \u0005[ו\u0006הלא \u0005אין כאן]!\u0006","\u0003אלא\u0004 יש לומר להיפך: לענין \u0003פרוטה שהוקרה איכא בינייהו\u0004 \u0005[יש\u0006 הבדל \u0005ביניהם],\u0006 \u0003מאן דאמר\u0004 \u0005[מי שאמר]\u0006 ולמד מ\u0003\"ומצאתה\"\u0004 — \u0003איכא\u0004 \u0005[יש\u0006 כאן\u0005]\u0006 חובה, שהרי בזמן מציאה הדבר היה שווה פרוטה, \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 שהלימוד הוא מ\u0003\"אשר תאבד\"\u0004 — \u0003ליכא\u0004 \u0005[אין כאן].\u0006","ומקשים: \u0003ולמאן דאמר\u0004 \u0005[ולדעת מי שאומר]\u0006 שהלימוד הוא מ\u0003\"ומצאתה\", הא בעינן\u0004 \u0005[הרי צריכים אנו]\u0006 גם שיתקיים בו \u0003\"אשר תאבד\" וליכא\u0004 \u0005[ואין כאן],\u0006 וכיוון שבשעת האבידה לא החשיב אותה בעליה, הריהי כהפקר ושייכת למוצא!","\u0003אלא\u0004 יש לומר כי המחלוקת היא ביחס לדבר שהיה שווה \u0003פרוטה שהוקרה והוזלה וחזרה והוקרה איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005].\u0006 \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שהלימוד הוא מ\u0003\"אשר תאבד\"\u0004 — \u0003איכא\u0004 \u0005[יש\u0006 כאן\u0005],\u0006 שהרי גם בשעת האבידה וגם בשעת המציאה היה הדבר שווה פרוטה. ואולם \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שהלימוד הוא מ\u0003\"ומצאתה\"\u0004 — \u0003בעינן דאית בה\u0004 \u0005[צריכים אנו שיהיה בה]\u0006 \u0003שיעור מציאה משעת אבידה ועד שעת מציאה.\u0004 ובמקרה זה, כיון שבמשך זמן מסויים לא היה בחפץ כדי ערך מציאה — אין בו חובת השבת אבידה.","השאלה שהוזכרה קודם בדרך אגב, מובאת עתה לעיקרה ומבררים אותה לפרטיה. \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: זה שמשיבים אבידה אף על פי \u0003סימנין\u0004 ואין צריך דווקא לעדות האם הוא \u0003דאורייתא\u0004 \u0005[מן התורה הם]\u0006 \u0003או\u0004 רק \u0003דרבנן\u0004 \u0005[מדברי חכמים]?\u0006 ושואלים: \u0003מאי נפקא מינה\u0004 \u0005[מה יוצא מזה,\u0006 מה ההבדל למעשה\u0005]?\u0006 הלא גם אם הם מדברי חכמים צריכים להחזיר אבידה בסימנים!"],["ומשיבים: ההבדל למעשה הוא לענין \u0003לאהדורי\u0004 \u0005[להחזיר]\u0006 \u0003גט אשה\u0004 על פי \u0003סימנים. אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שהשבת אבידה על פי סימנים זה \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 — \u0003מהדרינן\u0004 \u0005[מחזירים],\u0006 שהרי התורה אמרה שסימן מועיל, ואולם \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שהשבת אבידה על פי סימנים זה רק \u0003דרבנן\u0004 \u0005[מתקנת חכמים]\u0006 \u0003כי עבוד רבנן תקנתא\u0004 \u0005[כאשר עשו חכמים תקנה]\u0006 עשו זאת \u0003בממונא\u0004 \u0005[בעניני ממונות],\u0006 \u0003אבל באיסורא\u0004 \u0005[ב\u0006דיני \u0005איסורים]\u0006 \u0003לא עבוד רבנן תקנתא\u0004 \u0005[עשו חכמים תקנה],\u0006 שאינם יכולים לתקן ולהפקיע חשש איסור מן התורה.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה ממה ששנינו במשנתנו: \u0003אף השמלה היתה בכלל כל אלו, ולמה יצאת\u0004 (יצאה) מן הכלל להיאמר בכתוב במפורש? — \u0003להקיש\u0004 (להשוות) \u0003אליה\u0004 דברים אחרים, \u0003ולומר לך: מה שמלה מיוחדת שיש לה סימנין ויש לה תובעין חייב להכריז, אף כל דבר שיש לו סימנין ויש לו תובעין חייב להכריז.\u0004 הרי שסימנים מן התורה! ודוחים: ה\u0003תנא\u0004 עיקר דבריו וחידושו לענין \u0003תובעין אצטריכא ליה\u0004 \u0005[הוצרך לו\u0006 לומר\u0005],\u0006 ואילו \u0003סימנין כדי נסבא\u0004 \u0005[רק הביא],\u0006 שאת הסימנים הזכיר רק בדרך אגב, מאחר שמדברי חכמים מחזירים בסימנים. אבל הלימוד מן התורה הוא לגבי תובעים בלבד.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו בהמשך שמחזירים \u0003חמור בסימני אוכף.\u0004 הרי שסימנים מן התורה! ושוב דוחים: \u0003אימא\u0004 \u0005[אמור]\u0006 ותקן בלשון: לא \"בסימני אוכף\" אלא \u0003\"בעדי אוכף\",\u0004 כלומר, שמביא עדים שהאוכף שייך לו.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו בברייתא: נאמר בתורה \u0003\"והיה עמך עד דרש אחיך אתו\"\u0004 (דברים כב, ב) ואמרו חכמים: \u0003וכי תעלה על דעתך שיתננו לו קודם שידרשנו,\u0004 הרי איננו יודע מיהו! \u0003אלא\u0004 הכוונה שאתה צריך לדרוש ולחקור אותו, כלומר, \u0003דרשהו אם רמאי הוא או אינו רמאי.\u0004","ומדייקים: \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה שיבדוק אותו \u0003בסימנים\u0004 שהוא נותן אם הם סימנים ראויים! ודוחים: \u0003לא,\u0004 הכוונה היא בעדים, שיבדוק אם העדים אינם משקרים.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת: \u0003אין מעידין\u0004 על אדם שמת כדי להתיר לאשתו להינשא, \u0003אלא על פרצוף הפנים עם החוטם\u0004 שראו העדים והכירוהו, \u0003אף על פי שיש סימנין\u0004 אחרים \u0003בגופו ובכליו\u0004 (בגדיו) אין סומכים עליהם.","\u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003סימנין לאו דאורייתא\u0004 \u0005[אינם מן התורה]\u0006 שהרי אין סומכים עליהם בענין זה של איסור! \u0003אמרי\u0004 \u0005[אומרים]\u0006 ודוחים: משם אין ראיה, שכן שם מדובר כשהסימנים הם בלתי מובהקים שאין לסמוך עליהם, סימנים שב\u0003גופו\u0004 כגון שהוא \u0003ארוך\u0004 או שהוא \u0003גוץ.\u0004 ולענין סימנים של \u0003כליו\u0004 אין סומכים עליהם משום \u0003דחיישינן\u0004 \u0005[שאנו חוששים]\u0006 \u0003לשאלה,\u0004 שמא המת שאל אותם מבעליהם, ואינם שלו.","ומקשים: \u0003אי חיישינן\u0004 \u0005[אם חוששים אנו]\u0006 \u0003לשאלה,\u0004 אם כן \u0003חמור בסימני אוכף היכי מהדרינן\u0004 \u0005[איך אנו מחזירים]?\u0006 \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003אוכף, לא שאולי אינשי אוכפא\u0004 \u0005[אין משאילים אנשים אוכף]\u0006 \u0003משום דמסקב ליה לחמרא\u0004 \u0005[שפוצע את החמור]\u0006 כי האוכף צריך להיות בדיוק לפי מידתו.","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 ותדחה באופן אחר: \u0003כליו\u0004 שנתנו בהם רק סימנים כלליים, כלומר \u0003בחיורי ובסומקי\u0004 \u0005[בלבנים ובאדומים].\u0006","ומקשים: \u0003אלא הא דתניא\u0004 \u0005[זו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003מצאו\u0004 השליח את הגט שאבד ממנו \u0003קשור בכיס או בארנקי ובטבעת, או שמצאו בין כליו, אפילו לזמן מרובה\u0004 לאחר האבידה — \u0003כשר. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר כי \u0003חיישינן לשאלה\u0004 \u0005[חוששים אנו להשאלה],\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003מצאו קשור בכיס אמאי\u0004 \u0005[מדוע]\u0006 \u0003כשר? ניחוש\u0004 \u0005[נחשוש]\u0006 \u0003לשאלה!\u0004","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003כיס וארנקי וטבעת לא משאלי אינשי\u0004 \u0005[משאילים אנשים].\u0006 \u0003כיס וארנקי\u0004 — הטעם \u0003משום\u0004 שרואים בהם ענין של \u0003מסמני\u0004 \u0005[סימן וניחוש],\u0006 שהאדם המוסר את כיסו וארנקו לאחר כמי שמסר לו את מזלו. \u0003וטבעת\u0004 — \u0003משום\u0004 שיש חשש \u0003דמזייף\u0004 \u0005[לזיוף],\u0006 שבטבעת היה כרגיל מצוי החותם, ואין אדם משאיל לחבירו את חותמו.","ומציעים: \u0003לימא כתנאי\u0004 \u0005[האם נאמר\u0006 שנושא זה שנוי \u0005במחלוקת תנאים]\u0006 שכבר נחלקו בו. שכן שנינו בדיני עדות על המת: \u0003אין מעידין על השומא\u0004 (יבלת) שנמצאת בגוף המת שנמצא, שדבר זה אינו מספיק לסמוך עליו להתיר את אשתו. \u0003ואלעזר בן מהבאי אומר: מעידין על השומא. מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא ב\u0006נושא \u0005זה נחלקו];\u0006 שה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]:\u0006 \u0003סימנין דרבנן\u0004 \u0005[מדברי חכמים],\u0006 ולכן אין סומכים על השומא, \u0003ו\u0004אילו \u0003אלעזר בן מהבאי סבר\u0004 \u0005[סבור]:\u0006 \u0003סימנין דאורייתא\u0004 \u0005[מן התורה]!\u0006","\u0003אמר רבא,\u0004 אפשר לדחות ולומר: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003סימנין דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003ו\u0004אולם \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003ב\u0004שאלה האם \u0003שומא מצויה בבן גילו קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 האם אפשר לחשוש שיש אדם אחר, בן גילו ומזלו של המת, ואף בו מצוי סימן זה או לא. \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 תנא קמא, \u0005סבור]:\u0006 \u0003שומא מצויה בבן גילו, ומר סבר\u0004 \u0005[וחכם זה,\u0006 אלעזר בן מהבאי, \u0005סבור]:\u0006 \u0003שומא אינה מצויה בבן גילו.\u0004","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 אפשרות אחרת לדחות: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003שומא אינה מצויה בבן גילו, והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004שאלה אם \u0003סימנין העשוין להשתנות לאחר מיתה קמיפלגי\u0004 \u0005[חלוקים הם];\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 חכמים, \u0005סבור]\u0006 ש\u0003סימנין עשוים להשתנות לאחר מיתה,\u0004 ויתכן שנשתנה גודל או צבע השומא, ולכן אינה יכולה לשמש עוד כסימן. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 אלעזר בן מהבאי, \u0005סבור]:\u0006 \u0003סימנין אין עשויים להשתנות לאחר מיתה.\u0004","ועוד, \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003שומא אינה עשויה להשתנות לאחר מיתה, וסימנין\u0004 לדעת הכל הם \u0003דרבנן\u0004 \u0005[מדברי חכמים],\u0006 אלא \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003ב\u0004שאלה האם \u0003שומא סימן מובהק הוא קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 \u0003מר סבר\u0004 \u0005[חנם זה,\u0006 אלעזר בן מהבאי, \u0005סבור]\u0006 ש\u0003שומא סימן מובהק הוא,\u0004 שאין בו אפשרות לטעות או לכפילות, ולכן אפשר לסמוך עליו בשלימות אפילו אין השימוש בסימנים מפורש בתורה, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים, \u0005סבור]:\u0006 \u0003שומא לאו\u0004 \u0005[אין]\u0006 \u0003סימן מובהק הוא.\u0004","בהמשך לדיון שהובא כאן \u0003אמר רבא: אם תמצי\u0004 \u0005[תרצה]\u0006 \u0003לומר\u0004 כי \u0003סימנין לאו דאורייתא\u0004 \u0005[אינם מן התורה],\u0006 אם כן \u0003היכי מהדרינן אבידתא\u0004 \u0005[כיצד מחזירים אבידה]\u0006 \u0003בסימנין?\u0004 שהרי יתכן שאין בסימנים משום הוכחה ומוסרים רכושו של אדם אחר למישהו שאינו זכאי לו! והתשובה היא שיש לראות בכך הסכמה כללית, \u0003דניחא ליה\u0004 \u0005[שנוח לו]\u0006 \u0003למוצא אבידה דנהדר\u0004 \u0005[שיחזיר]\u0006 \u0003בסימנין,\u0004 והוא מוכן לוותר על זכותו במציאה אם יתנו לו סימנים, \u0003כי היכי דכי אבדה לדידה נמי נהדרו ליה\u0004 \u0005[שכאשר תאבד לו עצמו אבידה גם כן יחזירו לו]\u0006 \u0003בסימנין.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ספרא לרבא: וכי אדם עושה טובה לעצמו בממון שאינו שלו?\u0004 כלומר, כיצד אתה יכול לתלות את ההיתר בכך שמוצא האבידה מוכן להחזיר על פי סימנים, והלא החפץ איננו שייך לו, וכיצד הוא יכול לעשות לגביו הסכמים?!","\u0003אלא\u0004 יש להסביר באופן שונה במקצת: \u0003ניחא ליה\u0004 \u0005[נוח לו]\u0006 \u0003לבעל\u0004 ה\u0003אבידה\u0004 עצמו \u0003למיהב\u0004 \u0005[לתת]\u0006 \u0003סימנין ולמשקליה\u0004 \u0005[ולקחת אותה,\u0006 את אבידתו\u0005]\u0006 ולא להזדקק להוכחות מושלמות יותר. שכן \u0003מידע ידע\u0004 \u0005[יודע הוא]\u0006 ש\u0003עדים לית ליה\u0004 \u0005[אין לו],\u0006 \u0003ומימר אמר\u0004 \u0005[ואומר\u0006 בעצמו\u0005]:\u0006 \u0003כולי עלמא לא ידעי\u0004 \u0005[הכל אינם יודעים]\u0006 \u0003סימנין מובהקים דידה\u0004 \u0005[שלה],\u0006 \u0003ואנא יהיבנא\u0004 \u0005[ואני אתן]\u0006 \u0003סימנין מובהקים דידה\u0004 \u0005[שלה]\u0006 \u0003ושקלנא לה\u0004 \u0005[ואקח אותה],\u0006 ונוח לו להסכים לסידור כללי שיבדקו את זהות הבעלים על פי הסימנים, שהרי סבור הוא שבוודאי יודע סימנים יותר מאחרים.","ושואלים: \u0003אלא הא דתנן\u0004 \u0005[זו ששנינו\u0006 במשנה\u0005]\u0006 \u0003רבן שמעון בן גמליאל אומר:\u0004 מצא שלושה שטרות והיו אלה שטרות של \u0003אחד הלוה משלשה\u0004 — \u0003יחזיר ללוה,\u0004 ואם היו שטרות של \u0003שלשה שלוו מן האחד\u0004 — \u0003יחזיר למלוה.\u0004 ואם ענין זה של השבת אבידה בסימנים תלוי במעין הסכמה כללית, וכי \u0003ניחא ליה\u0004 \u0005[נוח לו]\u0006 \u0003ללוה לאהדורי ליה\u0004 \u0005[להחזיר לו]\u0006 את השטרות \u0003למלוה?\u0004 מוטב לו שלא יסמכו על הסימנים ולא יחזירו!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003סברא הוא,\u0004 ובגללה אנו מחזירים, ולא משום סימנים בלבד. כי \u0003אחד הלוה משלשה יחזיר ללוה\u0004 — \u0003דגבי\u0004 \u0005[שאצל]\u0006 ה\u0003לוה שכיחי\u0004 \u0005[מצויים]\u0006 שיהיו בידו שלושה שטרות שחייב היה לשלושה אנשים, ואילו \u0003גבי\u0004 \u0005[אצל]\u0006 ה\u0003מלוה לא שכיחי\u0004 \u0005[מצויים]\u0006 שטרות של אחרים, ולכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי ודאי \u0003מלוה נפול\u0004 \u0005[נפלו].\u0006 ולהיפך, \u0003שלשה שלוו מאחד יחזיר למלוה\u0004 — \u0003דגבי\u0004 \u0005[שאצל]\u0006 ה\u0003מלוה שכיחי\u0004 \u0005[מצויים]\u0006 שלושה שטרות של אנשים שונים שלוו ממנו, ואילו \u0003גבי\u0004 \u0005[אצל]\u0006 ה\u0003לוה לא שכיחי\u0004 \u0005[מצויים]\u0006 שטרות של אחרים, ולכן אין מסתבר ששלו הם."],["\u0003אלא הא דתנן\u0004 \u0005[זו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003מצא תכריך של שטרות או אגודה של שטרות\u0004 — \u0003הרי זה יחזיר\u0004 למי שהשטרות נכתבו עבורו, \u0003הכי נמי דניחא ליה\u0004 \u0005[כאן גם כן\u0006 תאמר \u0005שנוח לו]\u0006 \u0003ללוה לאהדורי ליה\u0004 \u0005[להחזיר לו]\u0006 \u0003למלוה?\u0004","\u0003אלא\u0004 ודאי אין הדבר תלוי בכך. וחזר בו, ו\u0003אמר רבא: סימנין דאורייתא\u0004 \u0005[מן התורה הם],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והיה עמך עד דרש אחיך אתו\"\u0004 (דברים כב, ב), \u0003וכי תעלה על דעתך שיתננו קודם שידרשנו? אלא דרשהו\u0004 (בדוק אותו) \u0003אם רמאי הוא או אינו רמאי. לאו\u0004 \u0005[וכי לא]\u0006 \u0003בסימנין?\u0004 וסיכם \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003אמר רבא: אם תמצי\u0004 \u0005[תרצה]\u0006 \u0003לומר סימנין דאורייתא\u0004 \u0005[מן התורה].\u0006 לפני שניגשים לבירור דברי רבא תוהים על שימוש הלשון שלו, מדוע אומר הוא \u0003אם תמצי לומר?! הא פשיט ליה\u0004 \u0005[הרי כבר פתר אותה]\u0006 את הבעיה, והחליט כי \u0003סימנין דאורייתא\u0004 \u0005[מן התורה]!\u0006 ומשיבים: \u0003משום דאיכא למימר כדשנינן\u0004 \u0005[שאפשר היה לומר\u0006 ולפרש שם \u0005כפי שתירצנו],\u0006 ואף שהתירוצים הללו אינם נראים לרבא כשלעצמם, מכל מקום אינו בא לדון כעת בענין, ודבריו נכונים אפילו לפי השיטה שסימנים הם מדברי סופרים בלבד.","אם היו \u0003סימנין וסימנין,\u0004 כלומר, שני אנשים שנתנו סימנים שווים — \u0003יניח\u0004 את החפץ ולא יתננו לא לזה ולא לזה. היו \u0003סימנין ועדים\u0004 — \u0003ינתן לבעל העדים,\u0004 שעדות עדים שהחפץ שייך לאדם מסויים לכל הדעות עדיפה מסתם סימנים. \u0003סימנין וסימנין ועד אחד\u0004 מסייע לאחד מהם — \u0003עד אחד כמאן דליתיה דמי\u0004 \u0005[כמי שאיננו נחשב],\u0006 שהרי מעד אחד אין מביאים ראיה בהלכה, ואם כן תלוי הדבר בסימנים, \u0003ויניח.\u0004","\u0003עדי אריגה ועדי נפילה,\u0004 שהיו עדים המעידים שהבגד נארג עבור אדם מסויים, ועדים אחרים מעידים שהבגד נפל מאחר — \u0003תנתן ל\u0004זה שיש לו \u0003עדי נפילה, דאמרינן\u0004 \u0005[שאומרים אנו]\u0006 \u0003זבוני זבנה\u0004 \u0005[מכר אותה]\u0006 האיש שארגה, \u0003ומאיניש אחרינא נפל\u0004 \u0005[ומאדם אחר נפלה].\u0006","אחד שנתן כסימן את \u0003מדת ארכו\u0004 של בגד \u0003ו\u0004אחד נתן את \u0003מדת רחבו\u0004 — \u0003תנתן ל\u0004זה שנתן \u0003מדת ארכו,\u0004 ש\u0003מדת רחבו שעורי קא משער לה כד מכסי לה מרה וקאי\u0004 \u0005[יכול הוא לשער כאשר מתכסה בה בעליה\u0006 של הגלימה \u0005ועומד],\u0006 \u0003ו\u0004אילו \u0003מדת ארכו לא משתער לה\u0004 \u0005[אי אפשר לשער כך],\u0006 ולכן הוא סימן מובהק יותר.","אחד נתן כסימן \u0003מדת ארכו ומדת רחבו ו\u0004אחר אומר \u0003מדת גמיו,\u0004 שיודע רק את סכום האורך והרוחב יחד אבל אינו יכול לפרט — \u0003ינתן ל\u0004מי שנתן \u0003מדת ארכו ורחבו.\u0004","אחד נתן \u0003מדת ארכו ומדת רחבו ו\u0004אחר נתן \u0003מדת משקלותיו\u0004 — \u0003ינתן למדת משקלותיו,\u0004 שדבר זה קשה לנחש, ומן הסתם רק בעל הבגד יודע את משקלו.","ואם היה הדבר בגט שאבד, ולא ברור אם נפל מן הבעל לפני הגירושין או מן האשה אחר כך, \u0003הוא\u0004 הבעל, \u0003אומר\u0004 את \u0003סימני הגט והיא אומרת\u0004 את \u0003סימני הגט\u0004 — \u0003ינתן\u0004 הגט \u0003לה.\u0004 ושואלים: \u0003במאי\u0004 \u0005[במה],\u0006 באיזה סימנים מדובר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שנתנה סימנים \u0003במדת ארכו ורחבו\u0004 — אין זה סימן מוכיח, \u0003דלמא בהדי דנקיט ליה חזיתיה\u0004 \u0005[שמא בתוך הזמן שהחזיק\u0006 הבעל \u0005אותו,\u0006 את הגט \u0005ראתה אותו]\u0006 ועדיין לא מסרו הבעל, ואיבד את הגט קודם מסירה. \u0003אלא\u0004 מה הסימן? — שאומרת \u0003נקב יש בו\u0004 בגט \u0003בצד אות פלוני,\u0004 שבודאי לא היתה האשה יודעת זאת אם לא היה הגט בידה.","וכן, \u0003הוא אומר סימני החוט\u0004 שקשור בו הגט, \u0003והיא אומרת סמני החוט\u0004 — \u0003ינתן\u0004 הגט \u0003לה.\u0004 ושואלים: \u0003במאי\u0004 \u0005[במה]?\u0006 \u0003אילימא בחיורא ובסומקא\u0004 \u0005[אם תאמר\u0006 סימן כגון חוט \u0005לבן\u0006 או \u0005חוט אדום],\u0006 \u0003ודלמא בהדי דנקיט ליה חזיתיה\u0004 \u0005[ושמא בתוך הזמן שהחזיק אותו ראתה אותו]?\u0006 \u0003אלא\u0004 שנותנת סימן \u0003במדת ארכו\u0004 של החוט.","\u0003הוא אומר\u0004 הגט היה מונח \u0003בחפיסה והיא אומרת בחפיסה\u0004 — \u0003ינתן לו, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003מידע ידעה\u0004 \u0005[יודעת היא]\u0006 ש\u0003כל מה דאית ליה\u0004 \u0005[שיש לו]\u0006 \u0003בחפיסה הוא דמנח ליה\u0004 \u0005[שמניח אותו]\u0006 ולכן מנחשת ששם היה.","\u0003ועד מתי חייב להכריז\u0004 על האבידה? — \u0003עד כדי שידעו בו שכניו,\u0004 אלו \u0003דברי רבי מאיר. רבי יהודה אומר:\u0004 מכריז \u0003שלש רגלים, ואחר הרגל האחרון\u0004 עוד \u0003שבעה ימים, כדי\u0004 הזמן \u0003שילך\u0004 האיש \u0003לביתו שלשה\u0004 ימים לבדוק שאכן החפץ אבד ממנו, \u0003ויחזור שלשה\u0004 ימים לירושלים, \u0003ויכריז יום אחד\u0004 שאבד חפץ, ובאותו הזמן יוכל למצוא גם את המוצא.","שנינו במשנה כדי שידעו בו שכניו. בתוספתא \u0003תנא\u0004 \u0005[שנה]:\u0006 \u0003שכני אבידה.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה פירוש]\u0006 \u0003שכני אבידה? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003שכינים\u0004 של \u0003בעל\u0004 ה\u0003אבידה?\u0004 אולם \u0003אי ידע ליה ליזול ולהדריה נהליה\u0004 \u0005[אם\u0006 הוא \u0005יודע מי הוא\u0006 בעל האבידה \u0005שילך ויחזיר לו],\u0006 ולמה לו להכריז? \u0003אלא\u0004 הכוונה היא \u0003שכני מקום שנמצאת בו אבידה.\u0004","שנינו במשנה, ש\u0003ר' יהודה אומר:\u0004 שלוש רגלים ועוד אחרי הרגל שבעה ימים שיוכל ללכת שלושה ימים לביתו.","\u0003ורמינהו\u0004 \u0005[ומשליכים, מראים סתירה]\u0006 ממה ששנינו: \u0003בשלשה במרחשון שואלין\u0004 (מבקשים) בתפילה \u0003את הגשמים,\u0004 שאז מתחילה העונה שראוי להתפלל בה על הגשם. \u0003רבן גמליאל אומר: בשבעה בו, שהוא חמישה עשר יום אחר החג\u0004 (חג הסוכות), \u0003כדי שיגיע אחרון שבארץ ישראל\u0004 שעלה לרגל עד \u0003נהר פרת\u0004 שהוא גבול ארץ ישראל. נמצא שלהגיע עד קצה גבול ארץ ישראל לוקח חמישה עשר יום ולא שלושה!","\u0003אמר רב יוסף: לא קשיא\u0004 \u0005[אין זה קשה];\u0006 \u0003כאן\u0004 — \u0003במקדש\u0004 ה\u0003ראשון, כאן\u0004 — \u0003במקדש\u0004 ה\u0003שני.\u0004 כיצד?","\u0003במקדש ראשון, דנפישי ישראל טובא\u0004 \u0005[כשהיו ישראל מרובים מאד]\u0006 \u0003דכתיב בהו\u0004 \u0005[שנאמר בהם]\u0006 \u0003\"יהודה וישראל רבים כחול אשר על הים לרב\"\u0004 (מלכים א' ד, כ) — \u0003בעינן כולי האי\u0004 \u0005[צריכים אנו\u0006 זמן \u0005רב כל כך]\u0006 משום שהיישוב היהודי היה מתפשט רחוק מאוד, \u0003במקדש שני\u0004 ש\u0003לא נפישי ישראל טובא\u0004 \u0005[היו מרובים ישראל הרבה],\u0006 \u0003דכתיב בהו\u0004 \u0005[שנאמר בהם]\u0006 בשעת העליה בימי כורש \u0003\"כל הקהל כאחד ארבע רבוא אלפים שלש מאות ששים\"\u0004 (עזרא ב, סה) — \u0003לא בעינן כולי האי\u0004 \u0005[אין אנו צריכים כל כך הרבה]\u0006 ובשלושה ימים מגיע לכל מקום.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: והא כתיב\u0004 \u0005[והרי נאמר]\u0006 בעליה של ימי בית שני \u0003\"וישבו הכהנים והלוים\u0004 ומן העם \u0003והמשררים והשוערים\u0004 והנתינים בעריהם \u0003וכל ישראל בעריהם\"\u0004 (שם ע), וכיוון שישבו בעריהם שהיו להם כאחוזת האבות משמע שהיו מפוזרים בכל מקומות ישובים הקודמים,","\u0003וכיון דהכי\u0004 \u0005[שכך]\u0006 \u0003הוא\u0004 — \u0003אפכא מסתברא\u0004 \u0005[ההיפך מסתבר]:\u0006 ב\u0003מקדש ראשון, דנפישי ישראל טובא\u0004 \u0005[שהיו ישראל מרובים הרבה],\u0006 \u0003דמצוות עלמא\u0004 \u0005[שהאנשים בצוותא],\u0006 \u0003ומשתכחי שיירתא דאזלי בין ביממא ובין בליליא\u0004 \u0005[ומוצאים שיירות ההולכות בין ביום ובין בלילה]\u0006 ששטח הארץ כולו מיושב — \u0003לא בעינן כולי האי\u0004 \u0005[אין אנו צריכים כל כך הרבה]\u0006 זמן, \u0003וסגי בתלתא יומא\u0004 \u0005[ודי בשלושה ימים]\u0006 כדי להגיע עד קצה הגבול. ואילו ב\u0003מקדש שני, דלא נפישי ישראל טובא\u0004 \u0005[שאין ישראל מרובים],\u0006 \u0003ולא מצוות עלמא\u0004 \u0005[ואין האנשים בצוותא],\u0006 \u0003ולא משתכחי שיירתא דאזלי\u0004 \u0005[מצויות שיירות שהולכות]\u0006 \u0003בין ביממא\u0004 \u0005[היום]\u0006 \u0003ובין בליליא\u0004 \u0005[בלילה]\u0006 — \u0003בעינן כולי האי\u0004 \u0005[צריכים אנו כל כך הרבה]\u0006 כלומר, חמישה עשר יום.","\u0003רבא אמר\u0004 מעיקרו של דבר אין כאן סתירה: \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 \u0003במקדש\u0004 ה\u0003ראשון ולא שנא\u0004 \u0005[ואינו שונה]\u0006 \u0003במקדש שני,\u0004 אין שינוי בהלכה, אלא אין הדברים דומים זה לזה; כי \u0003לא הטריחו רבנן\u0004 \u0005[חכמים]\u0006 \u0003באבדה יותר מדאי,\u0004 שלא הטריחו חכמים את המוצא שיחכה זמן רב כל כך עד שיוכל כל אדם ואדם לחזור, גם אם הוא רחוק ביותר.","מתוך הדברים שאמרנו \u0003אמר רבינא: שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003מכריז\u0004 המוצא מה מצא, אינו אומר סתם אבידה מצאתי, אלא \u0003\"\u0004מצאתי \u0003גלימא\"\u0004 במפורש הוא \u0003מכריז. דאי סלקא דעתך \"אבידתא\"\u0004 \u0005[אם עולה על דעתך\u0006 לומר ש\u0005\"אבידה\"\u0006 בלבד\u0005]\u0006 הוא \u0003מכריז, בעינן למטפי ליה חד יומא לעיוני במאניה\u0004 \u0005[צריכים להוסיף לו\u0006 למאבד עוד \u0005יום\u0006 כדי \u0005לחפש בכליו]\u0006 ולראות אם איבד דבר מה, ומה הדבר שאיבד. \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]:\u0006 כי \u0003גלימא מכריז,\u0004 ויכול אדם לגלות מיד אם איבד או לא איבד. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן].\u0006","ואילו \u0003רבא אמר:\u0004 מכאן אין הוכחה, \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 כי \u0003\"אבידתא\"\u0004 \u0005[\"אבידה\"]\u0006 הוא \u0003מכריז, לא הטריחו רבנן\u0004 \u0005[חכמים]\u0006 \u0003באבידה יותר מדאי.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 כשמכריז ב\u0003רגל\u0004 ה\u0003ראשון, אומר: רגל ראשון\u0004 הוא זה שאני מכריז בו. כשמכריז ב\u0003רגל שני אומר: רגל שני\u0004 אני מכריז, כשמכריז ב\u0003רגל שלישי אומר סתם,\u0004 ואינו אומר איזה רגל הוא.","ושואלים: \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003לימא\u0004 \u0005[שיאמר]\u0006 \u0003רגל שלישי!\u0004 ומשיבים: ש\u0003לא אתי לאחלופי\u0004 \u0005[יבוא להתחלף]\u0006 \u0003בשני,\u0004 שמא לא ישמע המאבד את קול הכרוז כראוי, ויחשוב שהוא מכריז \"שני\", ויסבור שיש בידו עוד רגל אחד, ואחר כך יתברר שהמוצא אינו חוזר עוד. ושואלים: אם כך שיש אפשרות לטעות — שמיעה כזו ברגל \u0003שני נמי\u0004 \u0005[גם כן],\u0006"],["\u0003אתיא לאחלופי\u0004 \u0005[יבוא להחליף]\u0006 \u0003בראשון,\u0004 שיחשוב שהוא מכריז רגל ראשון! ומשיבים: אמנם ייתכן שטעה, אולם דבר זה לא יכול לגרום נזק \u0003הא קא אתי\u0004 \u0005[הרי\u0006 המוצא \u0005יבוא]\u0006 גם ב\u0003רגל שלישי.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בראשונה, כל מי שמצא אבידה היה מכריז עליה שלשה רגלים, ואחר רגל אחרון שבעה ימים, כדי שילך\u0004 המאבד \u0003שלשה ויחזור שלשה ויכריז יום אחד. משחרב בית המקדש\u0004 (ומוסיפים: \u0003שיבנה במהרה בימנו), התקינו שיהו מכריזים בבתי כנסיות ובבתי מדרשות,\u0004 שהרי אין מקום שכל ישראל באים בו. \u0003ומשרבו האנסים התקינו שיהו מודיעין לשכיניו ולמיודעיו ודיו\u0004 בכך.","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003משרבו האנסין?\u0004 ומשיבים: \u0003דאמרי\u0004 \u0005[שאומרים]\u0006 שעל פי חוק הגויים \u0003אבידתא למלכא\u0004 \u0005[האבידה\u0006 שייכת \u0005למלך],\u0006 ולכן יש לחשוש שאם יכריז ברבים יחרימו השלטונות את המציאה. מסופר: \u0003רבי אמי אשכח אודייא דדינרי\u0004 \u0005[מצא כלי מלא דינרים],\u0006 \u0003חזייה ההוא רומאה דקא מירתת\u0004 \u0005[ראה אותו רומאי אחד שהוא מפחד].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל שקול לנפשך\u0004 \u0005[לך קח לעצמך]\u0006 \u0003דלאו פרסאי אנן דאמרי אבידתא למלכא\u0004 \u0005[שאין אנו פרסיים האומרים שהאבידה\u0006 שייכת \u0005למלך].\u0006","ועוד מספרים במנהגי השבת אבידה בזמן הבית. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אבן טוען היתה בירושלים\u0004 ומה היה תפקידה? \u0003כל מי שאבדה לו אבידה נפנה לשם\u0004 ששם היה מקום ההכרזה, \u0003וכל מי שמוצא אבידה נפנה לשם. זה עומד ומכריז\u0004 שמצא, \u0003וזה עומד ונותן סימנין ונוטלה.\u0004 ואבן זו עמדה במקום מוגדר בעיר, \u0003וזו היא ששנינו\u0004 בענין אחר: \u0003צאו וראו אם נמחת אבן הטוען,\u0004 שזו היא האבן המוזכרת שם.","\u0003אמר\u0004 הטוען לבעלות על האבידה \u0003את האבידה,\u0004 שאמר מה החפץ שאבד \u0003ולא אמר סימניה\u0004 — \u0003לא יתן לו. והרמאי, אף על פי שאמר סימניה\u0004 — \u0003לא יתן לו, שנאמר: \"עד דרש אחיך אתו\"\u0004 (דברים כב, ב), ופירשוהו: \u0003עד שתדרוש את אחיך\u0004 ותחקור \u0003אם רמאי הוא\u0004 או \u0003אם אינו רמאי.\u0004","\u0003אתמר\u0004 \u0005[נאמר]\u0006 שחלקו אמוראים בשאלה זו, \u0003רב יהודה אמר: \"אבידתא\u0004 \u0005[אבידה]\u0006 מצאתי \u0003\"\u0004\u0003מכריז, ורב נחמן אמר:\u0004 למשל \u0003\"גלימא\u0004 מצאתי \u0003מכריז\".\u0004 ומסבירים את טעמיהם.","\u0003רב יהודה אמר: \"אבידתא\" מכריז, דאי אמרת\u0004 \u0005[שאם אומר אתה]\u0006 ש\u0003\"גלימא\" מכריז\u0004 — \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003לרמאי,\u0004 שמא נודע לרמאי שאיבד חבירו אבידה זו, ויחקור וידרוש מה היו סימניה ויבוא ויתן בה סימנים ויקח אותה.","\u0003רב נחמן אמר: \"גלימא\" מכריז, ולרמאי לא חיישינן\u0004 \u0005[אין אנו חוששים],\u0006 ש\u0003אם כן אין לדבר סוף,\u0004 שהרי גם אם מכריז אבידה, שמא ינסה הרמאי לנחש מה היתה האבידה.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003אמר את האבידה ולא אמר את סימניה\u0004 — \u0003הרי זה לא יתן לו.\u0004 ומעתה, \u0003אי אמרת בשלמא \"אבידתא\"\u0004 \u0005[נניח אם אומר אתה\u0006 ש\u0005\"אבידה\"]\u0006 הוא \u0003מכריז, הא קא משמע לן\u0004 \u0005[הרי זה השמיע לנו]\u0006 במשנה, \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003אמר \"גלימא\"\u0004 איבדתי, \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003לא אמר סימנין לא מהדרינן ליה\u0004 \u0005[אין אנו מחזירים לו].\u0006 \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי \u0003\"גלימא\" מכריז, אמר איהו\u0004 \u0005[אומר הוא]\u0006 המוצא שמצא \u0003גלימא, ואמר איהו\u0004 \u0005[ואומר הוא]\u0006 שאיבד \u0003גלימא, צריכא למימר כי\u0004 \u0005[האם צריך לומר שכאשר]\u0006 \u0003לא אמר סימנין לא מהדרינן ליה\u0004 \u0005[אין מחזירים לו]?\u0006","\u0003אמר רב ספרא:\u0004 מכאן אין להוכיח, ו\u0003לעולם\u0004 אפשר לומר כי \u0003\"גלימא\" מכריז,\u0004 אלא \u0003אמר איהו\u0004 \u0005[הוא]\u0006 המוצא שמצא \u0003גלימא, ואמר איהו\u0004 \u0005[הוא הטוען]\u0006 \u0003סימנין. ומאי\u0004 \u0005[ומה פירוש]\u0006 \u0003לא אמר את סימניה\u0004 — \u0003לא אמר סימנין מובהקין דידה\u0004 \u0005[שלה],\u0006 ולכן יש חשש שאין הוא בעל האבידה.","שנינו במשנה: \u0003והרמאי אף על פי שאמר את סימניה\u0004 — \u0003הרי זה לא יתן לו. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בראשונה, כל מי שאבדה לו אבידה\u0004 — \u0003היה נותן סימנין ונוטלה. משרבו הרמאין\u0004 שהיו מגלים מפי המאבד מה איבד ונוטלים, \u0003התקינו שיהו אומרים לו: צא והבא עדים דלאו\u0004 \u0005[שלא]\u0006 \u0003רמאי את\u0004 \u0005[אתה]\u0006 \u0003וטול.\u0004","ומספרים דרך אגב \u0003כי הא\u0004 \u0005[כמו זה]\u0006 שאירע \u0003דאבוה\u0004 \u0005[שאביו]\u0006 של \u0003רב פפא אירכס ליה חמרא ואשכחוה\u0004 \u0005[אבד לו חמור ומצאוהו].\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רבה בר רב הונא, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל אייתי סהדי דלאו\u0004 \u0005[לך הבא עדים שלא]\u0006 \u0003רמאי את\u0004 \u0005[אתה],\u0006 \u0003וטול\u0004 את האבידה, שהרי נתת את הסימנים. \u0003אזל אייתי סהדי\u0004 \u0005[הלך והביא עדים],\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 רבה בר רב הונא לעדים: \u0003ידעיתון ביה\u0004 \u0005[יודעים אתם בו]\u0006 ש\u0003רמאי הוא? אמרו ליה\u0004 \u0005[לו]\u0006 העדים: \u0003אין\u0004 \u0005[כן].\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 אביו של רב פפא בהתמרמרות: \u0003אנא רמאה אנא\u0004 \u0005[אני רמאי אני]?!\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אנן\u0004 \u0005[אנו]\u0006 \u0003\"לאו\u0004 \u0005[לא]\u0006 \u0003רמאי את\" קאמרינן\u0004 \u0005[אתה אמרנו],\u0006 כלומר, התבלבלנו בדברים, שהיה נדמה להם ששאל כרגיל אם יודעים בו שאינו רמאי. \u0003אמר רבה בר רב הונא: מסתברא, לא מייתי איניש חובתא לנפשיה\u0004 \u0005[מסתבר שאין מביא אדם חובה לעצמו],\u0006 ואף על פי שענו העדים שלא כהוגן יש להניח שנתבלבלו, ולא לומר שחזרו בהם מעדותם הראשונה.","\u0003כל דבר\u0004 בעל חיים שמצא \u0003ש\u0004הוא \u0003עושה\u0004 מלאכה \u0003ואוכל\u0004 — \u0003יעשה\u0004 מלאכה אצל המוצא \u0003ויאכל, ודבר שאין עושה ו\u0004בכל זאת \u0003אוכל\u0004 — \u0003ימכר\u0004 לאחר זמן מה, ולא ישאירנו בידו שיאכל ולא יעשה. \u0003שנאמר: \"והשבתו לו\"\u0004 (דברים כב, ב), ללמד בין השאר: \u0003ראה היאך תשיבנו לו,\u0004 שאם יאכל זמן מרובה אצל המוצא ואחר כך יצטרך המאבד לשלם כל הוצאות האוכל, שמא לא יהא בכך השבת אבידה אלא טירדה בלבד.","\u0003מה יהא בדמים\u0004 שקיבל תמורת האבידה שמכר? \u0003רב טרפון אומר: ישתמש בהן\u0004 המוצא, \u0003לפיכך אם אבדו\u0004 דמים אלה \u0003חייב באחריותן,\u0004 שהרי הם כאילו לקח אותם בהלוואה מן המאבד. \u0003רבי עקיבא אומר: לא ישתמש בהן\u0004 אלא ישארו בידו כמות שהם ו\u0003לפיכך אם אבדו אין חייב באחריותן,\u0004 כשם שאין חייב באחריות של אבידה.","אמרנו שדבר שעושה ואוכל יעשה ויאכל, ושואלים: \u0003ולעולם\u0004 יישאר בביתו והוא יצטרך להיות אחראי לו? \u0003אמר רב נחמן אמר שמואל: עד שנים עשר חדש\u0004 ואחר כך יכול הוא למכור. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003כל דבר שעושה ואוכל כגון פרה וחמור\u0004 שיש בהם רווח כנגד דמי החזקתם, \u0003מטפל בהן עד שנים עשר חדש, מכאן ואילך\u0004 — \u0003שם\u0004 (מעריך) \u0003דמיהן ומניחן\u0004 את הדמים.","\u0003עגלים וסייחין\u0004 שהם קטנים ואינם עובדים \u0003מטפל בהן שלשה חדשים, מכאן ואילך\u0004 — \u0003שם דמיהן ומניחן.\u0004 מצא \u0003אווזין ותרנגולין מטפל בהם שלשים יום, מכאן ואילך\u0004 — \u0003שם דמיהן ומניחן.\u0004","\u0003אמר רב נחמן בר יצחק: תרנגולת\u0004 דינה \u0003כבהמה גסה\u0004 שכן היא מטילה ביצים והרי היא בגדר של עושה ואוכל. ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003תרנגולת ובהמה גסה מטפל בהן שנים עשר חודש, מכאן ואילך\u0004 — \u0003שם דמיהן ומניחן.\u0004 ואילו \u0003עגלים וסייחין מטפל בהן שלשים יום, מכאן ואילך\u0004 — \u0003שם דמיהן ומניחן.\u0004 ואילו \u0003אווזין ותרנגולין וכל דבר שטיפולו\u0004 (הטיפול בו) \u0003מרובה משכרו, מטפל בהן שלשה ימים, מכאן ואילך\u0004 — \u0003שם דמיהן ומניחן.\u0004","אף על פי שלענין דברי רב נחמן בר יצחק יש ראיה מכאן, מכל מקום יש הבדלים רבים בין הברייתות; \u0003קשיא\u0004 \u0005[קשה]\u0006 מ\u0003עגלים וסייחין\u0004 שבברייתא אחת על \u0003עגלים וסייחין\u0004 שבשניה, וכן מדין \u0003אווזין ותרנגולין\u0004 על \u0003אווזין ותרנגולין!\u0004","ומתרצים: \u0003עגלים וסייחין\u0004 על \u0003עגלים וסייחין לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003הא\u0004 \u0005[אלה]\u0006 ששנינו שמחזיק שלושה חדשים הם כאלה \u0003דרעיא\u0004 \u0005[שהולכין למרעה],\u0006 \u0003והא\u0004 \u0005[ואלה]\u0006 שאמרנו שאינו צרי לטפל בהם אלא חודש הרי זה מדובר באופן \u0003דפטומא\u0004 \u0005[שצריכים לפטם].\u0006","וכן \u0003אווזין ותרנגולין\u0004 על \u0003אווזין ותרנגולין נמי לא קשיא\u0004 \u0005[גם כן אינו קשה];\u0006 \u0003הא ברברבי\u0004 \u0005[זה בגדולים]\u0006 שאין טירחתן מרובה, \u0003הא בזוטרי\u0004 \u0005[זה בקטנים]\u0006 שטירחתן מרובה ישאירם אצלו רק שלושה ימים (רמב\"ם).","שנינו במשנה שדבר \u0003שאינו עושה ואוכל\u0004 ימכר כדי לקיים \"והשבותו לו\", \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"והשבתו לו\"\u0004 — \u0003ראה\u0004 והתבונן \u0003היאך תשיבנו לו\u0004 שתהא בכך השבה, \u0003שלא יאכיל עגל לעגלים,\u0004 כלומר, שלא ימצא שכל דמי עגל שנמצא הלכו בהוצאות שמוציא בטיפול בו, או \u0003סייח לסייחין, אווזא לאווזין, ותרנגול לתרנגולין,\u0004 שלבסוף לא יקבל המאבד דבר.","שנינו במשנה שחלקו חכמים \u0003מה יהא בדמים\u0004 שקיבל בעד האבידה. \u0003ר' טרפון אומר ישתמש\u0004 בהן ורבי עקיבא אסר להשתמש בה. ומעירים: \u0003עד כאן לא\u0004 שמענו כי \u0003פליגי\u0004 \u0005[נחלקו]\u0006 תנאים אלה,"],["\u0003אלא כשנשתמש בהן\u0004 בכספים הללו, ובכך נחלקו אם מתחייב באחריותן. \u0003אבל\u0004 אם \u0003לא נשתמש בהן, אם אבדו\u0004 כספים אלה — \u0003פטור.\u0004","\u0003לימא תיהוי תיובתא\u0004 \u0005[האם נאמר שתהא מכאן קושיה חמורה]\u0006 לשיטת \u0003רב יוסף\u0004 בענין זה? \u0003דאתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו אמוראים בשאלה מה דינו של \u0003שומר אבידה. רבה אמר:\u0004 דינו \u0003כשומר חנם, רב יוסף אמר:\u0004 דינו \u0003כשומר שכר.\u0004 ומן המשנה לכאורה מוכח שדינו כשומר חינם הפטור מלשלם בגניבה ואבידה אם לא ישתמש!","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 \u0003רב יוסף: בגניבה ואבידה\u0004 — \u0003דכולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 שהוא \u0003חייב\u0004 לשלם כשומר שכר, \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 ר' עקיבא ור' טרפון הרי זה \u0003באונסין\u0004 של \u0003שואל,\u0004 בדברים שאבדו ממנו באונס, שחייב עליהם השואל חפץ מחבירו. \u0003ר' טרפון סבר: שרו ליה רבנן לאשתמושי בגוייהו\u0004 \u0005[התירו לו חכמים להשתמש בהם],\u0006 \u0003והוה ליה\u0004 \u0005[והרי הוא]\u0006 כ\u0003שואל עלייהו\u0004 \u0005[עליהם]\u0006 וחייב אפילו באונס. \u0003ור' עקיבא סבר: לא שרו ליה רבנן לאשתמושי בגוייהו\u0004 \u0005[התירו לו חכמים להשתמש בהם],\u0006 \u0003הלכך\u0004 \u0005[על כן]\u0006 \u0003לא הוי\u0004 \u0005היה\u0006 כ\u0003שואל עלייהו\u0004 \u0005[עליהם].\u0006","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, \u0003\"לפיכך\"\u0004 ש\u0003אמר ר' עקיבא, למה לי?\u0004 הלא אין צורך בתוספת הסבר, שהרי המסקנה מובנת מאליה. \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם היית אומר]\u0006 ש\u0003בגניבה ואבידה הוא דפליגי\u0004 \u0005[שנחלקו],\u0006 \u0003היינו דקתני\u0004 \u0005[הוא ששנינו]\u0006 \u0003\"ר' עקיבא אומר לא ישתמש בהן לפיכך אם אבדו אינו חייב באחריותן\".\u0004 וכך נבין את הכפילות: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 ששומר אבידה \u0003שומר שכר הוי\u0004 \u0005[הוא]\u0006 \u0003כ\u0004דברי \u0003רב יוסף, ו\u0004אף \u0003בגניבה ואבידה מחייב\u0004 \u0005[\u0006הוא \u0005חייב],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 \u0003\"לפיכך\".\u0004 אבל \u0003השתא דאמרת\u0004 \u0005[עכשיו שאומר אתה]\u0006 \u0003לא ישתמש בהן, שומר שכר לא הוי\u0004 \u0005[איננו]\u0006 \u0003ולא מחייב\u0004 \u0005[ואינו מתחייב]\u0006 אפילו \u0003בגניבה ואבידה,\u0004 שהרי איננו נהנה.","\u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כדברי רב יוסף ש\u0003בגניבה ואבידה דכולי עלמא לא פליגי\u0004 \u0005[לדעת הכל אין חלוקים]\u0006 שהוא \u0003חייב,\u0004 \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003באונסין\u0004 של \u0003שואל, מאי\u0004 \u0005[מה]\u0006 טעם \u0003\"לפיכך\"\u0004 של \u0003ר' עקיבא? הכי מבעי ליה למתנא\u0004 \u0005[כך היה צריך לו לשנות]:\u0006 \u0003\"ר' עקיבא אומר לא ישתמש בהן\"\u0004 ולא עוד, \u0003ואנא ידענא\u0004 \u0005[ואני יודע]\u0006 ממילא \u0003כיון\u0004 ש\u0003לא ישתמש בהן\u0004 — \u0003לאו שואל הוי\u0004 \u0005[איננו שואל]\u0006 \u0003ואינו חייב באחריותן,\u0004 ואם כן \u0003\"לפיכך\"\u0004 של \u0003ר' עקיבא למה לי?\u0004","ומשיבים: באמת איננו נחוץ לענייננו, אלא הובא כנגד הלשון \u0003משום \"לפיכך\"\u0004 שאמר \u0003ר' טרפון.\u0004","ושואלים: \u0003ו\"לפיכך\"\u0004 שאמר \u0003ר' טרפון למה לי?\u0004 ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין את דברי ר' טרפון: \u0003כיון דשרו ליה רבנן לאשתמושי בגוייהו\u0004 \u0005[שהתירו לו חכמים להשתמש בהם]\u0006 \u0003כמאן דאישתמש בגוייהו דמי\u0004 \u0005[כמי שהשתמש בהם\u0006 בפועל הוא \u0005נחשב]\u0006 \u0003וחייב באחריותן,\u0004 ואפילו לא השתמש בהן ממש.","ומקשים מצד אחר על פירושו של רב יוסף למשנה: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"אבדו\" קתני\u0004 \u0005[שנינו]\u0006 שם ושומר שכר חייב בכל מקרה, ונמצא שבדין שומר שכר הם חולקים ולא בדין אונס!"],["\u0003רבה\u0004 לענין אחר. ש\u0003אמר רבה\u0004 מה ששנו שם \u0003\"נגנבו\"\u0004 כוונתו \u0003בלסטים מזויין\u0004 — על ידי שודד, שהוא אונס, ו\u0003\"אבדו\"\u0004 כוונתו \u0003שטבעה ספינתו בים\u0004 שאף הוא אונס.","\u0003אמר רב יהודה אמר שמואל:\u0004 לענין זה \u0003הלכה כר' טרפון.\u0004 מסופר: \u0003ביד\u0004 החכם \u0003רחבה הוה ליה הנהו זוזי דיתמי\u0004 \u0005[היו לו אותם כספים של יתומים]\u0006 שהוא היה שומר אותם, \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב יוסף\u0004 בשאלה, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מהו\u0004 הדין האם מותר \u0003לאשתמושי בגוייהו\u0004 \u0005[להשתמש בהם]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי אמר\u0004 \u0005[כך אמר]\u0006 \u0003רב יהודה אמר שמואל: הלכה כר' טרפון\u0004 ואם כן מותר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ולאו אתמר עלה\u0004 \u0005[וכי לא נאמר עליה]\u0006 על הלכה זו ש\u0003אמר ר' חלבו אמר רב הונא:\u0004 \u0003לא שנו\u0004 היתר זה של שימוש \u0003אלא בדמי אבידה,\u0004 כלומר, הכסף שקיבל עבור אבידה שמצא ואחר כך הוצרך למוכרה, \u0003הואיל וטרח בה\u0004 בטיפול קודם לכן, והתירו לו להשתמש בכספים, \u0003אבל מעות אבידה\u0004 אם מצא כסף מזומן ש\u0003לא טרח בהו\u0004 \u0005[בהם]\u0006 \u0003לא. והני\u0004 \u0005[ואלה]\u0006 כספי היתומים הלא \u0003כמעות אבידה דמו\u0004 \u0005[נחשבים]\u0006 ואם כן אין להשתמש בהם. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף לרחבה: \u0003זיל\u0004 \u0005[לך]\u0006 \u0003לא שבקו\u0004 \u0005[נתנו]\u0006 \u0003לי דאשרי\u0004 \u0005[שאתיר]\u0006 \u0003לך,\u0004 שהרי הוכיח אביי שאין הדבר מותר.","\u0003מצא ספרים\u0004 והספרים היו אז עשויים בקלף או נייר גלול כמגילה — \u0003קורא בהן אחד לשלשים יום\u0004 כדי שיתאווררו על ידי כך ולא יתעפשו. \u0003ואם אינו יודע לקרות\u0004 — \u0003גוללן\u0004 בלבד. \u0003אבל לא ילמוד בהן בתחילה\u0004 בנושא שלא למד בו עדיין, שכיוון שצריך להשתהות יותר בעיון על ידי זה מקלקל קצת את הספרים, \u0003ו\u0004כן \u0003לא יקרא אחר עמו,\u0004 שמא ימשכו זה לצד זה וזה לצד זה ועלול הספר להיקרע.","\u0003מצא כסות\u0004 — \u0003מנערה אחד לשלשים יום ושוטחה לצרכה\u0004 כדי שתתאוורר, \u0003אבל לא לכבודו,\u0004 כלומר, לא ישטח אותו כדי לקשט את ביתו לכבוד עצמו.","מצא \u0003כלי כסף וכלי נחושת\u0004 — \u0003משתמש בהן לצרכן\u0004 כדי שלא יחלידו, \u0003אבל לא\u0004 במדה שיש בה כדי \u0003לשחקן\u0004 (לשחוק אותן). מצא \u0003כלי זהב וכלי זכוכית\u0004 שאין מתקלקלים אם משאיר אותם כמות שהם — \u0003לא יגע בהן\u0004 ולא ישתמש בהן \u0003עד שיבוא אליהו\u0004 ויאמר של מי הם. ומכאן לדין שונה בדיני מציאות.","\u0003מצא\u0004 אדם \u0003שק או קופה\u0004 (סל) \u0003וכל דבר שאין דרכו ליטול,\u0004 שהמוצא הזה אדם מכובד הוא ואין דרכו לטלטל דברים כגון אלה — \u0003הרי זה לא יטול,\u0004 שאינו צריך לבזות עצמו, ואינו עובר משום \"לא תוכל להתעלם\" (דברים כב, ג).","\u0003אמר שמואל: המוצא תפילין בשוק\u0004 אם זקוק לתפילין בעצמו — \u0003שם\u0004 (מעריך) \u0003דמיהן\u0004 כמה הן \u0003ומניחן לאלתר\u0004 \u0005[מיד].\u0006","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רבינא\u0004 ממה ששנינו: \u0003מצא ספרים\u0004 — \u0003קורא בהן אחד לשלשים יום, ואם אינו יודע לקרות\u0004 — \u0003גוללן.\u0004 ונדייק: \u0003גוללן\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003שם דמיהן ומניחן\u0004 — \u0003לא,\u0004 ומדוע מותר לו לעשות זאת בתפילין? \u0003אמר אביי: תפילין בי\u0004 \u0005[בבית]\u0006 \u0003בר חבו משכח שכיחי\u0004 \u0005[מצויים הם],\u0006 שבית בר חבו היה כעין בית מלאכה של תפילין, ועשה הרבה מאוד תפילין, ובכל עת יכול אדם לקנות זוג תפילין, ואין יחוד בזוג מסויים זה, ולכן אין בעיה במה שישום אותם ויניחם לאלתר. ואילו \u0003ספרים לא שכיחי\u0004 \u0005[אינם מצויים]\u0006 שהרי ספרים היו מועתקים בטפסים מועטים ויתכן שלא ימצא ספר כיוצא בזה, ולכן אסור לו לעשות בהם כן.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003השואל ספר תורה מחבירו הרי זה לא ישאילנו לאחר, פותחו וקורא בו ובלבד שלא ילמוד בו בתחילה\u0004 ענין חדש, שלא יתעכב בלימוד ויבלה את הספר, \u0003ולא יקרא אחר עמו\u0004 שמא יקרע הספר.","\u0003וכן המפקיד ספר תורה אצל חבירו גוללו כל שנים עשר חדש\u0004 ובאותה שעה \u0003פותחו וקורא בו, אם בשבילו פתחו,\u0004 שהוא עצמו צריך לעיין בו — \u0003אסור. סומכוס אומר: ב\u0004ספר תורה \u0003חדש\u0004 יש לגוללו כל \u0003שלשים יום\u0004 מפני שהוא לח עדיין וצריך לאווררו ולייבשו הרבה, \u0003בישן\u0004 אין צריך לגוללו אלא כל \u0003שנים עשר חדש. ר' אליעזר בן יעקב אמר:\u0004 אין לחשוש לקלקול ספר חדש אלא \u0003אחד זה ואחד זה\u0004 גוללו אחת ל\u0003שנים עשר חדש.\u0004","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא שהבאנו: \u0003השואל ספר תורה מחבירו הרי זה לא ישאילנו לאחר.\u0004 ושואלים: \u0003מאי אריא\u0004 \u0005[מה שייך, מדוע דווקא]\u0006 \u0003ספר תורה? אפילו כל מילי נמי\u0004 \u0005[כל דבר גם כן]\u0006 ששואלים אסור להשאיל לאחר, שהרי כבר \u0003אמר ר' שמעון בן לקיש\u0004 במקום אחר כהערה למשנה בגיטין: \u0003כאן שנה רבי\u0004 ברמז את הכלל ש\u0003אין השואל רשאי להשאיל\u0004 את החפץ ששאל לאחר בלי רשות המשאיל, \u0003ואין השוכר רשאי להשכיר!\u0004","ומשיבים: \u0003ספר תורה\u0004 דווקא \u0003איצטריכא ליה\u0004 \u0005[הוצרך לו]\u0006 לומר במיוחד, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003ניחא ליה לאיניש דתיעביד\u0004 \u0005[נוח לו לאדם שתיעשה]\u0006 \u0003מצוה בממוניה\u0004 \u0005[בממונו],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאפילו ספר תורה אסרו לשואל להשאילו לאחר בלא רשות.","שנינו שם: \u0003פותחו וקורא בו.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 \u0003ואלא למאי שייליה מיניה\u0004 \u0005[למה שאל אותו ממנו]?\u0006 בוודאי כדי לקרוא בו! ומשיבים: \u0003סיפא איצטריכא ליה\u0004 \u0005[סופה\u0006 של הברייתא \u0005הוצרכה לו\u0006 לומר\u0005],\u0006 ששנינו בה: \u0003ובלבד שלא ילמוד בו בתחלה,\u0004 שמן הסתם לא לכך השאילו.","עוד שנינו שם \u0003וכן המפקיד ספר תורה אצל חבירו גוללו כל שנים עשר חדש, פותחו וקורא בו.\u0004 ותוהים: \u0003מאי עבידתיה גביה\u0004 \u0005[מה מעשהו אצלו]\u0006 כלומר, מה לו לפתוח ולקרוא בספר שאינו שלו? \u0003ותו\u0004 \u0005[ועוד]\u0006 אמרו שם: \u0003אם בשבילו פתחו\u0004 — \u0003אסור, הא\u0004 \u0005[הרי]\u0006 \u0003אמרת\u0004 קודם ש\u0003פותחו וקורא בו!\u0004 ומשיבים על שתי השאלות כאחת: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אם כשהוא גוללו\u0004 כדי לאווררו \u0003פתחו וקורא בו\u0004 — \u0003מותר\u0004 לקרוא, \u0003אם בשבילו פתחו\u0004 לשם קריאה — הרי זה \u0003אסור.\u0004","עוד שנינו שם ש\u0003סומכוס אומר: בחדש\u0004 גוללו כל \u0003שלשים יום, בישן\u0004 די בגלילתו אחת ל\u0003שנים עשר חדש. ר' אליעזר בן יעקב אומר: אחד זה ואחד זה\u0004 אין גוללם אלא אחת ל\u0003שנים עשר חדש.\u0004 ותוהים: \u0003ר' אליעזר בן יעקב היינו\u0004 \u0005[זהו]\u0006 שיטת \u0003תנא קמא,\u0004 שהרי גם תנא קמא אינו מחלק, ואמר בכלל: שנים עשר חדש. \u0003אלא אימא\u0004 \u0005[אמור]\u0006 ותקן את הגרסה כך: \u0003ר' אליעזר בן יעקב אומר אחד זה ואחד זה שלשים יום,\u0004 שהוא סבור שאפילו ספר תורה ישן צריך לאוורר אותו אחת לשלושים יום.","שנינו: \u0003אבל לא ילמוד בו בתחלה ולא יקרא אחר עמו. ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003לא יקרא\u0004 בספר תורה שאול \u0003פרשה\u0004 אחת \u0003וישנה, ולא יקרא בו פרשה ויתרגם,\u0004 ששוהה זמן רב יותר בקריאה, \u0003ולא יפתח בו יותר משלשה דפין\u0004 שעלול להתגלגל ולהקרע, \u0003ולא יקראו בו שלשה בני אדם בכרך אחד,\u0004 ומשמע: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003שנים\u0004 — \u0003קורין,\u0004 והרי אמרנו שאף שנים לא יקראו!","\u0003אמר אביי: לא קשיא\u0004 \u0005[אינו קשה],\u0006 \u0003כאן בענין אחד\u0004 מותר לשנים לקרוא שהרי הם קוראים באותו דבר, \u0003כאן בשני ענינים\u0004 אינם שמים לב זה לזה ומושכים זה מזה את הספר (רמב\"ם).","שנינו במשנה שאם \u0003מצא כסות\u0004 הריהו \u0003מנערה אחד לשלשים יום.\u0004 ושואלים: \u0003למימרא\u0004 \u0005[האם נאמר]\u0006 מכאן כי ה\u0003ניעור מעלי\u0004 \u0005[יפה]\u0006 \u0003לה\u0004 לכסות? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן\u0004 כעצה טובה: \u0003מי שיש לו גרדי אומן בתוך ביתו,\u0004 כלומר, רק מי שיש לו אורג העובד תמיד בתוך ביתו ואיננו חושש להשחתת בגדים יכול להרשות לעצמו ש\u0003ינער כסותו בכל יום! אמרי\u0004 \u0005[אומרים]\u0006 ומתרצים: ניעור \u0003בכל יום\u0004 — \u0003קשי\u0004 \u0005[קשה,\u0006 מזיק\u0005]\u0006 \u0003לה\u0004 לגלימה, ואולם \u0003אחד לשלשים יום\u0004 — \u0003מעלי\u0004 \u0005[מועיל]\u0006 \u0003לה.\u0004","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 ותרץ בדרך אחרת: \u0003לא קשיא\u0004 \u0005[אינו קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שהוא מועיל הרי זה \u0003בחד\u0004 \u0005[באדם אחד]\u0006 שמנער, \u0003והא\u0004 \u0005[וזה]\u0006 שזה מזיק הרי זה \u0003בתרי\u0004 \u0005[בשנים]\u0006 שמנערים יחד.","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 תירוץ אחר: \u0003לא קשיא\u0004 \u0005[אינו קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שיפה הוא ניעור \u0003בידא\u0004 \u0005[ביד],\u0006 \u0003והא\u0004 \u0005[וזה]\u0006 שמזיק הרי זה בניעור \u0003בחוטרא\u0004 \u0005[במקל].\u0006","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 תירוץ אחר: \u0003לא קשיא\u0004 \u0005[אינו קשה]:\u0006 \u0003הא בדעמרא\u0004 \u0005[זה ב\u0006בגד \u0005של צמר]\u0006 יפה לו הניעור, \u0003הא בדכיתנא\u0004 \u0005[זה ב\u0006בגד \u0005של פשתן]\u0006 מזיק לו הניעור (רי\"ף).","ועוד ממה ש\u0003אמר ר' יוחנן\u0004 כעצות לחיי מעשה: \u0003כסא דחרשין\u0004 \u0005[כוס של כישוף]\u0006 \u0003ולא כסא\u0004 \u0005[כוס]\u0006 של מים \u0003פושרין\u0004 שהם מזיקים ביותר לבריאות. ומעירים: \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה \u0003אלא\u0004 כששותה \u0003בכלי מתכות, אבל בכלי חרש\u0004 — \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 חשש זה. \u0003ובכלי מתכות נמי\u0004 \u0005[גם כן]\u0006 \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא\u0004 באופן ש\u0003לא צויץ\u0004 \u0005[רתח],\u0006 \u0003אבל דצויץ\u0004 \u0005[\u0006אם \u0005רתח]\u0006 — \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 חשש. \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא\u0004 באופן ש\u0003לא שדא ביה ציביא\u0004 \u0005[זרק בו עצים,\u0006 מיני עשבים ותבלין\u0005]\u0006 \u0003אבל\u0004 אם \u0003שדא ביה ציביא\u0004 \u0005[הטיל בו עצים,\u0006 עשבים\u0005]\u0006 — \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 חשש.","\u0003ואמר ר' יוחנן: מי שהניח לו אביו מעות הרבה ורוצה לאבדן\u0004 מה יעשה? כלומר, הרי רשימה של דברים הגורמים לאיבוד ממון, שצריך אדם להיזהר מהם. והם: \u0003ילבש בגדי פשתן, וישתמש בכלי זכוכית, וישכור פועלים ואל ישב עמהם\u0004 להשגיח. ומסבירים: \u0003ילבש בכלי פשתן\u0004 מדובר \u0003בכיתנא רומיתא\u0004 \u0005[בפשתן רומי]\u0006 שהוא יקר ומהיר להתקלקל. \u0003וישתמש בכלי זכוכית\u0004 — \u0003בזוגיתא חיורתא\u0004 \u0005[בזכוכית לבנה]\u0006 שהיא יקרה ביותר. \u0003וישכור פועלים ואל ישב עמהן\u0004 — \u0003תרגומא\u0004 \u0005[מתרגמים,\u0006 מסבירים זאת\u0005]\u0006"],["\u0003בתורי דנפיש פסידייהו\u0004 \u0005[בשוורים שמרובה הפסדם]\u0006 שהם גורמים אם אין משגיחים בהם.","שנינו במשנה שכסות שנמצאה \u0003שוטחה לצורכה אבל לא לכבודו. איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים שאלה זו: אם רוצה לשוטחה \u0003לצורכו ולצורכה\u0004 גם יחד, \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 תשובה לדבר ממה ששנינו במשנתנו \u0003\"שוטחה לצורכה\",\u0004 ונדייק: \u0003לצורכה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 אם היה זה \u0003לצורכו ולצורכה\u0004 — \u0003לא!\u0004 ודוחים: מכאן אין הוכחה, כי \u0003אימא סיפא\u0004 \u0005[אמור את הסוף]\u0006 של המשנה: \u0003\"אבל לא לכבודו\",\u0004 ונדייק מכאן \u0003לכבודו\u0004 בלבד \u0003הוא\u0004 ש\u0003לא\u0004 ישטח, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לצורכה ולצורכו\u0004 — \u0003שפיר דמי\u0004 \u0005[יפה הדבר].\u0006 \u0003אלא מהא ליכא למשמע מינה\u0004 \u0005[מ\u0006משנה \u0005זו אין לשמוע ממנה],\u0006 שהדיוק מתוכה איננו מביא למסקנה.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה ממה ששנינו בברייתא: \u0003לא ישטחנה לא על גבי מטה ולא על גבי מגוד\u0004 (קולב) \u0003לצרכו, אבל ישטחנה על גבי מטה ועל גבי מגוד לצרכה\u0004 של האבידה, \u0003נזדמנו לו אורחים לא ישטחנה לא על גבי מטה ולא על גבי מגוד, בין\u0004 ששוטחה \u0003לצורכו בין לצורכה,\u0004 הרי מכאן ראיה שלצורכו (להתכבד בפני האורחים) ולצורכה אסור!","ודוחים: משם אין ראיה, שכן \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 \u0003דמקלא קלי לה\u0004 \u0005[שהרי\u0006 הוא \u0005כשורף אותה]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום עינא\u0004 \u0005[עין\u0006 הרע\u0005]\u0006 שתשלוט בה, \u0003אי\u0004 \u0005[או]\u0006 \u0003משום גנבי\u0004 \u0005[הגנבים]\u0006 שידעו שיש בביתו חפץ כזה ויבואו לגנבו.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו בברייתא בדיני עגלה ערופה, שלצורך זה יש לקחת עגלה שלא עשתה כל מלאכה: אם \u0003הכניסה לרבקה\u0004 (קבוצה של פרות) \u0003ו\u0004עגלה זו \u0003דשה\u0004 איתן — הרי זו \u0003כשירה,\u0004 שלא נתכוון שתדוש. אבל אם הכניסה \u0003בשביל שתינק\u0004 מאמה \u0003ו\u0004בינתיים גם \u0003תדוש\u0004 — \u0003פסולה. והא הכא\u0004 \u0005[והרי כאן]\u0006 ש\u0003לצורכו ולצורכה הוא,\u0004 שהרי לשניהם יש תועלת בזה, \u0003וקתני\u0004 \u0005[ושנה]\u0006 שהיא \u0003פסולה!\u0004","ודוחים: משם אין להוכיח, שכן \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"עגלת בקר \u0003אשר לא עבד בה\u0004 אשר לא משכה בעול\" (דברים כא, ג), ומלשון זו למדים שנפסלת על ידי כל עבודה \u0003מכל מקום.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שכל עבודה פוסלתה \u0003אפילו רישא נמי\u0004 \u0005[בתחילה גם כן].\u0006","ומשיבים: \u0003הא לא דמיא\u0004 \u0005[זה אינו דומה]\u0006 \u0003אלא להא\u0004 \u0005[לזו],\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 לגבי פרה אדומה, שאף בה אסור לעשות כל מלאכה: אם \u0003שכן עליה עוף\u0004 — \u0003כשירה,\u0004 שבודאי אין זו מלאכה ואין זה בגדר עול, אם \u0003עלה עליה זכר\u0004 — \u0003פסולה.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 ההבדל?","ומסבירים שהוא \u0003כ\u0004דברי \u0003רב פפא,\u0004 ש\u0003אמר רב פפא: אי כתיב\u0004 \u0005[אילו היה כתוב]\u0006 \u0003\"עובד\" וקרינן\u0004 \u0005[והיינו קוראים]\u0006 \u0003\"עובד\"\u0004 שהוא לשון המתייחסת לדבר שנעשה מעצמו — \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003אפילו ממילא\u0004 גם ללא כוונה, כיון שנעשתה בה עבודה כל שהיא — נפסלה. \u0003ואי כתיב\u0004 \u0005[ואילו\u0006 היה \u0005כתוב]\u0006 \u0003\"עבד\" וקרינן\u0004 \u0005[והיינו קוראים]\u0006 \u0003\"עבד\"\u0004 בלשון פועל, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 שלא תאסר \u0003עד\u0004 ש\u0003עבד בה איהו\u0004 \u0005[הוא]\u0006 ברצון ומדעת.","\u0003השתא דכתיב\u0004 \u0005[עכשיו שנאמר]\u0006 \u0003\"עבד\" וקרינן\u0004 \u0005[ואנו קוראים]\u0006 \u0003\"עובד\"\u0004 — \u0003בעינן\u0004 \u0005[צריכים אנו שיהיה]\u0006 \u0003\"עבד\" דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003\"עובד\".\u0004 וכך נשווה: \u0003מה \"עבד\" דניחא ליה\u0004 \u0005[שנוח לו]\u0006 שעשה את הדבר מרצונו, \u0003אף עובד\u0004 כשנעשתה עבודה מעצמה צריך להיות בה תנאי זה \u0003דניחא ליה\u0004 \u0005[שנוח לו הדבר],\u0006 וכיון שבשכינת העוף אין לו כל ענין — לכן כשרה היא, אבל אם עלה עליה זכר שיכולה להתעבר ולהוליד כמותה, הרי נוח לו בכך ולכן היא נפסלת.","שנינו במשנה ש\u0003כלי כסף וכלי נחושת משתמש בהן\u0004 לצרכם וכן בשאר כלים למיניהם. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המוצא כלי עץ משתמש בהן בשביל שלא ירקבו\u0004 מחוסר שימוש, \u0003כלי נחושת משתמש בהן\u0004 לצורך \u0003חמין, אבל לא על ידי האור\u0004 \u0005[האש]\u0006 ממש, \u0003מפני שמשחיקן,\u0004 שגורם להם שישתחקו על ידי כך, ואילו \u0003כלי כסף משתמש בהן\u0004 רק \u0003בצונן אבל לא בחמין, מפני שמשחירן\u0004 על ידי החמין. \u0003מגריפות וקרדומות\u0004 שמצא \u0003משתמש בהן ב\u0004שביל דבר \u0003רך, אבל לא בקשה מפני שמפחיתן. כלי זהב וכלי זכוכית\u0004 שאינם מתקלקלים כלל \u0003לא יגע בהן עד שיבא אליהו.\u0004","ומעירים: \u0003כדרך שאמרו באבידה כך אמרו בפקדון.\u0004 ותוהים: \u0003פקדון מאי עבידתיה גביה\u0004 \u0005[מה מעשהו אצלו]?\u0006 כלומר, מי הרשה לו לטפל בחפץ שנמסר לו כפקדון? יבוא בעל הפקדון ויטפל בו! \u0003אמר רב אדא בר חמא אמר רב ששת:\u0004 מדובר כאן \u0003בפקדון שהלכו בעליהן למדינת הים\u0004 ואינם עתידים לחזור אלא לאחר זמן מרובה, ומתוך אחריותו של השומר לשמירת הפיקדון צריך הוא לעשות בכלי שימוש מה.","שנינו במשנה כי מי ש\u0003מצא שק או קופה וכל דבר שאין דרכו\u0004 של המוצא כרגיל \u0003ליטול\u0004 מפני כבודו — \u0003הרי זה לא יטול,\u0004 ואינו עובר משום ביטול מצווה. ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין הדברים הללו],\u0006 מה מקורם במקרא? ומשיבים, \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]\u0006 על המקרא: \"לא תראה את שור אחיך או את שיו נידחים \u0003והתעלמת\u0004 מהם\" (דברים כב, א). ולמדים מלשון הכתוב \u0003פעמים שאתה מתעלם\u0004 מן האבידה ברשות \u0003ופעמים שאי אתה מתעלם.\u0004","\u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 מתעלם? — אם \u0003היה\u0004 המוצא \u0003כהן והיא,\u0004 האבידה, \u0003בבית קברות,\u0004 שאסור לכהן להכנס לבית הקברות, \u0003או שהיה זקן ואינה לפי כבודו\u0004 לטפל בה, \u0003או שהיתה מלאכה שלו מרובה משל חבירו\u0004 ואם יבוא להחזיר את האבידה יפסיד ביותר, \u0003לכך נאמר: \"והתעלמת מהם\".\u0004","ושואלים: \u0003למאי איצטריך קרא\u0004 \u0005[למה,\u0006 לאיזה מהדברים הללו \u0005הוצרך הכתוב]\u0006 לפרש להתיר בענין זה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003לכהן והיא בבית הקברות\u0004 — אולם זה איננו צריך מקרא, שהרי זה \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 שכן \u0003האי\u0004 \u0005[זה]\u0006 מצוות השבת אבידה מצוות \u0003עשה\u0004 (\"השב תשיבם\". שם), \u0003והאי\u0004 \u0005[וזה]\u0006 האיסור להיטמא למת מצוות \u0003לא תעשה\u0004 (\"לנפש לא יטמא בעמיו\". ויקרא כא, א), \u0003ו\u0004גם מצוות \u0003עשה\u0004 (\"קדושים תהיו\". שם יט, ב), \u0003ולא אתי\u0004 \u0005[בא]\u0006 דבר שהוא מצוות \u0003עשה ודחי\u0004 \u0005[ודוחה]\u0006 \u0003את לא תעשה ועשה, ותו\u0004 \u0005[ועוד]\u0006 טעם: \u0003לא דחינן איסורא מקמי ממונא\u0004 \u0005[אין אנו דוחים\u0006 דבר של \u0005איסור מלפני\u0006 ענין של \u0005ממון].\u0006","\u0003אלא\u0004 אם תאמר שהפסוק בא \u0003ל\u0004ענין שמלאכתו \u0003שלו מרובה משל חבירו\u0004 — אולם דבר זה נלמד ממקור אחר, \u0003מ\u0004דברי \u0003רב יהודה אמר רב נפקא\u0004 \u0005[יוצא\u0006 הדבר\u0005],\u0006 ש\u0003אמר רב יהודה אמר רב:\u0004 נאמר במקרא \u0003\"אפס כי\u0004"],["\u0003לא יהיה בך אביון\"\u0004 (דברים טו, ד) ומכאן למדו שחובה לאדם שידאג לעצמו שלא יגיע להיות אביון, ולכן \u0003שלך קודם לשל כל אדם,\u0004 וממילא אין אדם חייב להפסיד ממונו כדי שיימצא חבירו מרוויח,","\u0003אלא\u0004 בא הכתוב להתיר \u0003לזקן ואינו לפי כבודו.\u0004","\u0003אמר רבה:\u0004 אם היתה זו בהמה שאבדה ו\u0003הכישה\u0004 \u0005[היכה אותה]\u0006 אפילו פעם אחת — \u0003חייב בה\u0004 בטיפולה והשבתה לבעליה. מסופר: \u0003אביי הוה יתיב קמיה\u0004 \u0005[היה יושב לפני]\u0006 \u0003רבה, חזא להנך עיזי דקיימו\u0004 \u0005[ראה אותן עיזים שעומדות]\u0006 שם, \u0003שקל קלא ושדא בהו\u0004 \u0005[נטל צרור וזרק בהן].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: כבר \u0003איחייבת בהו, קום אהדרינהו\u0004 \u0005[התחייבת בהן\u0006 בטיפולן, \u0005עמוד והחזר אותן]\u0006 לבעליהן.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים שאלה זו: \u0003דרכו להחזיר בשדה,\u0004 כלומר, כשהוא בשדה שאין האנשים מרובים איננו מתבייש ולוקח חפצים כגון אלה, אבל \u0003אין דרכו להחזיר בעיר\u0004 ומצא אבידה זו בשדה \u0003מהו? מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 כי \u0003השבה מעליא בעינן\u0004 \u0005[מעולה צריכים אנו]\u0006 \u0003וכיון דלאו דרכיה\u0004 \u0005[שאין דרכו]\u0006 \u0003להחזיר בעיר\u0004 ש\u0003לא לחייב\u0004 \u0005[יתחייב]\u0006 לו להחזיר, שהרי אין מדרכו להחזיר עד לעיר, וכיון שכך לא יגע בה כלל. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003בשדה מיהת\u0004 \u0005[על כל פנים]\u0006 \u0003הוא דאיחייב ליה\u0004 \u0005[שהתחייב לו]\u0006 בהשבת האבידה, \u0003וכיון דאיחייב ליה\u0004 \u0005[שהתחייב לו]\u0006 \u0003בשדה איחייב ליה\u0004 \u0005[התחייב לו]\u0006 גם \u0003בעיר?\u0004 שאלה זו לא נמצאה לה תשובה, ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003אמר רבא\u0004 כלל: \u0003כל שבשלו מחזיר,\u0004 שחפץ כגון זה, אם היה שלו היה לוקח אותו, הרי \u0003בשל חבירו נמי\u0004 \u0005[גם כן]\u0006 \u0003מחזיר, וכל שבשלו\u0004 היה \u0003פורק וטוען\u0004 מן החמור, \u0003בשל חבירו נמי\u0004 \u0005[גם כן]\u0006 \u0003פורק וטוען.\u0004","מסופר: \u0003ר' ישמעאל בר' יוסי הוה קאזיל באורחא\u0004 \u0005[היה הולך בדרך]\u0006 \u0003פגע ביה ההוא גברא\u0004 \u0005[פגש בו אדם אחד],\u0006 \u0003הוה דרי פתכא דאופי, אותבינהו וקא מיתפח\u0004 \u0005[היה נושא משא של עצים, הניחם והיה נח],\u0006 ואחר כך \u0003אמר\u0004 האיש \u0003ליה\u0004 \u0005[לו]\u0006 לר' ישמעאל: \u0003דלי\u0004 \u0005[הרם]\u0006 \u0003לי,\u0004 הטען עלי, וכיון שלא רצה ר' ישמעאל לעשות זאת מפני כבודו, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כמה שוין\u0004 העצים הללו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003פלגא דזוזא\u0004 \u0005[חצי זוז],\u0006 \u0003יהיב ליה פלגא דזוזא\u0004 \u0005[נתן לו\u0006 ר' ישמעאל במחירם \u0005חצי זוז]\u0006 \u0003ואפקרה\u0004 \u0005[והפקירה]\u0006 את חבילת העצים.","\u0003הדר זכה בהו\u0004 \u0005[חזר אותו אדם וזכה בהם]\u0006 ושוב ביקש ממנו להרים את החבילה, \u0003הדר יהיב ליה פלגא דזוזא ואפקרה\u0004 \u0005[חזר ונתן לו חצי זוז והפקירם].\u0006 \u0003חזייה דהוה קא בעי למיהדר למזכיה בהו\u0004 \u0005[ראה אותו שהוא רוצה לחזור ולזכות בהם],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לכולי עלמא אפקרנהו\u0004 \u0005[לכל העולם הפקרתי אותם]\u0006 \u0003ו\u0004אולם \u0003לך לא אפקרנהו\u0004 \u0005[הפקרתי אותם].\u0006","אגב סיפור זה שואלים: \u0003ומי הוי\u0004 \u0005[והאם יהא]\u0006 זה \u0003הפקר כי האי גוונא\u0004 \u0005[באופן זה]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005],\u0006 \u0003בית שמאי אומרים: הפקר\u0004 שהפקיר \u0003לעניים\u0004 בלבד — הועילו דבריו והריהו \u0003הפקר,\u0004 אף כי לעניים בלבד, ואם היו אלו פירות הריהם פטורים מן המעשר כדין כל פירות הפקר. \u0003ובית הלל אומרים: אינו הפקר עד שיהא הפקר לעניים ולעשירים\u0004 בשווה, \u0003כשמיטה\u0004 שהכל מותרים בה. נמצא שלשיטת בית הלל, שהלכה כמותם, אין הפקר אלא כאשר הכל מותרים בו, וכיצד עשה זאת ר' ישמעאל?","ומסבירים: \u0003אלא ר' ישמעאל בר' יוסי\u0004 אכן \u0003לכולי עלמא אפקרינהו\u0004 \u0005[לכל העולם הפקירם]\u0006 \u0003ובמלתא בעלמא\u0004 \u0005[ובדיבור בלבד]\u0006 \u0003הוא דאוקמיה\u0004 \u0005[שהעמידו]\u0006 כלומר, באמת יכול היה אותו אדם לזכות שוב, אלא כיון שלא רצה ר' ישמעאל לחזור ולקנות שוב ושוב אמר לו כן.","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' ישמעאל בר' יוסי זקן ואינו לפי כבודו הוה\u0004 \u0005[היה]\u0006 ולא היה חייב כלל לטעון! ומשיבים: \u0003ר' ישמעאל בר' יוסי לפנים משורת הדין הוא דעבד\u0004 \u0005[שעשה],\u0006 שאף שלא היה חייב, היה מדקדק על עצמו במנהג חסידות, אפילו במה שאינו מחוייב בו מן הדין.","ומעין הדברים הללו \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רב יוסף\u0004 ברייתא זו על הכתוב \"והזהרתה אתהם את החוקים ואת התורות והודעת להם את הדרך אשר ילכו בה ואת המעשה אשר יעשון\" (שמות יח, כ). ומסבירה הברייתא: שנוסף לחוקי התורה ומצוותיה, \u0003\"והודעת להם\"\u0004 — \u0003זה בית חייהם\u0004 להודיעם ולייעצם לעסוק במלאכה שיחיו ממנו, \u0003\"את הדרך\"\u0004 — \u0003זו גמילות חסדים, \"אשר ילכו\"\u0004 — \u0003זה\u0004 מצות \u0003ביקור חולים, \"בה\"\u0004 — \u0003זו\u0004 רמז ל\u0003קבורה, \"ואת המעשה\"\u0004 — \u0003זה הדין, \"אשר יעשון\"\u0004 — \u0003זו לפנים משורת הדין.\u0004","ומסבירים קצת את הברייתא הזו, \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003\"אשר ילכו\"\u0004 — \u0003זה ביקור חולים,\u0004 ושואלים: \u0003היינו\u0004 \u0005[הרי הוא]\u0006 פרט ממצות \u0003גמילות חסדים!\u0004 ומשיבים: \u0003לא נצרכה\u0004 מצוה יתרה זו \u0003אלא\u0004 שהולך \u0003לבן גילו,\u0004 לאדם שהוא בן מזלו, ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003בן גילו\u0004 שבא לבקר את החולה \u0003נוטל אחד מששים בחליו, ו\u0004אף על פי שהוא עצמו מקבל מן החולי — \u0003אפילו הכי\u0004 \u0005[כך]\u0006 \u0003מבעי ליה למיזל לגביה\u0004 \u0005[צריך הוא ללכת אליו]\u0006 למרות שנמצא שהוא נפגע מעט.","\u0003\"בה\"\u0004 — \u0003זו קבורה,\u0004 ושוב שואלים: \u0003היינו\u0004 \u0005[הרי הוא]\u0006 \u0003גמילות חסדים!\u0004 ומשיבים: \u0003לא נצרכה אלא לזקן ואינו לפי כבודו\u0004 לטפל בקבורה, שבכל זאת ראוי שידאג לקבור מת הזקוק לכך.","\u0003\"אשר יעשון\"\u0004 — \u0003זו לפנים משורת הדין.\u0004 ש\u0003אמר ר' יוחנן: לא חרבה ירושלים אלא על שדנו בה דין תורה.\u0004 ועל כך תהו: \u0003אלא דיני דמגיזתא לדיינו\u0004 \u0005[גזלנות שידונו]\u0006 ולא דיני תורה?! הרי חובה היא לדון דיני תורה! \u0003אלא אימא\u0004 \u0005[אמור]\u0006 כך: \u0003שהעמידו דיניהם על דין תורה ולא עבדו\u0004 \u0005[עשו]\u0006 \u0003לפנים משורת הדין,\u0004 וכיון שאיש לא רצה לוותר על זכויותיו לכן חרבה ירושלים.","\u0003אי זו היא אבידה? מצא חמור או פרה רועין בדרך\u0004 — \u0003אין זו אבידה,\u0004 שבודאי בעליהם סמוכים לשם ויודעים בהם. מצא \u0003חמור וכליו\u0004 (הכלים שעליו) \u0003הפוכין,\u0004 או \u0003פרה רצה בין הכרמים\u0004 — \u0003הרי זו אבידה.\u0004 והלכה נוספת: \u0003החזירה וברחה, החזירה וברחה, אפילו ארבעה וחמישה פעמים\u0004 — \u0003חייב להחזירה\u0004 שוב כשמוצא אותה, \u0003שנאמר\u0004 בהדגשה וביתור המילים: \u0003\"השב תשיבם\"\u0004 (דברים כב, א).","\u0003היה\u0004 תוך כדי השבת האבידה \u0003בטל מ\u0004מלאכה ששווה \u0003סלע, לא יאמר לו\u0004 בעל האבידה: \u0003תן לי סלע\u0004 שבטלתי מזמני להשבת אבידתך, \u0003אלא נותן לו\u0004 המאבד \u0003שכרו\u0004 על טרחה שטרח \u0003כפועל\u0004 בטל, והוא רק שכר טרחה קטן ביותר. \u0003אם יש שם בית דין,\u0004 שיש שלושה אנשים שיכול לעשותם בית דין — \u0003מתנה\u0004 מלכתחילה \u0003בפני בית דין\u0004 שהוא מחזיר את האבידה על מנת לקבל תשלום עבור כל מה שיפסיד, אבל \u0003אם אין שם בית דין בפני מי יתנה?\u0004 — במקרה זה \u0003שלו קודם,\u0004 שכיון שעלול להפסיד בכך אינו צריך להשיב.","ותוהים על לשון המשנה \"איזו היא אבידה\": \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003כל הני דאמרינן\u0004 \u0005[אלה שאמרנו]\u0006 בכל הפרק הזה \u0003לאו\u0004 \u0005[לא]\u0006 \u0003אבידה הוו\u0004 \u0005[הם]?\u0006 \u0003אמר רב יהודה: הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך היא הכוונה: \u0003אי זו היא כלל\u0004 לגבי \u0003אבידה שהוא חייב בה,\u0004 כלומר, לאבידה במקרים שלא ברור אם אבדה הבהמה אם לא? \u0003מצא חמור ופרה רועין בדרך\u0004 — \u0003אין זו אבידה ו\u0004הוא \u0003לא מיחייב\u0004 \u0005[חייב]\u0006 \u0003בה.\u0004 מצא \u0003חמור וכליו הפוכים,\u0004 וכן \u0003פרה ורצה בין הכרמים\u0004 — \u0003הרי זו אבידה ומיחייב\u0004 \u0005[וחייב]\u0006 \u0003בה\u0004 בהשבה. שנינו שאם מצא חמור או פרה רועים אין זו אבידה.","ושואלים: \u0003ולעולם?!\u0004 גם יראה אותם שוהים שם זמן מרובה אין זו כאבידה? \u0003אמר רב יהודה אמר רב: עד שלשה ימים.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה\u0006 הדבר\u0005]?\u0006 \u0003אי בלילותא\u0004 \u0005[אם בלילות]\u0006 מצא אותם — \u0003אפילו חדא שעתא נמי\u0004 \u0005[שעה אחת גם כן]\u0006 ברור שאין אדם משאיר את בהמתו לרעות בדרך לבדה, ומן הסתם אבידה היא. \u0003אי ביממא\u0004 \u0005[אם\u0006 רק \u0005ביום]\u0006 ראה את הבהמה — \u0003אפילו טובא נמי\u0004 \u0005[הרבה יותר\u0006 משלושה ימים \u0005גם כן]\u0006 \u0003לא!\u0004","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא באופן \u0003דהוה חזי לה בקדמתא ובחשכתא\u0004 \u0005[שהוא רואה אותה במוקדם\u0006 בשחר \u0005וב\u0006שעת \u0005החשיכה\u0006 בלילה\u0005],\u0006 \u0003תלתא יומי אמרינן\u0004 \u0005[שלושה ימים אומרים אנו]\u0006 \u0003:\u0004 \u0003איתרמויי אתרמי לה ונפקא\u0004 \u0005[הזדמן הדבר ויצאה הבהמה]\u0006 מוקדם יותר או מאוחר יותר, ומדעת בעליה היא שם. \u0003טפי\u0004 \u0005[יותר מזה]\u0006 \u0003ודאי אבידה היא.\u0004","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003מצא טלית וקרדום\u0004"],["\u0003באסרטיא\u0004 \u0005[ברחוב ראשי]\u0006 \u0003ופרה רצה בין הכרמים\u0004 — \u0003הרי זו אבידה.\u0004 מצא \u0003טלית בצד גדר,\u0004 או \u0003קרדום בצד גדר,\u0004 או \u0003פרה רועה בין הכרמים\u0004 — \u0003אין זו אבידה.\u0004 ראה את אלה \u0003שלשה ימים זה אחר זה\u0004 — \u0003הרי זו אבידה. ראה מים ששוטפין ובאין\u0004 לשדה חבירו \u0003הרי זה גודר בפניהם\u0004 ואף בכך יש משום השבת אבידה.","\u0003אמר רבא:\u0004 מה שנאמר \u0003\"לכל אבידת אחיך\u0004 אשר תאבד ממנו\u0003\"\u0004 (דברים כב, ג) בא \u0003לרבות אבידת קרקע. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חנניה לרבא: תניא דמסייע\u0004 \u0005[שנויה\u0006 ברייתא \u0005המסייעת]\u0006 \u0003לך,\u0004 ששנינו: \u0003ראה מים ששוטפין ובאין הרי זה גודר בפניהם.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום הא\u0004 \u0005[זו]\u0006 \u0003לא תסייעי\u0004 \u0005[תסייע אותי]\u0006 כי ראיה אין כאן, שכן \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 — \u0003בדאיכא\u0004 \u0005[כשיש]\u0006 \u0003עומרין\u0004 של תבואה בשדה והמציל מציל את העומרים, ולא את הקרקע עצמה. ומקשים: \u0003אי דאיכא\u0004 \u0005[אם יש]\u0006 \u0003עומרין\u0004 בשדה \u0003מאי למימרא\u0004 \u0005[מה יש לומר\u0006 בזה\u0005]?\u0006 הלא מובן מעצמו שחייב להציל את ממון חבירו! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה],\u0006 אלא לאופן \u0003דאית\u0004 \u0005[שיש]\u0006 \u0003בה עומרין דצריכי לארעא\u0004 \u0005[הצריכים\u0006 עדיין \u0005לקרקע]\u0006 להתייבש שם, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003כיון דצריכי לארעא\u0004 \u0005[שצריכים\u0006 הם עדיין \u0005לקרקע]\u0006 \u0003כי גופה דארעא דמיין\u0004 \u0005[כגופה של הקרקע\u0006 הם \u0005נחשבים]\u0006 ואינם בכלל אבידה סתם אלא אבידת קרקע הם, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 הלכה זו.","שנינו במשנה שאם \u0003מצא חמור ופרה\u0004 רצים בדרך הרי זו אבידה. ותוהים: \u0003הא גופה קשיא\u0004 \u0005[היא עצמה קשה]!\u0006 \u0003אמרת\u0004 מצד אחד שאם \u0003מצא חמור ופרה רועין בדרך\u0004 — \u0003אין זו אבידה,\u0004 ונדייק: דווקא אם \u0003רועין בדרך הוא דלא הוו\u0004 \u0005[שאינם]\u0006 \u0003אבידה, הא\u0004 \u0005[הרי]\u0006 אם היתה הפרה \u0003רצה בדרך\u0004 או \u0003רועה בין הכרמים הויא\u0004 \u0005[הריהי]\u0006 \u0003אבידה.\u0004 ואולם \u0003אימא סיפא\u0004 \u0005[אמור את סופה]\u0006 של המשנה: \u0003חמור וכליו הפוכים ופרה רצה בין הכרמים\u0004 — \u0003הרי זו אבידה.\u0004 ונדייק מכאן: \u0003רצה בין הכרמים\u0004 דווקא \u0003הוא דהויא\u0004 \u0005[שהיא]\u0006 \u0003אבידה, הא\u0004 \u0005[הרי]\u0006 אם היתה \u0003רצה בדרך\u0004 או \u0003רועה בין הכרמים\u0004 — \u0003אין זו אבידה.\u0004 שעל ידי הדיוק יש סתירה מראשה לסופה של המשנה!","\u0003אמר אביי:\u0004 כאן יש לנקוט בכלל הפרשני שאפשר לבטא במליצה בלשון הכתוב \u0003\"יגיד עליו רעו\"\u0004 (איוב לו, לג), וכך יש להבין: \u0003תנא\u0004 \u0005[שנה]\u0006 החכם \u0003רועה בדרך דלא הויא\u0004 \u0005[שאינה]\u0006 \u0003אבידה\u0004 ודאי, \u0003והוא הדין ל\u0004פרה ה\u0003רועה בין הכרמים\u0004 שאין זו אבידה. וכן \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003רצה בין הכרמים דהויא\u0004 \u0005[שהיא]\u0006 \u0003אבידה, והוא הדין לרצה בדרך.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: אי\u0004 \u0005[אם]\u0006 בדרך של \u0003\"יגיד עליו רעו\"\u0004 למדים כאן, אם כן \u0003ליתני קילתא\u0004 \u0005[שישנה\u0006 את \u0005הקלה],\u0006 \u0003וכל שכן חמירתא\u0004 \u0005[\u0006את \u0005החמורה];\u0006 \u0003ליתני\u0004 \u0005[שישנה]\u0006 \u0003רצה בדרך דהויא\u0004 \u0005[שהיא]\u0006 \u0003אבידה, וכל שכן\u0004 ש\u0003רצה בין הכרמים\u0004 היא אבידה, \u0003ולתני\u0004 \u0005[ושישנה]\u0006 \u0003רועה בין הכרמים דלא הויא\u0004 \u0005[שאינה]\u0006 \u0003אבידה וכל שכן רועה בדרך.\u0004","\u0003אלא\u0004 \u0003אמר רבא\u0004 יש לחזור בנו ממה שאמרנו, וכך יש לתרץ: \u0003רצה\u0004 על \u0003רצה לא קשיא\u0004 \u0005[אינו קשה],\u0006 ויש לומר \u0003הא דאפה לגבי דברא\u0004 \u0005[זו שפניה כלפי השדה],\u0006 שבורחת מן העיר לשדה ובכגון זה היא נחשבת כאבידה, \u0003הא דאפה לגבי מתא\u0004 \u0005[וזו שפניה כלפי העיר],\u0006 ובכגון זה אינה נחשבת לאבידה.","\u0003רועה\u0004 על \u0003רועה נמי לא קשיא\u0004 \u0005[גם כן אינו קשה],\u0006 \u0003כאן\u0004 דנים לגבי \u0003אבידת גופה\u0004 של הפרה עצמה, ו\u0003כאן באבידת קרקע\u0004 שהיא גורמת נזקים.","וכך נבין: \u0003כי קתני\u0004 \u0005[כאשר שנה]\u0006 \u0003רועה בדרך לא הויא\u0004 \u0005[אינה]\u0006 \u0003אבידה,\u0004 ודייקנו: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003רועה בין הכרמים הויא\u0004 \u0005[הריהי]\u0006 \u0003אבידה,\u0004 ונבין הדבר לגבי \u0003אבידת קרקע.\u0004 \u0003וכי קתני\u0004 \u0005[וכאשר שנה]\u0006 \u0003רצה בין הכרמים הויא\u0004 \u0005[הריהי]\u0006 \u0003אבידה, הא\u0004 \u0005[הרי]\u0006 \u0003רועה בין הכרמים לא הויא אבידה,\u0004 הכוונה היא ל\u0003אבידת גופה\u0004 של הפרה עצמה, שזו ה\u0003רצה בין הכרמים\u0004 הריהי \u0003מסקבא\u0004 \u0005[נחבלת],\u0006 \u0003ורועה בין הכרמים לא מסקבא\u0004 \u0005[אינה נחבלת].\u0006","ושואלים: \u0003ורועה בין הכרמים, נהי דלא מסקבא תיפוק ליה\u0004 \u0005[אם אמנם שאיננה נחבלת, תצא לו]\u0006 ההלכה שצריך להחזירה \u0003משום אבידת קרקע,\u0004 שהרי היא מפסידה את הכרם! ומשיבים: מדובר כאן \u0003ב\u0004שדה של \u0003גוי,\u0004 שאיננו חייב להשיב אבידתו.","ומקשים: אף אז \u0003ותיפוק ליה\u0004 \u0005[ותא לו]\u0006 \u0003משום אבידת גופה\u0004 של הפרה, \u0003דדלמא קטלו לה\u0004 \u0005[שמא יהרגו אותה]\u0006 בעלי השדה הגויים! ומשיבים: מדובר כאן \u0003באתרא דמתרו והדר קטלי\u0004 \u0005[במקום ש\u0006קודם \u0005מתרים\u0006 בבעלים \u0005ואחר כך הורגים].\u0006 ושואלים: \u0003ודלמא אתרו\u0004 \u0005[ושמא\u0006 כבר \u0005התרו]\u0006 \u0003בה,\u0004 בבעליה של בהמה זו, ועכשיו יהרגו אותה! ומשיבים: \u0003אי אתרו\u0004 \u0005[אם התרו]\u0006 \u0003בה,\u0004 בבהמה, \u0003ולא אזדהרו\u0004 \u0005[נזהרו]\u0006 \u0003בה\u0004 בעליה \u0003ודאי אבידה מדעת היא,\u0004 ואין המוצא חייב לטפל בה.","שנינו במשנה שאם \u0003החזירה\u0004 לבעליה \u0003וברחה,\u0004 ושוב \u0003החזירה וברחה\u0004 — מחזירה אפילו כמה וכמה פעמים, משום שנאמר \"השב תשיבם\". \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ההוא מדרבנן\u0004 \u0005[אחד מהחכמים]\u0006 \u0003לרבא, אימא\u0004 \u0005[אמור]\u0006 שנפרש כך: \u0003\"השב\"\u0004 — פירושו \u0003חדא זמנא\u0004 \u0005[פעם אחת],\u0006 \u0003\"תשיבם\"\u0004 — \u0003תרי זמני\u0004 \u0005[שתי פעמים]\u0006 ולא יותר!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003\"השב\" אפילו מאה פעמים משמע,\u0004 כלומר שישיב עד שתהא האבידה מוחזרת. \u0003\"תשיבם\"\u0004 בא ללמד לענין אחר: \u0003אין לי\u0004 ממשמעות הכתוב \u0003אלא\u0004 שישיב את האבידה \u0003לביתו\u0004 ממש של המאבד, ואולם אם השיב \u0003לגינתו\u0004 או \u0003לחורבתו מנין?\u0004 — \u0003תלמוד לומר: \"תשיבם\",\u0004 ללמד: \u0003מכל מקום\u0004 יש בכך השבה. ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]\u0006 שמחזיר לגינתו ולחורבתו? \u0003אי דמינטרא\u0004 \u0005[אם ש\u0006היא, האבידה \u0005נשמרת]\u0006 שם, \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שיש בכך השבה גמורה, \u0003אי דלא מינטרא\u0004 \u0005[אם שאיננה נשמרת שם]\u0006 ועלולה לברוח ולהיאבד שנית, \u0003אמאי\u0004 \u0005[מדוע]\u0006 ייחשב הדבר להשבה?","ומשיבים: \u0003לעולם\u0004 צריך לומר \u0003דמינטרא\u0004 \u0005[שנשמרת\u0006 שם\u0005],\u0006 \u0003והא קא משמע לן\u0004 \u0005[ו\u0006דבר \u0005זה השמיע לנו]:\u0006 \u0003דלא בעינן\u0004 \u0005[שאין אנו צריכים]\u0006 בכגון זה \u0003דעת\u0004 ה\u0003בעלים,\u0004 שאין חובה להודיעם שהחזיר אבידתם. \u0003וכ\u0004דברי \u0003רבי אלעזר\u0004 ש\u0003אמר: הכל צריכין דעת בעלים,\u0004 כלומר, כל ממון שהוא מחזיר לבעליו כגון פקדון שהופקד אצלו, או גניבה שגנב — צריך להודיע לבעליו שהחזיר \u0003חוץ מהשבת אבידה.\u0004 לפי \u0003שהתורה ריבתה\u0004 באבידה \u0003השבות הרבה\u0004 (\"תשיבם\") ולא הקפידה בכך. בדומה לדין זה מביאים גם מדרש על הלכה אחרת, בהלכות שילוח הקן, שגם שם למדים מכפילות המילים שחובה לקיים מצוות שילוח אפילו הרבה פעמים.","ושאלו: נאמר \u0003\"שלח תשלח\u0004 את האם\u0003\"\u0004 (דברים כב, ז), \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003\"שלח\"\u0004 משמעו \u0003חדא זימנא\u0004 \u0005[פעם אחת],\u0006 \u0003\"תשלח\" תרי זמני\u0004 \u0005[שתי פעמים]!\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003\"שלח\"\u0004 — \u0003אפילו מאה פעמים משמע,\u0004 עד שתהיה משולחת, \u0003\"תשלח\"\u0004 כוונתו להוסיף: \u0003אין לי אלא לדבר הרשות\u0004 כשלוקח את האפרוחים לצורכו, אבל כשיש מי שרוצה לקחת את הציפור \u0003לדבר מצוה\u0004 כגון לקרבן או לטהרת מצורע \u0003מנין? תלמוד לומר: \"תשלח\",\u0004 בהדגשה: \u0003מכל מקום.\u0004","\u0003אמר ליה ההוא מדרבנן\u0004 \u0005[לו אחד מהחכמים]\u0006 \u0003לרבא\u0004 על מצוות תוכחה הנלמדת מן המילים \"הוכח תוכיח את עמיתך\" (ויקרא יט, יז): \u0003ואימא\u0004 \u0005[ואמור]\u0006 \u0003\"הוכח\" חדא זימנא\u0004 \u0005[פעם אחת],\u0006 \u0003\"תוכיח\" תרי זמני\u0004 \u0005[שתי פעמים]\u0006 ולא יותר?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003\"הוכח\"\u0004 — \u0003אפילו מאה פעמים משמע. \"תוכיח\"\u0004 שהוא כלשון ריבוי, כוונתו: \u0003אין לי אלא\u0004 ש\u0003הרב\u0004 רשאי להוכיח \u0003לתלמיד,\u0004 ואולם שה\u0003תלמיד\u0004 רשאי וצריך להוכיח \u0003לרב מנין?\u0004 — \u0003תלמוד לומר: \"הוכח תוכיח\" מכל מקום.\u0004","מתוך דמיון הלימוד הצורני, דנים גם בהלכות אחרות; שדרשו על הכתוב \u0003\"\u0004כי תראה חמור שונאך רובץ תחת משאו וחדלת מעזוב לו \u0003עזב תעזב עמו\"\u0004 (שמות כג, ה), \u0003אין לי אלא בעליו עמו, שאין בעליו עמו מנין\u0004 שצריך לעזור לפרוק את הבהמה? — \u0003תלמוד לומר \"עזב תעזב\", מכל מקום.\u0004","וכן ממה שנאמר \u0003\"\u0004לא תראה את חמור אחיך או שורו נופלים בדרך והתעלמת מהם \u0003הקם תקים עמו\"\u0004 (דברים כב, ד), \u0003אין לי אלא בעליו עמו,\u0004 ואולם כש\u0003אין בעליו עמו מנין\u0004 שהדין כמו כן? \u0003—\u0004 \u0003תלמוד לומר \"הקם תקים\" מכל מקום.\u0004","ושואלים: \u0003ולמה ליה למכתב\u0004 \u0005[לו לכתוב]\u0006 הלכה זו גם ב\u0003פריקה, ולמה ליה למכתב\u0004 \u0005[לו לכתוב]\u0006 ב\u0003טעינה?\u0004 והרי לכאורה זהים הם! ומשיבים: \u0003צריכי\u0004 \u0005[נצרכו שניהם];\u0006 \u0003דאי כתב רחמנא\u0004 \u0005[שאילו כתבה התורה]\u0006 ב\u0003פריקה\u0004 בלבד \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003משום דאיכא\u0004 \u0005[שיש]\u0006 בדבר שני טעמים: מצד אחד \u0003צער בעלי חיים\u0004 על הבהמה העמוסה, \u0003ואיכא\u0004 \u0005[ויש]\u0006 גם \u0003חסרון כיס,\u0004 שמא תינזק הסחורה או תמות הבהמה, \u0003אבל טעינה, דלאו\u0004 \u0005[שלא]\u0006 \u0003צער בעלי חיים איכא\u0004 \u0005[יש]\u0006 כאן, \u0003ולא חסרון כיס איכא\u0004 \u0005[יש]\u0006 כאן, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יצטרך לטעון, על כן הוצרך להשמיע לנו הלכה זו.","ולהיפך, \u0003ואי אשמעינן\u0004 \u0005[ואילו היה משמיע לנו]\u0006 חובת \u0003טעינה\u0004 בלבד, הייתי אומר \u0003משום\u0004 שטעינה זו \u0003בשכר\u0004 היא, \u0003אבל פריקה\u0004 שהיא \u0003בחנם,\u0004 שחייב לעשותה ללא תמורה, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 על כן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 גם הלכה זו.","ושואלים: \u0003ול\u0004דעת \u0003ר' שמעון\u0004 ש\u0003אמר: אף טעינה\u0004 צריכה להיות \u0003בחנם, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ומשיבים: \u0003לר' שמעון לא מסיימי קראי\u0004 \u0005[אין הכתובים מבוררים]\u0006 איזהו בפריקה ואיזה בטעינה, ולכן צריכים שניהם.","ושואלים עוד: \u0003למה לי למכתב הני תרתי\u0004 \u0005[לכתוב\u0006 את \u0005שני אלה]\u0006 בפריקה וטעינה, \u0003ולמה לי למכתב\u0004 \u0005[לכתוב]\u0006 גם דין \u0003אבידה,\u0004 שהרי לכאורה בכולם אותו טעם עצמו! ומשיבים: \u0003צריכי\u0004 \u0005[נצרכו]\u0006 כולם. \u0003דאי כתב רחמנא הני תרתי\u0004 \u0005[שאילו כתבה התורה\u0006 את \u0005שני אלה]\u0006 פריקה וטעינה בלבד, ההיתי אומר שהוא כן \u0003משום דצערא דמרה איתא\u0004 \u0005[שצער בעליה יש\u0006 כאן\u0005],\u0006 \u0003צערא דידה איתא\u0004 \u0005[צער שלה,\u0006 של הבהמה \u0005יש\u0006 כאן\u0005],\u0006 שסובלת מחמת המשא. \u0003אבל אבידה, דצערא דמרה איתא וצערא דידה ליתא\u0004 \u0005[שצער של בעליה יש כאן ו\u0006אולם \u0005צער שלה אין],\u0006 שהרי היא רועה בדרך להנאתה, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יצטרך להשיבה. ולהיפך, \u0003ואי אשמעינן\u0004 \u0005[ואילו היה משמיע לנו]\u0006 \u0003אבידה\u0004 בלבד, הייתי אומר שבה צריך לטפל \u0003משום דליתא למרה בהדה\u0004 \u0005[שאין בעליה עמה]\u0006 ואין מי שיטרח בהשבתה."],["\u0003אבל הני תרתי דאיתא למרה בהדה\u0004 \u0005[אלה השתיים,\u0006 פריקה וטעינה \u0005שבעליה ישנו עמה]\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 על כן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 לומר בכולם.","ועוד בפירוש דרשות בהלכה מלשונות כפולים בתורה: נאמר בדין הרוצח שנגזר דינו \u0003\"מות יומת המכה\"\u0004 (במדבר לה, כא), כוונתו: \u0003אין לי אלא\u0004 שממיתו \u0003במיתה הכתובה בו\u0004 שהיא מיתת סייף. \u0003מנין שאם אי אתה יכול להמיתו במיתה הכתובה בו\u0004 כגון שברח, \u0003שאתה רשאי להמיתו בכל מיתה שאתה יכול להמיתו,\u0004 וכגון בחץ? \u0003—\u0004 \u0003תלמוד לומר: \"מות יומת\",\u0004 ללמדנו: יומת \u0003מכל מקום,\u0004 בכל דרך שהיא.","וכן מה שנאמר באנשי עיר הנדחת \u0003\"הכה תכה\u0004 את יושבי העיר ההיא לפי חרב\u0003\"\u0004 (דברים יג, טז), \u0003אין לי אלא בהכאה הכתובה בהן\u0004 שהיא בסייף, \u0003מנין שאם אי אתה יכול להמיתן בהכאה הכתובה בהן שאתה רשאי להכותן בכל הכאה שאתה יכול?\u0004 — \u0003תלמוד לומר \"הכה תכה\", מכל מקום.\u0004","ועוד מפורש בכפילות זו: נאמר בדיני משכון מעני שאם משכנו דבר שצריך לו, וכגון שמשכנו כר וצריך הוא לו לשינה, על כגון זה צוותה התורה \u0003\"השב תשיב\u0004 לו את העבוט כבוא השמש\u0003\"\u0004 (דברים כד, יג), \u0003אין לי\u0004 שחייב להשיב לו משכונו \u0003אלא\u0004 כ\u0003שמשכנו,\u0004 את החפץ, \u0003ברשות בית דין,\u0004 ואולם אם \u0003משכנו שלא ברשות בית דין, מנין\u0004 שמצווה להשיב? — \u0003תלמוד לומר: \"השב תשיב\", מכל מקום.\u0004","ועוד בדין השבת משכון לבעליו: ממה שנאמר \"אם \u0003חבל תחבל\u0004 שלמת רעך עד בוא השמש תשיבנו לו\" (שמות כב, כה), \u0003אין לי אלא שמשכנו ברשות,\u0004 ואולם \u0003כש\u0004\u0003משכנו שלא ברשות מנין?\u0004 — \u0003תלמוד לומר:\u0004 בכפילות \u0003\"חבל תחבל\", מכל מקום.\u0004","אגב הזכרת הכתוב שואלים: \u0003והני תרי קראי\u0004 \u0005[ושני כתובים אלו]\u0006 \"השב תשיב\" ו\"חבל תחבול\" המדברים באותה הלכה \u0003למה לי?\u0004 ומשיבים: \u0003חד\u0004 \u0005[אחד]\u0006 מהם בא ללמד \u0003לכסות יום, וחד לכסות לילה.\u0004","ועוד, ממה שנאמר במצות הלוואה וצדקה \u0003\"פתח תפתח\u0004 את ידך לאחיך לעניך ולאביונך בארצך\u0003\"\u0004 (דברים טו, יא), \u0003אין לי אלא\u0004 שחייב לפתוח את ידו \u0003לעניי עירך, לעניי עיר אחרת מנין?\u0004 — \u0003תלמוד לומר: \"פתח תפתח\", מכל מקום.\u0004","נאמר בצדקה \u0003\"\u0004השמר לך... ורעה עינך באחיך האביון... \u0003נתן תתן\"\u0004 (דברים טו, ט–י), \u0003אין לי אלא\u0004 שיתן אם הוא יכול לתת \u0003מתנה מרובה, מתנה מועטת מנין?\u0004 — \u0003תלמוד לומר: \"נתן תתן\", מכל מקום.\u0004","נאמר בדין שחרור עבד עברי \u0003\"העניק תעניק\"\u0004 (שם יד), \u0003אין לי אלא\u0004 שכ \u0003שנתברך הבית בגללו מעניקין\u0004 לו, שאז מתקיים אותו הכתוב כלשונו, ואולם \u0003לא נתברך הבית בגללו מנין\u0004 שמעניקין? \u0003תלמוד לומר \"העניק תעניק\",\u0004 כוונתו: \u0003מכל מקום.\u0004","ושואלים: \u0003ול\u0004דעת \u0003ר' אלעזר בן עזריה,\u0004 ש\u0003אמר:\u0004 אם \u0003נתברך הבית בגללו\u0004 — \u0003מעניקין לו, לא נתברך הבית בגללו\u0004 — \u0003אין מעניקין\u0004 לו, אם כן \u0003\"תעניק\"\u0004 שהוא מיותר שם \u0003למה לי?\u0004 ומשיבים: לשיטתו \u0003דברה תורה כלשון בני אדם\u0004 שכפילות בסגנון זה היא לשון התורה הרגילה, ואין ללמוד ממנה להלכה.","נאמר במצות הלוואה לעני \"כי פתוח תפתח את ידך לו ו\u0003העבט תעביטנו\u0004 די מחסורו\" (שם ח), \u0003אין לי אלא\u0004 במקרה \u0003שאין לו\u0004 לאותו אדם \u0003ואינו רוצה להתפרנס\u0004 מן הצדקה, על כך \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003תן לו דרך הלואה.\u0004 ואולם אם \u0003יש לו\u0004 לאדם \u0003ואינו רוצה להתפרנס\u0004 משלו \u0003מנין\u0004 שחובה להלוותו, ולגבות אחר כך מנכסיו? — \u0003תלמוד לומר: \"תעביטנו\"\u0004 — \u0003מכל מקום.\u0004","ושואלים, \u0003ול\u0004שיטת \u0003ר' שמעון\u0004 ש\u0003אמר:\u0004 מי ש\u0003יש לו ואינו רוצה להתפרנס\u0004 משלו \u0003אין נזקקין לו,\u0004 אם כן \u0003\"תעביטנו\"\u0004 שהוא מיותר \u0003למה לי?\u0004 ומשיבים: לשיטתו \u0003דברה תורה כלשון בני אדם.\u0004","שנינו במשנה שמי שמצא אבידה ו\u0003היה בטל מן ה\u0004עבודה שמרויח בה \u0003סלע\u0004 בשל השבתה, \u0003לא יאמר לו\u0004 לבעל האבידה \u0003\"תן לי סלע\", אלא נותן לו שכרו כפועל בטל. תנן\u0004 \u0005[שנה]\u0006 החכם בתוספתא: \u0003נותן לו שכרו כפועל בטל.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה פירוש]\u0006 \u0003כפועל בטל?\u0004 שהרי אינו בטל לגמרי, אלא עוסק באבידה! \u0003אמר אביי: כפועל בטל של אותה מלאכה\u0004 ש\u0003בטל מינה\u0004 \u0005[ממנה],\u0006 כלומר, מעריכים כמה רוצה אדם שלא יעבוד עבודה קשה ומסובכת שהוא עוסק בה, ויעסוק במלאכה קלה כזו, אף שבכך הוא מקבל פחות שכר, והדבר תלוי איפוא בכובד מלאכתו ובריבוי שכרה.","שנינו במשנה: \u0003אם יש שם בית דין\u0004 — \u0003מתנה בפניהם.\u0004 מסופר: הסוחר \u0003איסור ורב ספרא עביד עיסקא בהדי הדדי\u0004 \u0005[עשו עיסקה יחד].\u0006 \u0003אזל\u0004 \u0005[הלך]\u0006 \u0003רב ספרא פלג ליה\u0004 \u0005[חילק אותה,\u0006 את השותפות\u0005]\u0006 \u0003בלא דעתיה\u0004 \u0005[דעתו,\u0006 רשותו\u0005]\u0006 של \u0003איסור באפי בי תרי\u0004 \u0005[בפני שניים]\u0006 שישמשו כעדים. \u0003אתא לקמיה\u0004 \u0005[בא\u0006 הענין \u0005לפני]\u0006 \u0003רבה בר רב הונא, אמר ליה\u0004 \u0005[לו]\u0006 רבה בר רב הונא לרב ספרא: \u0003זיל אייתי תלתא דפלגת קמייהו\u0004 \u0005[לך הבא\u0006 את \u0005שלושת\u0006 האנשים \u0005שחלקת לפניהם],\u0006 כלומר, הבא את בית הדין שבפניו חלקת, \u0003אי נמי\u0004 \u0005[או גם כן]\u0006"],["\u0003תרי מגו תלתא\u0004 \u0005[שנים מתוך שלושה]\u0006 שיעידו ששלושה היו וחלקת בפניהם, \u0003ואי נמי תרי סהדי דפלגת באפי בי תלתא\u0004 \u0005[ואו גם כן\u0006 הבא \u0005שני עדים שיעידו שחלקת בפני שלושה].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב ספרא: \u0003מנא\u0004 \u0005[מנין]\u0006 \u0003לך הא\u0004 \u0005[\u0006דבר \u0005זה]\u0006 שצריך לעשות זאת בפני בית דין דווקא? \u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אם יש שם בית דין\u0004 — \u0003מתנה בפניהם, אין שם בית דין\u0004 — \u0003בפני מי יתנה?\u0004 — במקרה זה \u0003שלו קודם,\u0004 שכיון שעלול להפסיד בכך אינו צריך להשיב. משמע שאין רשות לקבוע דברים לגבי ממון חבירו אלא בפני בית דין.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב ספרא: \u0003מי דמי\u0004 \u0005[וכי דומה]\u0006 הדבר! \u0003התם דמפיק ממונא מהאי ומותיב להאי בעינן\u0004 \u0005[שם שמוציא כסף מזה ונותן לזה צריכים אנו]\u0006 \u0003בית דין, אבל הכא דידיה שקלי\u0004 \u0005[כאן את שלו,\u0006 כלומר, שלי, \u0005לקחתי]\u0006 \u0003גילוי מילתא בעלמא\u0004 \u0005[גילוי דברים בלבד]\u0006 \u0003הוא\u0004 שיראו שחלקתי ביושר ואם כן \u0003בתרי סגי ליה\u0004 \u0005[בשנים די לו,\u0006 לי\u0005].\u0006 \u0003תדע\u0004 שכן הוא, שבדבר כגון זה אין צורך בשלושה, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אלמנה מוכרת\u0004 למזונותיה מרכוש הנפטר \u0003שלא בפני בית דין,\u0004 משמע שאם אדם לוקח את השייך לו איננו זקוק לבית דין!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ולאו מי אתמר עלה\u0004 \u0005[והאם לא נאמר עליה],\u0006 על הלכה זו: \u0003אמר רב יוסף בר מניומי אמר רב נחמן:\u0004 אמנם \u0003אלמנה אינה צריכה בית דין של מומחין, אבל צריכה\u0004 לפחות \u0003בית דין של הדיוטות,\u0004 שלושה אנשים סתם שיהו בית דין, שיאשרו את הדבר. ואם כן, שלא כדין עשה רב ספרא.","\u0003מצאה\u0004 את הבהמה \u0003ברפת\u0004 — \u0003אין חייב בה\u0004 בהשבה. מצאה \u0003ברשות הרבים\u0004 — \u0003חייב בה. ואם היתה בבית הקברות\u0004 והוא כהן — \u0003לא יטמא לה.\u0004 והלכה כללית: \u0003אם אמר לו אביו\u0004 לכהן: \u0003\"היטמא\u0004 למתים \u0003\",\u0004 \u0003או שאמר לו\u0004 לבנו \u0003\"אל תחזיר\u0004 אבידה \u0003\"\u0004— \u0003לא ישמע לו\u0004 לאביו, שאין עוברים על דברי תורה מפני כבוד אב.","\u0003פרק וטען\u0004 מעל גבי בהמה הנופלת תחת משאה, \u0003פרק וטען, אפילו ארבעה וחמישה פעמים\u0004 — \u0003חייב, שנאמר \"עזב תעזב\"\u0004 (שמות כג, ה).","\u0003הלך\u0004 בעל הבהמה \u0003וישב לו, ואמר: \"הואיל ועליך מצוה, אם רצונך לפרוק\u0004 — \u0003פרוק\",\u0004 הרי זה \u0003פטור\u0004 מלעשות זאת, \u0003שנאמר:\u0004 \u0003\"\u0004עזוב תעזוב \u0003עמו\"\u0004 — עם בעל הבהמה, ואם ההוא עצמו איננו עוסק בכך, אף הזר אינו חייב לעזור לו. \u0003אם היה\u0004 בעל הבהמה \u0003זקן או חולה\u0004 שאינו יכול לסייע לעובר הדרך — הרי \u0003חייב\u0004 עובר הדרך לעשות זאת.","ובענין מצוה זו: \u0003מצוה מן התורה לפרוק\u0004 משא מן הבהמה \u0003אבל לא\u0004 צוותה התורה \u0003לטעון\u0004 עליה. \u0003ר' שמעון אומר:\u0004 מצוה \u0003אף לטעון.\u0004","\u0003ר' יוסי הגלילי אומר:\u0004 בכלל, \u0003אם היה עליו\u0004 על החמור או השור \u0003יתר על משאו\u0004 — \u0003אין זקוק לו\u0004 לעזור לו, \u0003שנאמר: \"תחת משאו\"\u0004 (שם), משמע \u0003משאוי שיכול לעמוד בו,\u0004 שאם היה טעון יותר מזה, הרי זו אשמת בעל הבהמה.","\u0003אמר רבא: רפת שאמרו\u0004 חכמים במשנה זו הכוונה היא ש\u0003אינה מתעה,\u0004 כלומר, שאינה גורמת לבהמה שתברח ממנה, אבל גם \u0003אינה משמרת,\u0004 שבהמה יכולה לצאת משם. ומנין שכך הוא הפירוש? \u0003אינה מתעה\u0004 — \u0003מדקתני\u0004 \u0005[ממה ששנה]\u0006 \u0003\"אינו חייב בה\",\u0004 משמע שאיננה נחשבת כאבידה, \u0003ואינה משמרת\u0004 — \u0003מדאיצטריך למיתני\u0004 \u0005[מכיון שהיה צריך בכלל לשנות]\u0006 \u0003\"אינו חייב בה\".\u0004","\u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר שרפת זו \u0003משמרת, השתא משכח לה אבראי מעייל לה לגואי\u0004 \u0005[עכשיו, הרי,\u0006 אילו \u0005היה מוצא אותה בחוץ היה מכניס אותה בפנים]\u0006 לרפת כגון זו, ואם כן \u0003משכח לה מגואי מבעיא\u0004 \u0005[אם מצאה בפנים נצרכה לומר]\u0006 שאינו צריך לטפל בה? \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 שרפת זו \u0003אינה משמרת,\u0004 ומסכמים: אכן, \u0003שמע מינה.\u0004","על האמור שאם \u0003מצאה ברפת אינו חייב, אמר ר' יצחק: והוא שעומדת\u0004 הרפת \u0003תוך לתחום\u0004 העיר. ומעירים: \u0003מכלל\u0004 שאם היתה הפרה \u0003ברשות הרבים, ואפילו בתוך התחום נמי\u0004 \u0005[גם כן]\u0006 \u0003חייב.\u0004","\u0003איכא דמתני לה אסיפא\u0004 \u0005[יש ששונה את\u0006 דברי ר' יצחק \u0005על סופה\u0006 של המשנה\u0005]\u0006 ששנינו \u0003ברשות הרבים חייב בה. אמר ר' יצחק: והוא שעומדת חוץ לתחום.\u0004 ומכאן מדייקים: \u0003מכלל\u0004 ש\u0003ברפת אפילו\u0004 אם היתה \u0003עומדת חוץ לתחום נמי\u0004 \u0005[גם כן]\u0006 \u0003אינו חייב בה.\u0004","שנינו במשנה: היתה האבידה \u0003בבית הקברות\u0004 והוא כהן — \u0003לא יטמא לה\u0004 וכו'. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מנין שאם אמר לו אביו\u0004 לכהן \u0003\"היטמא\u0004 למתים \u0003\",\u0004 \u0003או שאמר לו \"אל תחזיר\u0004 אבידה \u0003\"\u0004\u0003שלא ישמע לו? שנאמר \"איש אמו ואביו תיראו ואת שבתתי תשמרו אני ה' \"\u0004(ויקרא יט, ג), הדגשה זו \"אני ה' \" באה לומר: \u0003כולכם חייבין בכבודי,\u0004 ולכן כשה' מצווה על שמירת המצוות חייבים כולם בכך.","ושואלים: \u0003טעמא דכתב רחמנא\u0004 \u0005[הטעם,\u0006 דווקא, \u0005שכתבה התורה]\u0006 \u0003\"את שבתתי תשמרו\" הא לאו הכי הוה אמינא צייתא ליה\u0004 \u0005[הרי לולא זאת הייתי אומר שיציית לו\u0006 לאביו\u0005]?\u0006 \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 יעשה זאת? \u0003האי\u0004 \u0005[זה],\u0006 כבוד אביו, מצוות \u0003עשה\u0004 הוא (\"כבד את אביך ואת אמך\". שמות כ, יב. דברים ה, טז), \u0003והאי\u0004 \u0005[וזה]\u0006 האיסור לכהן להיטמא למתים, גם מצות \u0003לא תעשה\u0004 (\"לנפש לא יטמא בעמיו\". ויקרא כא, א), \u0003ו\u0004גם מצות \u0003עשה\u0004 (\"קדושים תהיו\". שם יט, ב) יש בכך, \u0003ו\u0004כלל הוא: \u0003לא אתי\u0004 \u0005[בא]\u0006 \u0003עשה ודחי\u0004 \u0005[ודוחה]\u0006 \u0003את לא תעשה ועשה!\u0004","ומשיבים: \u0003איצטריך\u0004 \u0005[נצרך הדבר\u0006 להיאמר\u0005]\u0006 בכל זאת. כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003הואיל והוקש\u0004 \u0005[והושווה]\u0006 בכתוב \u0003כיבוד אב ואם לכבודו של מקום, שנאמר כאן \"כבד את אביך ואת אמך\"\u0004 (שמות כ, יג. דברים ה, טז), \u0003ונאמר להלן \"כבד את ה' מהונך\"\u0004 (משלי ג, ט), שבשניהם יש חובת כבוד, \u0003הלכך לציית ליה\u0004 \u0005[על כן יציית לו]\u0006 לאב, ולכן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003לא לשמע ליה\u0004 \u0005[ישמע לו]\u0006 לעבור על כבוד שמים.","שנינו במשנה: \u0003מצוה מן התורה לפרוק אבל לא לטעון.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה פירוש]\u0006 \u0003אבל לא לטעון? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003אבל לא לטעון כלל,\u0004 שאין מצוה כזו, \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003פריקה, דכתיב\u0004 \u0005[שנאמר]\u0006 בכתוב \u0003\"עזב תעזב עמו\"\u0004 (שמות כג, ה), \u0003טעינה נמי הכתיב\u0004 \u0005[גם כן הרי כתוב]\u0006 \u0003\"הקם תקים עמו\"\u0004 (דברים כב, ד), הרי שחייב לטעון!","\u0003אלא\u0004 כך יש להבין את המשנה: \u0003מצוה מן התורה לפרוק בחנם,\u0004 אבל \u0003לא לטעון בחנם אלא בשכר.\u0004 שאמנם מצווה הוא לעזור בטעינה, אבל רשאי ליטול שכר על עבודתו. ואילו \u0003ר' שמעון אומר: אף לטעון\u0004 חייב \u0003בחנם.\u0004 ומעירים: \u0003תנינא להא\u0004 \u0005[שנינו\u0006 דבר \u0005זה]\u0006 כמפורש בברייתא, \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 \u0003פריקה בחנם, טעינה בשכר. ר' שמעון אומר: זו וזו בחנם.\u0004","ושואלים: \u0003מאי טעמייהו דרבנן\u0004 \u0005[מה טעמם של חכמים]\u0006 לחלק? ומשיבים: \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לפרש את הכתובים \u0003כר' שמעון\u0004 ששניהם מצוה, ובחינם, אם כן \u0003לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 רק מצות \u0003טעינה, ולא בעי\u0004 \u0005[יהיה צורך]\u0006 ללמד במצות \u0003פריקה. ואנא אמינא\u0004 \u0005[ואני אומר\u0006 מדעתי\u0005]\u0006 קל וחומר זה: \u0003ומה טעינה דלית\u0004 \u0005[שאין]\u0006 \u0003בה\u0004 \u0003צער בעלי חיים וליכא\u0004 \u0005[ואין\u0006 בה\u0005]\u0006 \u0003חסרון כיס\u0004 — לבעלים \u0003חייב\u0004 לטעון, \u0003פריקה דאית\u0004 \u0005[שיש]\u0006 \u0003בה\u0004 \u0003צער בעלי חיים\u0004 על הבהמה העמוסה, \u0003ו\u0004גם \u0003חסרון כיס,\u0004 שמא תינזק הסחורה או תמות הבהמה, \u0003לא כל שכן\u0004 שחייב? \u0003אלא למאי הלכתא כתביה רחמנא\u0004 \u0005[לאיזו הלכה כתבתו התורה\u0006 במפורש\u0005]?\u0006 — \u0003לומר לך\u0004 שיש הבדל בין הדינים: \u0003פריקה\u0004 עושה \u0003בחנם, טעינה\u0004 עושה \u0003בשכר.\u0004","ושואלים: \u0003ור' שמעון מאי טעמא\u0004 \u0005[מה טעם]\u0006 שיטתו? — \u0003משום דלא מסיימי קראי\u0004 \u0005[שאין הכתובים מבוררים],\u0006 שאין ברור מלשון הכתובים היכן נאמר בפריקה והיכן בטעינה.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה הם אומרים לדעתם, \u0003אמאי לא מסיימי קראי\u0004 \u0005[מדוע אין הכתובים מבוררים]?\u0006 הלא \u0003הכא כתיב\u0004 \u0005[כאן נאמר]\u0006 \u0003\"רבץ תחת משאו\"\u0004 (שמות נג, ה) משמע שהמשא עליו וצריך לסייע לפרקו, ו\u0003התם כתיב\u0004 \u0005[שם נאמר]\u0006 \u0003\"נפלים בדרך\"\u0004 (דברים כב, ד), \u0003דרמו אינהו וטעונייהו באורחא\u0004 \u0005[שמוטלים הם,\u0006 הבהמות, \u0005והמטען שלהם בדרך]\u0006 \u0003משמע,\u0004 שכבר פורק המשא, אלא שצריך לחזור ולטעון. \u0003ור' שמעון\u0004 לדעתו \u0003\"נפלים בדרך\" אינהו וטעונייהו עלוייהו\u0004 \u0005[הם ומטענם עליהם]\u0006 \u0003משמע,\u0004 שאפשר לפרש שהבהמה התמוטטה ומשאה עליה וחובתו היא לפרוק מעליה.","\u0003אמר רבא:\u0004"],["\u0003מדברי שניהם,\u0004 גם תנא קמא וגם ר' שמעון המעדיפים פריקה, \u0003נלמד\u0004 כי ההתחשבות ב\u0003צער בעלי חיים\u0004 הוא מצוה \u0003דאורייתא\u0004 \u0005[מן התורה].\u0006 \u0003ואפילו ר' שמעון לא קאמר\u0004 \u0005[אמר]\u0006 שצריך כתוב מיוחד לפריקה, \u0003אלא משום דלא מסיימי קראי\u0004 \u0005[שאין הכתובים מבוררים],\u0006 \u0003אבל\u0004 אילו היו \u0003מסיימי קראי\u0004 \u0005[הכתובים מבוררים]\u0006 \u0003דרשינן\u0004 \u0005[היינו דורשים]\u0006 \u0003קל וחומר, משום מאי\u0004 \u0005[מה]\u0006 מה הבסיס לקל וחומר זה? \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום צער בעלי חיים דרשינן\u0004 \u0005[דורשים אנו]\u0006 אותו?","ודוחים: \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003משום דאיכא\u0004 \u0005[שיש]\u0006 \u0003חסרון כיס\u0004 בפריקה. \u0003והכי קאמר\u0004 \u0005[וכך אמר],\u0006 כך יש להבין את הדבר: \u0003ומה טעינה דלית\u0004 \u0005[שאין]\u0006 \u0003בה חסרון כיס\u0004 — \u0003חייב, פריקה דאית\u0004 \u0005[שיש]\u0006 \u0003בה חסרון כיס, לא כל שכן!\u0004","ודוחים: \u0003ו\u0004כי \u0003טעינה אין בה חסרון כיס? מי לא עסקינן\u0004 \u0005[האם אין אנו עוסקים]\u0006 אף במקרה \u0003דאדהכי והכי בטיל משוקיה\u0004 \u0005[שבין כך ובין כך\u0006 עד שימצא לטעון \u0005יתבטל משוקו]\u0006 ולא יהיה לו למי למכור את סחורתו, \u0003אי נמי אתו גנבי ושקלי\u0004 \u0005[או גם כן יבואו גנבים ויקחו]\u0006 \u0003כל מה דאיכא בהדיה\u0004 \u0005[שיש עמו],\u0006 ונמצא שקל וחומר זה אין בו ממש.","ומביאים ראיה נוספת, \u0003תדע\u0004 ש\u0003צער בעלי חיים דאורייתא\u0004 \u0005[מן התורה]\u0006 הוא, \u0003דקתני סיפא\u0004 \u0005[ששנה בסופה]\u0006 של המשנה: \u0003ר' יוסי הגלילי אומר: אם היה עליו,\u0004 על החמור, \u0003יתר על משאו\u0004 הראוי לו לפי בריאות גופו — \u0003אין זקוק לו, שנאמר\u0004 \u0003\"\u0004רובץ \u0003תחת משאו\"\u0004 (שמות כג, ה) ומשמע — \u0003משאוי שיכול לעמוד בו. לאו\u0004 \u0005[האם לא]\u0006 \u0003מכלל\u0004 הדברים אתה למד שה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]\u0006 כי אפילו כך \u0003זקוק לו\u0004 לסייע בפריקתו? \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום\u0004 ש\u0003צער בעלי חיים דאורייתא\u0004 \u0005[מן התורה]\u0006 הוא?","ודוחים: משם אין ראיה, \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003ב\u0004פירוש הכתוב \u0003\"תחת משאו\" פליגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 ש\u0003ר' יוסי סבר: דרשינן\u0004 \u0005[דורשים אנו]\u0006 \u0003\"תחת משאו\",\u0004 וכוונתו: משא הראוי לו \u0003משאוי שיכול לעמוד בו, ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003לא דרשינן\u0004 \u0005[אין אנו דורשים]\u0006 \u0003\"תחת משאו\"\u0004 באופן זה.","ולהיפך, \u0003תדע\u0004 ש\u0003צער בעלי חיים לאו דאורייתא\u0004 \u0005[אינו מן התורה],\u0006 \u0003דקתני רישא\u0004 \u0005[ששנה בראשה]\u0006 של המשנה: \u0003הלך\u0004 בעל החמור \u0003וישב לו ואמר לו\u0004 למסייע \u0003הואיל ועליך מצוה לפרוק, פרוק\u0004 — \u0003פטור\u0004 מלפרוק, \u0003שנאמר \"עמו\". ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר כי \u0003צער בעלי חיים דאורייתא\u0004 \u0005[מן התורה]\u0006 הוא, \u0003מה לי\u0004 אם \u0003איתיה למריה בהדיה\u0004 \u0005[ישנו בעליו עמו],\u0006 \u0003ומה לי כי ליתיה למריה בהדיה\u0004 \u0005[אם אין בעליו עמו]?\u0006 הלא צערו על בעלי חיים אינו משתנה על ידי כך!","ומשיבים: \u0003לעולם\u0004 תפרש כי \u0003צער בעלי חיים דאורייתא\u0004 \u0005[מן התורה]\u0006 הוא, ואולם \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 שמה שאמרו \u0003\"פטור\"\u0004 כוונתו \u0003פטור לגמרי? ודלמא\u0004 \u0005[ושמא]\u0006 הכוונה \u0003פטור\u0004 לעשות \u0003בחנם, וחייב\u0004 לעשות, אבל מותר לו לגבות ממנו \u0003שכר.\u0004 \u0003והכי קאמר רחמנא\u0004 \u0005[וכך אמרה התורה]:\u0006 \u0003כי איתיה למריה בהדיה\u0004 \u0005[כאשר ישנו בעליו עמו]\u0006 — \u0003עבד גביה\u0004 \u0005[עשה עמו]\u0006 \u0003בחנם, וכי ליתיה למריה בהדיה\u0004 \u0005[וכאשר אין בעליו עמו]\u0006 — \u0003עבד גביה\u0004 \u0005[עשה עמו]\u0006 \u0003בשכר, ולעולם\u0004 תאמר כי \u0003צער בעלי חיים דאורייתא\u0004 \u0005[מן התורה].\u0006","\u0003(סימן\u0004 לראיות הבאות: \u0003בהמת, בהמת, אוהב, שונא, רבצן).\u0004","ומציעים עוד, \u0003לימא מסייע ליה\u0004 \u0005[האם נאמר שנסייע לו]\u0006 שצער בעלי חיים מן התורה, ממה ששנינו בברייתא: \u0003בהמת גוי מטפל בה כבהמת ישראל\u0004 לענין פריקה. \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 כי \u0003צער בעלי חיים דאורייתא\u0004 הוא — \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003מטפל בה כבהמת ישראל, אלא אי אמרת\u0004 \u0005[אומר אתה]\u0006 כי \u0003צער בעלי חיים לאו דאורייתא\u0004 \u0005[לא מן התורה]\u0006 הוא, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003מטפל בה כבהמת ישראל?\u0004 ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 אינו עושה זאת משום מצוה, אלא \u0003משום איבה,\u0004 שכדי שלא תיווצר איבה בין יהודים וגויים, עוזר גם לגויים, אבל לא משום חובת המצוה.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לפרש, \u0003דקתני\u0004 \u0005[ששנה שם]:\u0006 \u0003אם היתה\u0004 הבהמה \u0003טעונה\u0004 בה \u0003יין נסך\u0004 (שהוא איסור הנאה) — \u0003אין זקוק לה\u0004 ואינו צריך לעזרו. \u0003אי אמרת בשלמא לאו דאורייתא\u0004 \u0005[נניח אם אומר אתה\u0006 שצער בעלי חיים \u0005לא מן התורה]\u0006 הוא — \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003אין זקוק לה,\u0004 לפי שיש כאן צד איסור, \u0003אלא אי אמרת דאורייתא\u0004 \u0005[אם אומר אתה\u0006 כי \u0005מן התורה]\u0006 מצווה על צער בעלי חיים, \u0003אמאי\u0004 \u0005[מדוע]\u0006 אם כן \u0003אין זקוק לה?\u0004 ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003ולהטעינה יין נסך\u0004 — \u0003אין זקוק לה\u0004 כי אין בכך צער בעלי חיים, וגם איבה אין כאן, כיון שיכול לומר לגוי שבדבר של איסור אינו רשאי לסייע לו.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו במקום אחר: \u0003בהמת גוי ומשאוי\u0004 של \u0003ישראל\u0004 — על כך נרמז בכתוב \u0003\"וחדלת\u0004 מעזוב לו\u0003\"\u0004 (שמות כג, ה) כלומר, יכול אתה שלא לעזור. \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 ש\u0003צער בעלי חיים דאורייתא\u0004 \u0005[מן התורה]\u0006 הוא, \u0003אמאי\u0004 \u0005[מדוע]\u0006 אם כן אתה נותן לו את האפשרות של \u0003\"וחדלת\"?\u0004 הלא \u0003\"עזב תעזב\" מבעי ליה\u0004 \u0005[צריד היה לו]\u0006 לומר! ומשיבים: \u0003לעולם\u0004 תאמר כי \u0003צער בעלי חיים דאורייתא\u0004 \u0005[מן התורה]\u0006 הוא, ואולם \u0003התם\u0004 \u0005[שם]\u0006 מדובר \u0003בטעינה,\u0004 שאין בה צד צער בעלי חיים.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של הברייתא, ששנינו: היתה זו \u0003בהמת ישראל ומשאוי גוי\u0004 — \u0003\"עזב תעזב\". ואי\u0004 \u0005[ואם]\u0006 \u0003בטעינה, אמאי\u0004 \u0005[מדוע]\u0006 יש בכך \u0003\"עזב תעזב\"?\u0004 ומשיבים: מצוה היא שם \u0003משום צערא\u0004 \u0005[צער]\u0006 ה\u0003ישראל\u0004 שהוא שותף בדבר.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003אפילו רישא נמי\u0004 \u0005[בתחילה גם כן]\u0006 יש לעזור משום צערו של ישראל שהוא שותף בדבר! ומשיבים: \u0003רישא\u0004 \u0005[ראשה]\u0006 של הברייתא מדובר \u0003בחמר גוי, סיפא\u0004 \u0005[הסוף]\u0006 \u0003בחמר ישראל.\u0004 ותוהים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003פסקת,\u0004 מה חתכת להחליט כי דווקא במקרה הראשון מדובר בגוי ובסוף בישראל, מה ההוכחה בדבר? ומשיבים: \u0003סתמא דמלתא\u0004 \u0005[סתמו של דבר]\u0006 \u0003איניש בתר חמריה אזיל\u0004 \u0005[אדם אחר חמורו\u0006 הוא \u0005הולך]\u0006 ולכן, אם היתה זו בהמת גוי — מן הסתם גם החמר גוי הוא, ולהיפך בבהמת ישראל החמר מן הסתם ישראל.","על ההסבר שבברייתא זו מדובר בטעינה מקשים מצד אחר: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"וחדלת\" ו\"עזב תעזב\" ב\u0004ענין \u0003פריקה הוא דכתיבי\u0004 \u0005[שנאמרו]!\u0006","על כך יש להסביר בדרך אחרת, ומשיבים \u0003אמר ליה: הא מני\u0004 \u0005[\u0006ברייתא \u0005זו כשיטת מי היא]\u0006 — כשיטת \u0003ר' יוסי הגלילי היא,\u0004 ש\u0003אמר: צער בעלי חיים לאו דאורייתא\u0004 \u0005[לא מן התורה]\u0006 הוא, ואולם רוב החכמים אינם סבורים כן.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו במקום אחר: אם הוא בא לפני אדם שהוא \u0003אוהב\u0004 שלו וצריך \u0003לפרוק\u0004 משא מחמורו, \u0003ושונא\u0004 שהוא צריך \u0003לטעון\u0004 עבורו משא — \u0003מצוה בשונא, כדי לכוף את יצרו\u0004 ולהתגבר על השנאה. \u0003ואי סלקא דעתך\u0004 \u0005[\u0006\u0005ואם עולה על דעתך]\u0006 לומר ש\u0003צער בעלי חיים דאורייתא\u0004 \u0005[מן התורה]\u0006 הוא, \u0003הא\u0004 \u0005[זה]\u0006 \u0003עדיף ליה\u0004 \u0005[לו]\u0006 שיפרוק, שהרי יש בכך גם צער בעלי חיים? ודוחים: \u0003אפילו הכי\u0004 \u0005[כך]\u0006 השיקול שיש בכך הוא \u0003כדי לכוף את יצרו עדיף\u0004 אפילו מצער בעלי חיים.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 \u0003שונא שאמרו\u0004 בתורה — הכוונה ל\u0003שונא ישראל ולא\u0004 ל\u0003שונא גוי,\u0004 ומעתה, \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי \u0003צער בעלי חיים דאורייתא\u0004 \u0005[מן התורה]\u0006 הוא, \u0003מה לי\u0004 אם כן \u0003שונא ישראל ומה לי שונא גוי?\u0004 הלא צריך לדאוג לבהמה!","ומשיבים: \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 שעל ה\u0003שונא דקרא קאי\u0004 \u0005[שבכתוב\u0006 הוא \u0005מוסב],\u0006 לגבי עצם החיוב לפרוק, לא כך, על \u0003שונא דמתניתין קאי\u0004 \u0005[של הברייתא\u0006 הוא \u0005מוסב]\u0006 שאמרו שמצוה להעדיף טעינה בשונא על פריקה באוהב, מדובר דווקא שהוא מישראל.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006"],["\u0003\"רבץ\"\u0004 — \u0003ולא רבצן\u0004 שרגיל לרבוץ תמיד, \u0003\"רבץ\"\u0004 — \u0003ולא עומד\u0004 עדיין. \u0003\"תחת משאו\"\u0004 — \u0003ולא\u0004 שמשאו \u0003מפורק\u0004 כבר. \u0003\"תחת משאו\"\u0004 כוונתו \u0003משאוי שיכול\u0004 החמור \u0003לעמוד בו,\u0004 שלא העמיס עליו יותר מן הראוי. \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כי \u0003צער בעלי חיים דאורייתא\u0004 \u0005[מן התורה]\u0006 הוא, \u0003מה לי\u0004 אם היה \u0003רובץ, ומה לי\u0004 אם הוא \u0003רבצן, ומה לי עומד,\u0004 הלא סובל הוא!","ומשיבים: \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו כשיטת מי היא]?\u0006 — כשיטת \u0003ר' יוסי הגלילי היא,\u0004 ש\u0003אמר צער בעלי חיים דרבנן\u0004 \u0005[מדברי סופרים]\u0006 הוא, ולדעתו אין מצוה בכגון אלה.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר על פי שיקולים אחרים, \u0003דקתני\u0004 \u0005[ששנה]\u0006 שם: \u0003\"תחת משאו\"\u0004 — \u0003משאוי שיכול לעמוד בו, מאן שמעת ליה דאית ליה האי סברא\u0004 \u0005[מי שמעת אותו שיש לו,\u0006 מחזיק, \u0005סברה זו]\u0006 — \u0003ר' יוסי הגלילי\u0004 הוא, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ושואלים: \u0003ומי מצית מוקמת לה\u0004 \u0005[האם יכול אתה להעמיד,\u0006 להסביר \u0005אותה]\u0006 \u0003כר' יוסי הגלילי? והא קתני סיפא\u0004 \u0005[והרי שנינו בסופה]:\u0006 \u0003\"תחת משאו\"\u0004 — \u0003ולא מפורק.\u0004 ונברר: \u0003מאי\u0004 \u0005[מה פירוש]\u0006 \u0003\"לא מפורק\"? אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003לא\u0004 חייב כשהיה \u0003מפורק כלל, הא כתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"הקם תקים עמו\"\u0004 (דברים כב, ד), שמצוה לטעון בהמה מפורקת! \u0003אלא פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 כי הכוונה היא: \u0003\"לא מפורק\"\u0004 — שאתה חייב לעשות זאת \u0003בחנם, אלא\u0004 יכול לעשות \u0003בשכר, מאן\u0004 \u0005[מי]\u0006 \u0003שמעת ליה\u0004 \u0005[אותו]\u0006 \u0003דאית ליה האי סברא\u0004 \u0005[שיש לו סברה זו]?\u0006 — \u0003רבנן\u0004 \u0005[חכמים]\u0006 במשנה! ודוחים: מכאן אין ראיה. \u0003לעולם\u0004 תאמר שהוא כשיטת \u0003ר' יוסי הגלילי,\u0004 \u0003ו\u0004אולם \u0003בטעינה סבר לה כרבנן\u0004 \u0005[סבור הוא כ\u0006שיטת \u0005חכמים]\u0006 ולא כר' שמעון.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 נאמר: \u0003\"כי תראה\u0004 חמור שונאך רובץ תחת משאו\u0003\"\u0004 (שמות כג, ה). \u0003יכול אפילו מרחוק,\u0004 שצריך להרחיק ללכת אם יודע שיש לעזור בכגון זה — \u0003תלמוד לומר: \"כי תפגע\"\u0004 (שם, ד) כלומר: תפגוש, משמע בקרבתך. \u0003אי\u0004 \u0005[אם]\u0006 נאמר \u0003\"כי תפגע\", יכול פגיעה ממש,\u0004 ואם אינו מגיע ממש למקום ההוא איננו חייב? \u0003תלמוד לומר: \"כי תראה\". ואיזו היא ראייה שיש בה פגיעה\u0004 שמשלבת את שני הצדדים שככתובים? — \u0003שיערו חכמים\u0004 מרחק זה, כ\u0003אחד משבע ומחצה במיל, וזה הוא\u0004 השיעור של \u0003ריס.\u0004","\u0003תנא\u0004 \u0005[שנה]\u0006 החכם: לאחר שטען, עוד \u0003מדדה עמו.\u0004 כלומר, מסייע לחמור מעט והולך עם בעליו \u0003עד פרסה\u0004 שמא יתמוטט שנית. \u0003אמר רבה בר בר חנה: ו\u0004אולם על תוספת זו של ליווי ועזרה הריהו \u0003נוטל שכר,\u0004 שאיננו מעיקר המצוה שבתורה אלא כתוספת עזרה.","\u0003אבדתו ואבדת אביו\u0004 — \u0003אבדתו\u0004 שלו \u0003קודמת,\u0004 ולה צריך לדאוג תחילה. \u0003אבדתו ואבדת רבו\u0004 — \u0003שלו קודם.\u0004","\u0003אבדת אביו ואבדת רבו\u0004 — \u0003של רבו קודמת,\u0004 שבכללו של דבר רבו קודם לאביו, \u0003ש\u0004כן \u0003אביו הביאו לעולם הזה, ורבו שלמדו חכמה מביאו לחיי העולם הבא. ו\u0004אולם \u0003אם אביו חכם,\u0004 וחייב לכבדו גם בשל תורתו, אבידתו \u0003של אביו קודמת.\u0004","וכן אם \u0003היה אביו ורבו נושאין משאוי, מניח\u0004 ומפרק \u0003את של רבו, ואחר כך מניח את של אביו. היה אביו ורבו בבית השבי\u0004 — \u0003פודה את רבו\u0004 תחילה, \u0003ואחר כך פודה את אביו. ו\u0004אף כאן, \u0003אם אביו\u0004 הוא עצמו \u0003חכם, פודה את אביו, ואחר כך פודה את רבו.\u0004","על האמור במשנתנו, שאבידתו קודמת לשל כל אדם, אפילו לשל אלה שחייב בכבודם, שואלים: \u0003מנא הני מילי\u0004 \u0005[מנין דברים אלה]?\u0006 \u0003אמר רב יהודה אמר רב: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"אפס כי לא יהיה בך אביון\"\u0004 (דברים טו, ד), כוונתו: שצריך אתה לדאוג, שאתה עצמך לא תהיה אביון, ולכן \u0003שלך קודם לשל כל אדם. ו\u0004על כך","\u0003אמר רב יהודה אמר רב: כל המקיים בעצמו כך, סוף בא לידי כך,\u0004 כלומר, אף שזו הלכה, אם אדם תמיד עומד על הלכה זו, ומקדים תמיד את שלו, בסופו של דבר יבוא לידי עניות, ואנשים אחרים יקיימו בו שיקול זה.","שנינו במשנה: אם \u0003היה אביו ורבו נושאין משאוי\u0004 — של רבו קודם. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003רבו שאמרו,\u0004 כוונתו, \u0003רבו שלמדו חכמה,\u0004 היא חכמת הגמרא, העיון והתעמקות בדברי תורה, \u0003ולא רבו שלמדו\u0004 רק \u0003מקרא ומשנה,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר:\u0004 רבו שאמרו, כוונתו, \u0003כל שרוב חכמתו הימנו\u0004 (ממנו). \u0003ר' יוסי אומר: אפילו לא האיר\u0004 אדם את \u0003עיניו\u0004 ולא הסביר לו \u0003אלא במשנה אחת, זה הוא רבו.\u0004","\u0003אמר רבא: כגון רב סחורה דאסברן\u0004 \u0005[שהסביר לי]\u0006 מה פירוש המלה במשנה \u0003זוהמא ליסטרון,\u0004 שהוא מין כף ומזלג הצמודים יחד, חייב אני לראותו בשל כך כרבי. ומסופר כי \u0003שמואל קרע מאניה עליה ההוא מרבנן\u0004 \u0005[את בגדיו,\u0006 כאבל \u0005על אחד החכמים\u0006 שמת] \u0003דאסבריה\u0004 \u0005[שהסביר לו]\u0006 את האמור במשנה: \u0003\"אחד יורד לאמת השחי ואחד פותח כיון\".\u0004 שאף שהסביר לו רק משנה אחת, ראה אותו לענין זה כרבו.","\u0003אמר עולא: תלמידי חכמים שבבבל, עומדין זה מפני זה\u0004 מפני הכבוד, \u0003וקורעין זה על זה\u0004 באבל על מותם. כיוון שבבבל אין כרגיל רב מובהק, כדרך שיש ראש ישיבה בארץ ישראל, והחכמים למדים זה מזה, וכל אחד יכול לראות את חבריו כרבותיו, \u0003ו\u0004אולם \u0003לענין אבדה\u0004 להקדימו \u0003במקום אביו, אינן חוזרים אלא לרבו מובהק\u0004 ולא לחבירו או לאדם שלימד אותו דבר מה.","מסופר: \u0003קבעי מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רב חסדא מרב הונא: תלמיד ו\u0004בכל זאת \u0003צריך לו רבו, מאי\u0004 \u0005[מה דינו]?\u0006 וכיון שרב חסדא היה תלמיד חבר לרב הונא, חשב רב הונא שהוא מתכוון לעצמו, \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא: \u0003חסדא חסדא, לא צריכנא לך\u0004 \u0005[אין אני צריך אותך],\u0006 \u0003את צריכת לי עד ארבעין שנין\u0004 \u0005[אתה תצטרך אותי עד ארבעים שנה]:\u0006 \u0003איקפדי אהדדי\u0004 \u0005[הקפידו זה על זה]\u0006 \u0003ולא עיילי לגבי הדדי\u0004 \u0005[באו עוד זה אצל זה]\u0006 משום ההקפדה ההדדית. ומספרים: \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב חיסדא ארבעין תעניתא\u0004 \u0005[ארבעים תעניות]\u0006 לשם תשובה, \u0003משום דחלש דעתיה\u0004 \u0005[שחלשה דעתו]\u0006 של \u0003רב הונא,\u0004 שאף שלא נתכוון לכך, מכל מקום נעלב רב הונא. וגם \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב הונא ארבעין תעניתא\u0004 \u0005[ארבעים תעניות],\u0006 \u0003משום דחשדיה\u0004 \u0005[שחשד לחינם]\u0006 את \u0003רב חסדא,\u0004 שלא התכוון כלל לרמוז ליחסים ביניהם.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בבעיה זו להלכה; \u0003רב יצחק בר יוסף אמר\u0004 בשם \u0003ר' יוחנן: הלכה כ\u0004שיטת \u0003ר' יהודה\u0004 שרבו הוא זה שרוב חכמתו ממנו, ואילו \u0003רב אחא בר רב הונא אמר\u0004 בשם \u0003רב ששת: הלכה\u0004 \u0003כ\u0004שיטת \u0003ר' יוסי\u0004 שאפילו לא האיר את עיניו רק במשנה אחת הוא נקרא רבו לענין זה.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן\u0004 כלל גדול בפסיקה: \u0003הלכה כסתם משנה, ותנן\u0004 \u0005[ושנינו\u0006 במשנתנו\u0005]:\u0006 \u0003רבו שלמדו חכמה.\u0004 ואם כן, נראים הדברים כדברי ר' מאיר! ומסבירים: \u0003מאי\u0004 \u0005[מה פירוש]\u0006 \u0003\"חכמה\"\u0004 במשנתנו? — הכוונה: \u0003רוב חכמתו\u0004 ולא סוג מסויים של לימוד.","אגב הדיון בשאלה מיהו רבו, מביאים דברים בענין חלקים שונים שבתורה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003העוסקים במקרא\u0004 — הרי זו \u0003מדה\u0004 טובה, אבל \u0003אינה מדה\u0004 שלימה, שצדדים אחרים של לימוד התורה חשובים ממנה. העוסקים \u0003במשנה\u0004 — הרי זו \u0003מדה, ונוטלין עליה שכר.\u0004 העוסקים \u0003בתלמוד\u0004 — \u0003אין לך מדה גדולה מזו, ולעולם הוי רץ ל\u0004למוד \u0003משנה יותר מן התלמוד.\u0004","על ברייתא זו תוהים: \u0003הא גופא קשיא\u0004 \u0005[היא עצמה קשה].\u0006 \u0003אמרת\u0004 קודם לכן \u0003ב\u0004ענין העיסוק ב\u0003תלמוד\u0004 ש\u0003אין לך מדה גדולה מזו, והדר\u0004 \u0005[וחזרת]\u0006 ו\u0003אמרת:\u0004 \u0003ולעולם הוי רץ למשנה יותר מן התלמוד,\u0004 והרי זו סתירה לגבי ערכם של הדברים! \u0003אמר ר' יוחנן:\u0004"],["\u0003בימי רבי נשנית משנה זו,\u0004 והוא בא לומר כמה חשובים העיון וההתעמקות בדברי ההלכה. כיון שאמר את הדברים \u0003שבקו כולא עלמא מתניתין ואזלו בתר תלמודא\u0004 \u0005[עזבו הכל את\u0006 שינון \u0005המשניות והלכו אחר התלמוד\u0006 והעיון\u0005],\u0006 על כן \u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003דרש להו\u0004 \u0005[להם]:\u0006 \u0003ולעולם הוי רץ למשנה יותר מן התלמוד,\u0004 שכן אם אין לאדם בסיס של ידיעות מוצקות, אינו יכול לדון בדברים.","ושואלים: \u0003מאי דרוש\u0004 \u0005[מה דרשו],\u0006 ועל מה סמכו כשאמרו שלימוד התלמוד חשוב ביותר? \u0003כדדריש\u0004 \u0005[כפי שדרש]\u0006 \u0003ר' יהודה ברבי אלעאי: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"\u0004ו\u0003הגד לעמי פשעם ולבית יעקב חטאתם\"\u0004 (ישעיהו נח, א), \u0003\"הגד לעמי פשעם\"\u0004 — \u0003אלו תלמידי חכמים, ש\u0004אפילו \u0003שגגות נעשות\u0004 (נחשבות) \u0003להם כזדונות,\u0004 שכל מה שעושה תלמיד חכם שלא כהוגן נחשב לו כפשע, לאמור כזדון. ומשום כך חייב תלמיד חכם לדקדק בדברים, שמא ישגוג ויחשב לו הדבר כפשע. \u0003\"ולבית יעקב חטאתם\"\u0004 — \u0003אלו עמי הארץ ש\u0004אף \u0003זדונות נעשות להם כשגגות\u0004 (\"חטאת\"), משום שאינם יודעים חומר העבירות שבידם. \u0003והיינו דתנן\u0004 \u0005[וזהו ששנינו\u0006 במשנה\u0005],\u0006 \u0003ר' יהודה אומר: הוי זהיר בתלמוד, ששגגת תלמוד עולה זדון,\u0004 כלומר, נחשבת כזדון, ומשום כך צריך לדקדק בו.","","ועוד \u0003דרש ר' יהודה בר' אלעאי\u0004 בענין סוגים שונים שבישראל: \u0003מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \"שמעו דבר ה' החרדים אל דברו אמרו אחיכם שנאיכם מנדיכם למען שמי יכבד ה' ונראה בשמחתכם והם יבושו\" (ישעיה סו, ה), \u0003\"שמעו דבר ה' החרדים אל דברו\"\u0004 — \u0003אלו תלמידי חכמים. \"אמרו אחיכם\"\u0004 — \u0003אלו בעלי מקרא,\u0004 שיודעים שאינם בקיאים בהלכה ומכבדים את תלמידי החכמים. \u0003\"שנאיכם\"\u0004 — \u0003אלו בעלי משנה,\u0004 שנראה להם שתלמידי חכמים מזלזלים בכבודם ושאף הם חכמים למדי. \u0003\"מנדיכם\",\u0004 כלומר, אלה שמרחקים ומתרחקים מכם — \u0003אלו עמי הארץ.\u0004","\u0003שמא תאמר פסק סברם\u0004 \u0005[תקוותם]\u0006 \u0003ובטל סיכוים\u0004 של אלה שאינם תלמידי חכמים? — \u0003תלמוד לומר: \"ונראה בשמחתכם\". שמא תאמר ישראל יבושו?\u0004 — \u0003תלמוד לומר: \"והם יבשו\",\u0004 כלומר, \u0003גוים יבושו, וישראל ישמחו.\u0004","","\u0003המפקיד אצל חבירו בהמה או כלים\u0004 והיה שומר הפקדון שומר חנם\u0003, ונגנבו או שאבדו\u0004 ממנו\u0003,\u0004 ואותו שומר \u0003שילם\u0004 למפקיד \u0003ולא רצה לישבע\u0004 שלא שלח ידו ולא התרשל\u0003, שהרי אמרו\u0004 חכמים \u0003: שומר חנם\u0004 אם רוצה — \u0003נשבע ויוצא\u0004 בלא לשלם, ושומר זה לא רצה.","\u0003נמצא\u0004 לבסוף \u0003הגנב\u0004 — \u0003משלם\u0004 הגנב \u0003תשלומי כפל.\u0004 ואם היתה זו בהמה, והגנב \u0003טבח ומכר\u0004 — \u0003משלם תשלומי ארבעה וחמשה.\u0004 ו\u0003למי משלם\u0004 כפל וארבעה וחמשה — \u0003למי שהפקדון אצלו,\u0004 לשומר, שאחר שפיצה השומר את הבעלים כאילו נעשה בעל החפץ. ומגיע לו כל תשלום וקנס שמתקבל עבורו.","ואולם אם השומר \u0003נשבע ולא רצה לשלם,\u0004 ואחר כך \u0003נמצא הגנב\u0004 — \u0003משלם\u0004 הגנב \u0003תשלומי כפל.\u0004 ואם \u0003טבח ומכר\u0004 — \u0003משלם תשלומי ארבעה וחמשה,\u0004 אולם \u0003למי משלם\u0004 — \u0003לבעל הפקדון\u0004 ולא לשומר \u0003.\u0004","שואלים: \u0003למה ליה למתני\u0004 \u0005[לו לשנות]\u0006 \u0003בהמה, ולמה ליה למתני\u0004 \u0005[לו לשנות]\u0006 \u0003כלים\u0004 ולהזכיר במפורש את שניהם? דיו שיאמר סתם המפקיד אצל חבירו!","ומסבירים: \u0003צריכי\u0004 \u0005[נצרכו]\u0006 שני הדברים להיאמר, \u0003דאי תנא\u0004 \u0005[שאילו היה שונה]\u0006 \u0003בהמה\u0004 בלבד \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כך: \u0003ב\u0004\u0003בהמה הוא דמקני ליה כפילא\u0004 \u0005[שמקנה לו\u0006 בעל הבהמה לשומר את \u0005הכפל]\u0006 כאשר השומר פיצה אותו, \u0003משום דנפיש טירחה לעיולה ולאפוקה\u0004 \u0005[שמרובה טרחתה להכניסה ולהוציאה]\u0006 ולדאוג לה, ולכן כשמתברר שהשומר לא שלח ידו בבהמה — מגיעים לו פיצויים, שבעל הבהמה מוותר עליהם. \u0003אבל כלים דלא נפיש טירחייהו\u0004 \u0005[שאין טירחתם מרובה]\u0006 בשמירה, \u0003אימא לא מקני ליה כפילא\u0004 \u0005[נאמר שאינו מקנה לו כפל]\u0006 \u0003.\u0004 ולהיפך, \u0003ואי תנא\u0004 \u0005[ואילו היה שונה]\u0006 רק ב\u0003כלים הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 ב\u0003כלים\u0004 ש\u0003הוא דקמקני ליה כפילא\u0004 \u0005[שמקנה לו\u0006 בעל הכלים לשומר את \u0005הכפל]\u0006 — \u0003משום דלא נפיש כפלייהו\u0004 \u0005[שאין כפלן מרובה],\u0006 שהרי יותר מכפל לא יקבל גם אם ימצא הגנב, \u0003אבל בהמה דכי\u0004 \u0005[שכאשר]\u0006 \u0003טבח ומכר\u0004 הגנב \u0003משלם תשלומי ארבעה וחמשה\u0004 ונמצא רווח גדול \u0003— אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא מקני ליה כפילא\u0004 \u0005[יקנה לו כפל],\u0006 על כן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 לומר בשני המקרים.","","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 על הסברה זו מעיקרה \u0003רמי בר חמא:\u0004 כיצד אפשר לומר שבעל החפצים מקנה לשומר את הזכות לקבל כפל? \u0003והא\u0004 \u0005[והרי]\u0006 כלל הוא ש\u0003אין אדם מקנה דבר שלא בא לעולם.\u0004 וכיון שכפל זה עדיין לא בא לעולם, אין דרך חוקית להקנות אותו לאחר. \u0003ואפילו\u0004 לשיטת \u0003ר' מאיר\u0004 ש\u0003אמר\u0004 בכלל ש\u0003אדם מקנה דבר שלא בא לעולם,\u0004 הרי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים בדבר \u0003כגון פירות דקל\u0004 שיכול להקנות לאחר את יבול השנה הבאה משום \u0003דעבידי דאתו\u0004 \u0005[ש\u0006הם \u0005עשויים לבוא],\u0006 כלומר, דרכם שהם צומחים ובאים תמיד,","\u0003אבל הכא\u0004 \u0005[כאן]\u0006"],["\u0003מי יימר דמגנבא\u0004 \u0005[מי יאמר שתיגנב],\u0006 \u0003ואם תמצי\u0004 \u0005[תמצא]\u0006 \u0003לומר דמגנבא\u0004 \u0005[שתיגנב]\u0006 — \u0003מי יימר דמשתכח\u0004 \u0005[מי יאמר שיימצא]\u0006 ה\u0003גנב,\u0004 \u0003ואי משתכח\u0004 \u0005[ואם ימצא]\u0006 ה\u0003גנב\u0004 — \u0003מי יימר דמשלם, דלמא מודי ומפטר\u0004 \u0005[\u0006\u0005מי יאמר שישלם, שמא יודה\u0006 בגניבה\u0005, ויפטר\u0006 מן הכפל\u0005]\u0006 ואם כן כיצד אפשר להקנות כפל? \u0003אמר רבא: נעשה\u0004 המפקיד \u0003כאומר לו\u0004 לשומר בשעת הפקדון: \u0003לכשתגנב\u0004 הבהמה, \u0003ותרצה ותשלמני\u0004 במקום להישבע, \u0003הרי פרתי קנויה לך\u0004 כבר \u0003מעכשיו.\u0004 וכיון שקנויה לו מעכשיו, ממילא זכה גם בכל הדברים הבאים מחמת הפרה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' זירא: אי הכי\u0004 \u0005[אם כך]\u0006 \u0003אפילו גיזותיה וולדותיה\u0004 של הבהמה שנתן לבעלים, כל זמן שהיתה אצלו \u0003נמי\u0004 \u0005[גם כן]\u0006 יצטרך השומר לקבל, שהרי התברר שנקנה לו החפץ מתחילתו. \u0003אלמה תניא\u0004 \u0005[ומדוע שנויה\u0006 ברייתא\u0005]\u0006 שמקבל \u0003חוץ מגיזותיה וולדותיה! אלא אמר ר' זירא,\u0004 יש לתקן את הדברים ולומר כך: \u0003נעשה כאומר לו\u0004 המפקיד לשומר: \u0003חוץ מגיזותיה וולדותיה.\u0004","ושואלים: \u0003ומאי פסקא\u0004 \u0005[ומה פסקת]\u0006 שמתנה תנאי כזה דווקא? ומסבירים: יש טעם בדבר; \u0003סתמא דמלתא\u0004 \u0005[סתמו של דבר]\u0006 \u0003שבחא דאתא מעלמא, עביד איניש דמקני\u0004 \u0005[שבח,\u0006 רווח, \u0005שיבוא מבחוץ, עשוי אדם להקנות]\u0006 מספק. \u0003שבחא דמגופה, לא עביד איניש דמקני\u0004 \u0005[שבח שמגופה, אין אדם עשוי להקנות],\u0006 שהוא בטוח בו שהוא בא תמיד.","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 לא כך \u0003אמר רבא\u0004 אלא בסגנון אחר: \u0003נעשה\u0004 המפקיד \u0003כאומר לו\u0004 לשומר: \u0003לכשתגנב ותרצה ותשלמני,\u0004 הרי הבהמה \u0003סמוך לגניבתה קנויה לך.\u0004 ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה ההבדל\u0006 המעשי \u0005ביניהם]\u0006 אם אמר בסגנון זה, או בסגנון זה?","ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 לגבי ה\u0003קושיא\u0004 של \u0003ר' זירא,\u0004 שלפי הנוסח האחרון, אין מקום לקושיא זו. \u0003אי נמי\u0004 \u0005[או גם כו]\u0006 כאן \u0003דקיימא\u0004 \u0005[שהיתה\u0006 הבהמה \u0005עומדת]\u0006 \u0003באגם\u0004 לפני גניבתה, וכיון שלא היתה בבית השומר סמוך לגניבה, לא נקנתה לו אז.","שנינו במשנה שאם \u0003שילם\u0004 השומר \u0003ולא רצה לישבע\u0004 הרי הכפל שלו. \u0003אמר רב חייא בר אבא אמר ר' יוחנן: לא\u0004 תפרש \u0003\"שילם\"\u0004 — \u0003שילם ממש, אלא כיון שאמר\u0004 השומר \u0003\"הריני משלם\", אף על פי שלא שילם,\u0004 כבר זכה בכפל ובכל השאר.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003שילם ולא רצה לישבע.\u0004 ונדייק: \u0003שילם\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003לא שילם\u0004 — \u0003לא. אימא סיפא\u0004 \u0005[אמור את סופה]\u0006 של המשנה: \u0003נשבע ולא רצה לשלם.\u0004 ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003לא רצה, הא\u0004 \u0005[הרי]\u0006 אם \u0003רצה\u0004 לשלם \u0003אף על פי שלא שילם.\u0004 ונמצאו הדיוקים מן המשנה סותרים זה את זה. \u0003אלא מהא ליכא למשמע מינה\u0004 \u0005[מכאן אי אפשר לשמוע ממנה]\u0006 דבר לענייננו.","ומעירים: \u0003תניא כותיה\u0004 \u0005[שנוייה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן:\u0004 \u0003השוכר פרה מחבירו, ונגנבה, ואמר הלה,\u0004 השוכר: \u0003\"הריני משלם ואיני נשבע\", ואחר כך נמצא הגנב\u0004 — \u0003משלם תשלומי כפל לשוכר.\u0004 משמע שעל ידי ההסכמה לשלם, כבר נקנה הכפל לשוכר.","\u0003אמר רב פפא\u0004 בהמשך לדברים: \u0003שומר חנם, כיון שאמר \"פשעתי\",\u0004 שמודה שהתרשל, וממילא התחייב לשלם, מאותה שעה \u0003מקנה ליה כפילא\u0004 \u0005[נקנה לו\u0006 את \u0005הכפל]\u0006 לכשימצא הגנב. ומדוע? \u0003דאי בעי פטר נפשיה\u0004 \u0005[שאילו היה רוצה,\u0006 הלא היה יכול \u0005לפטור את עצמו]\u0006 \u0003ב\u0004טענת \u0003גניבה,\u0004 וכיון שאמר \"פשעתי\", הרי זה כאומר \"הריני משלם\". וכן \u0003שומר שכר, כיון שאמר \"נגנבה\",\u0004 מפני שחייב עצמו בתשלום, \u0003מקנה ליה כפילא\u0004 \u0005[מקנה לו כפל]\u0006 אם ימצא הגנב, ומדוע? — \u0003דאי בעי פטר נפשיה\u0004 \u0005[שאילו היה רוצה\u0006 שלא לשלם, היה \u0005פוטר\u0006 את \u0005עצמו]\u0006 בטענה שהבהמה היתה \u0003שבורה\u0004 באונס או \u0003מתה.\u0004 ועל אלה אין שומר שכר משלם.","ואולם \u0003שואל שאומר \"הריני משלם\"\u0004 — \u0003לא מקני ליה כפילא\u0004 \u0005[אינו קונה\u0006 את זכות \u0005הכפל],\u0006 ומדוע? — \u0003במאי הוה ליה למפטר נפשיה\u0004 \u0005[במה היה לו לפטור\u0006 את \u0005עצמו],\u0006 איזו טענה יכול לטעון — שהיה יכול לומר ש\u0003מתה מחמת מלאכה,\u0004 ואולם \u0003מתה מחמת מלאכה לא שכיח\u0004 \u0005[אינו מצוי]\u0006 ולכן אין טענה זו מתקבלת בלא הוכחה, ולכן אומרים שבאומרו \"הריני משלם\" לא עשה דבר, שהרי בעל כורחו הוא משלם, ובאמירה זו בלבד לא נקנתה לו זכות.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 נוסח אחר בדברי \u0003רב פפא: שואל נמי\u0004 \u0005[גם כן]\u0006 \u0003כיון שאמר \"הריני משלם\"\u0004 — \u0003מקני ליה כפילא\u0004 \u0005[מקנה לו\u0006 את \u0005הכפל]\u0006 והטעם — \u0003דאי בעי\u0004 \u0005[שאם היה רוצה]\u0006 \u0003פטר נפשיה\u0004 \u0003ב\u0004טענת \u0003מתה מחמת מלאכה. אמר ליה רב זביד\u0004 לרב פפא: \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר אביי: שואל\u0004 אינו קונה את הזכות לכפל \u0003עד שישלם\u0004 ממש. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 ההבדל — \u0003הואיל\u0004 \u0003ו\u0004השואל \u0003כל הנאה שלו,\u0004 שהרי הוא משתמש בחפץ המושאל, ואיננו משלם דבר על כך, ו\u0003בדיבורא לא מקני ליה כפילא\u0004 \u0005[על ידי דיבור\u0006 בלבד, שאומר הריני מוכן לשלם, \u0005אין\u0006 הבעלים \u0005מקנים לו את הכפל].\u0006","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב זביד,\u0004 ששנינו: \u0003השואל פרה מחבירו ונגנבה, וקידם השואל ושילם\u0004 לפני שהיה דיון בדבר, \u0003ואחר כך נמצא הגנב\u0004 — הרי זה \u0003משלם תשלומי כפל לשואל.\u0004 משמע דווקא כששילם ממש.","ומעירים: \u0003ללישנא קמא\u0004 \u0005[ללשון ראשונה]\u0006 של \u0003רב פפא,\u0004 שאמר ששואל איננו יכול לפטור את עצמו בטענת \"מתה מחמת מלאכה\" — \u0003ודאי לא הויא תיובתא\u0004 \u0005[אין זו קושיה חמורה],\u0006 שהרי אפשר לפרש את הדברים יפה לשיטה זו. אולם \u0003ללישנא בתרא לימא תיהוי תיובתיה\u0004 \u0005[ללשון אחרונה\u0006 של רב פפא, האם \u0005נאמר שתהא זו קושיה חמורה\u0006 על שיטתו\u0005]?\u0006","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול \u0003היה\u0004 \u0005לומר]\u0006 \u0003לך רב פפא: מי אלימא ממתניתין\u0004 \u0005[האם\u0006 הברייתא \u0005תקיפה יותר ממשנתנו]?\u0006 \u0003דקתני\u0004 \u0005[ששנה]\u0006 במשנה \u0003\"שילם\", ואוקימנא\u0004 \u0005[והעמדנו,\u0006 והסברנו\u0005]\u0006 שמדובר \u0003באמר\u0004 שהוא משלם, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 הכוונה היא \u0003באמר\u0004 שישלם.","ותוהים: \u0003מי דמי\u0004 \u0005[האם דומה]\u0006 הדבר? \u0003התם\u0004 \u0005[שם]\u0006 במשנה \u0003לא קתני\u0004 \u0005[שנה]\u0006 \u0003\"קידם\"\u0004 ושילם, \u0003הכא קתני\u0004 \u0005[כאן שנה]\u0006 \u0003\"קידם\",\u0004 משמע שעשה מעשה ושילם! ודוחים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"קידם\"\u0004 — \u0003קידם ואמר,\u0004 ולא ששילם ממש.","ושואלים: \u0003הא מדקתני\u0004 \u0005[הרי ממה ששנינו]\u0006 בברייתא כעין זו גבי \u0003שוכר,\u0004 ושם הנוסחה \u0003\"ואמר\",\u0004 ואילו \u0003גבי שואל\u0004 הנוסח \u0003\"קידם\u0004 ושילם \u0003\"\u0004— \u0003שמע מינה דוקא קתני\u0004 \u0005[למד מכאן\u0006 שבאופן \u0005מדוייק שנה],\u0006 ו\"קידם\" משמעו שילם ממש! ודוחים: בדרך זו אין להוכיח, שכן וכי \u0003מידי גבי הדדי תניא\u0004 \u0005[זו ליד זו\u0006 הן \u0005שנויות]?\u0006 כלומר, מי אמר לנו ששתי הברייתות הללו צמודות זו לזו, שאפשר ללמוד מלשונה של זו על זו, שמא אין ביניהן קשר, וההבדל הוא סגנוני בלבד!","ומעירים: \u0003שיילינהו לתנאי\u0004 \u0005[שאלו את חוזרי המשניות]\u0006 \u0003דבי\u0004 \u0005[של בית\u0006 המדרש\u0005]\u0006 של \u0003ר' חייא ור' אושעיא, ואמרי\u0004 \u0005[ואמרו]:\u0006 \u0003גבי הדדי תניין\u0004 \u0005[זו ליד זו הן שנויות],\u0006 כלומר, הן חלק מברייתא ארוכה אחת, ולכן אפשר באמת ללמוד מזו על זו.","לפני שניגשים לברר בעיות מסויימות, מסבירים קודם את הידוע לנו. \u0003פשיטא\u0004 \u0005[פשוט]\u0006 ידוע, ברור לנו, שאם \u0003אמר\u0004 השומר תחילה \u0003\"איני משלם\", וחזר ואמר \"הריני משלם\u0004 ואיני נשבע \u0003\",\u0004 — \u0003הא קאמר\u0004 \u0005[הרי\u0006 כבר \u0005אמר]\u0006 \u0003\"הריני משלם\",\u0004 ויש לו זכות לכפל. \u0003אלא\u0004 השאלה היא, אם \u0003אמר\u0004 קודם \u0003\"הריני משלם\".\u0004"],["\u0003וחזר ואמר \"איני משלם\", מאי\u0004 \u0005[מה\u0006 דינו\u0005]?\u0006 \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 כי \u0003מהדר קא הדר ביה\u0004 \u0005[חזר בו]\u0006 מכוונתו לשלם, וממילא אין לו זכות בכפל, \u0003או דלמא במלתיה קאי ודחויי הוא דקא מדחי ליה\u0004 \u0005[שמא בדבריו\u0006 הראשונים \u0005הוא עומד\u0006 ובינתיים \u0005הוא שדוחה אותו\u0006 מלשלם מיד\u0005]\u0006 וכבר נקנה לו הכפל?","ועוד שאלה: \u0003אמר\u0004 השומר \u0003\"הריני משלם\", ומת\u0004 לפני שהספיק לשלם, ובאו \u0003ואמרו בניו \"אין אנו משלמים\" מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 \u0003מי אמרינן מהדר קא הדרי בהו\u0004 \u0005[האם אומרים אנו שחזרו בהם]\u0006 מהבטחת אביהם, \u0003או דלמא במלתא דאבוהון קיימי, ודחויי הוא דקא מדחו ליה\u0004 \u0005[שמא בדברי אביהם הם עומדים\u0006 עדיין, והם רק \u0005דוחים אותו]\u0006 עד שיוכלו לשלם?","וכן אם מת האב לפני שהספיק לומר דבר ו\u0003שלמו\u0004 ה\u0003בנים מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 האם \u0003מצי אמר להו\u0004 \u0005[יכול לומר להם]\u0006 בעל החפץ: \u0003כי אקנאי כפילא\u0004 \u0005[כאשר הקניתי את הכפל]\u0006 — הקניתיו \u0003לאבוכון דעבד\u0004 \u0005[לאביכם שעשה]\u0006 \u0003לי נייח נפשאי\u0004 \u0005[נחת רוח],\u0006 ואולם \u0003לדידכו\u0004 \u0005[לכם]\u0006 \u0003לא\u0004 הקניתי, \u0003או דלמא לא שנא\u0004 \u0005[שמא אינו שונה]\u0006 שכל המשלם קנה.","וכן אם \u0003שילם\u0004 אדם \u0003לבנים,\u0004 שבינתיים מת המפקיד והשומר שילם לבניו, \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 האם \u0003מצו אמרי ליה\u0004 \u0005[יכולים\u0006 הם \u0005לומר לו]:\u0006 \u0003כי אקני\u0004 \u0005[כאשר הקנה]\u0006 \u0003לך אבונא כפילא\u0004 \u0005[אבינו\u0006 את \u0005הכפל]\u0006 — הרי זה משום \u0003דעבדת ליה נייח נפשיה\u0004 \u0005[שעשית לו נחת רוח],\u0006 \u0003אבל אנן לדידן\u0004 \u0005[אנחנו לנו]\u0006 \u0003לא\u0004 עשית, \u0003או דלמא לא שנא\u0004 \u0005[שמא אינו שונה].\u0006 וכן, אם \u0003שלמו בנים\u0004 של השומר שנפטר \u0003לבנים\u0004 של המפקיד שאף הוא נפטר בינתיים, \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006","וכן אם \u0003שילם מחצה\u0004 מן הסכום ולא הספיק לשלם עד שנמצא הגנב, \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 למי שייך הכפל? וכן אם \u0003שאל שתי פרות\u0004 ונגנבו, \u0003ושילם\u0004 השומר רק עבור \u0003אחת מהן, מאי\u0004 \u0005[מה\u0006 יהא הדין\u0005]\u0006 כשיתפס הגנב? וכן, \u0003שאל מן השותפין\u0004 חפץ השייך להם \u0003ושילם לאחד מהן, מאי\u0004 \u0005[מה]\u0006 הדין? או להיפך, \u0003שותפין ששאלו ושילם אחד מהן, מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 \u0003שאל מן האשה ושילם לבעלה מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 או \u0003אשה ששאלה ושילם בעלה מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 לכל השאלות הרבות הללו לא נמצאה תשובה, ועל כל \u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה, שאין לנו פתרונות לשאלות אלה.","\u0003אמר רב הונא:\u0004 אף על פי שאומר אדם הריני משלם, מכל מקום \u0003משביעין אותו שבועה\u0004 נוספת \u0003שאינה ברשותו\u0004 אלא נגנבה או אבדה. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 שבועה יתירה זו — \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא עיניו נתן בה.\u0004 כלומר, שמא חשקה נפשו של השומר באותו חפץ דווקא, וחומס אותו מבעליו בדרך זו, ולכן משביעים אותו שאינה ברשותו.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003המלוה את חבירו על המשכון, ואבד המשכון, ואמר לו\u0004 המלוה: \u0003סלע\u0004 (שהוא שני שקלים) \u0003הלויתיך עליו,\u0004 עבור המשכון הזה, והמשכון עצמו רק \u0003שקל היה שוה,\u0004 ואתה חייב לי איפוא עוד שקל אחד. \u0003והלה,\u0004 הלווה, \u0003אומר: לא כי,\u0004 \u0003אלא\u0004 \u0003סלע הלויתני עליו,\u0004 ו\u0003סלע היה שוה\u0004 — הרי הלוה \u0003פטור\u0004 מלשלם.","ואולם אם טען המלוה: \u0003סלע הלויתיך עליו\u0004 ו\u0003שקל\u0004 בלבד \u0003היה שוה, והלה,\u0004 הלווה, \u0003אומר: לא כי, אלא סלע הלויתני עליו\u0004 ו\u0003שלשה דינרים\u0004 (שהם שלשת רבעי הסלע) \u0003היה שוה\u0004 — הרי זה \u0003חייב\u0004 שבועה, שכן הוא מודה במקצת הטענה.","אמר הלווה: \u0003סלע הלויתני עליו, שניים היה שוה,\u0004 \u0003והלה,\u0004 המלוה, \u0003אומר: לא כי, אלא סלע הלויתיך עליו סלע היה שוה\u0004 — הרי זה \u0003פטור.\u0004","אמר הלוה: \u0003סלע הלויתני עליו שנים היה שוה, והלה,\u0004 המלוה, \u0003אומר: לא כי, אלא סלע הלויתיך עליו\u0004 ובאמת \u0003חמשה דינרים היה שוה\u0004 — הרי \u0003חייב\u0004 בשבועה כדין מודה במקצת.","ומעירים: \u0003מי נשבע\u0004 בכל המקרים הללו — \u0003מי שהפקדון אצלו.\u0004 ומדוע תיקנו כך — \u0003שמא\u0004 יקרה \u0003ש\u0004\u0003ישבע זה,\u0004 כלומר, הלווה, הטוען בדבר ערכו של הפקדון, \u0003ויוציא הלה,\u0004 המחזיק, \u0003את הפקדון\u0004 ויוכיח שהיתה זו שבועת שקר. וכיון שאין אנו רוצים להביא את הדברים לידי כך, ישבע זה שהפקדון היה אצלו לגבי ערך הפקדון, וממילא לא תבוא הוכחה אחרת בדבר.","ומבררים: \u0003אהייא\u0004 \u0005[על מה]\u0006 נאמרו דברים אלה בהסבר מי ישבע? \u0003אילימא אסיפא\u0004 \u0005[אם תאמר לגבי סופה]\u0006 של המשנה כאשר הלווה רוצה לקבל עבור פקדונו — אולם במקרה זה אין צורך בנימוק זה, \u0003ותיפוק ליה\u0004 \u0005[ותצא לו]\u0006 עם אחר שחיוב ה\u0003שבועה גבי\u0004 \u0005[אצל]\u0006 ה\u0003מלוה היא,\u0004 \u0003דהא קא מודי\u0004 \u0005[שהרי הוא מודה]\u0006 ב\u0003מקצת הטענה\u0004 ומדין תורה הוא נשבע! \u0003אלא אמר שמואל:\u0004 חייבים לפרש זאת \u0003ארישא\u0004 \u0005[על ראשה]\u0006 של המשנה.","ו\u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003ארישא\u0004 — \u0003אסיפא דרישא\u0004 \u0005[על סופה של ההתחלה]\u0006 שחייבוהו להשבע, שהמלוה אומר \u0003סלע הלויתיך עליו שקל היה שוה, והלה,\u0004 הלווה בעל המשכון, \u0003אומר: לא כי, אלא סלע הלויתני עליו שלשה דינרים היה שוה,\u0004 הרי זה \u0003חייב\u0004 בשבועה. שמעיקר הדין \u0003שבועה גבי לוה הוא,\u0004 שהלוה היה צריך להישבע, שהרי הוא הנתבע והודה במקצת הטענה, \u0003ואמור רבנן\u0004 \u0005[אמרו חכמים]:\u0006 \u0003לשתבע\u0004 \u0005[שישתבע]\u0006 \u0003מלוה\u0004 שטענתו צודקת, \u0003שמא ישבע זה ויוציא הלה את הפקדון.\u0004","עד כאן לבירור הברייתא לגופה, ומעתה לצד הנוגע לעניננו: \u0003ואם\u0004"],["\u0003איתא\u0004 \u0005[ואם יש]\u0006 בסיס \u0003ל\u0004דברי \u0003רב הונא\u0004 אם כן \u0003כיון דמשתבע\u0004 \u0005[שנשבע]\u0006 ה\u0003מלוה שאינה ברשותו,\u0004 שהרי רב הונא סבור שכן צריך מחזיק הפקדון להישבע, אם כן \u0003היכי מצי מפיק לה\u0004 \u0005[כיצד יכול להוציא אותה]\u0006 אחר כך? \u0003אמר רבא:\u0004 מדובר כאן \u0003שיש עדים שנשרפה,\u0004 ולכן איננו צריך להשבע שאינה ברשותו.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 חוזרת השאלה מדוע לא ישבע האיש שצריך להשבע, שאין חשש עוד להוצאת הפקדון שהרי \u0003מהיכא מייתי לה\u0004 \u0005[מהיכן יביא אותה]\u0006 אם נשרפה? \u0003אלא אמר רב יוסף:\u0004 מדובר כאן באופן \u0003שיש עדים שנגנבה.\u0004 ושואלים: אף כאן, \u0003סוף סוף מהיכא מייתי לה\u0004 \u0005[מהיכן יביא אותה]?\u0006 ומשיבים: \u0003דטרח ומייתי לה\u0004 \u0005[שהוא טורח ומביא אותה],\u0006 שמחפש דרכים לקבל את החפץ מיד הגנב, כדי שיוכל להוכיח שחבירו נשבע לשקר.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003כי משתבע\u0004 \u0005[כאשר ישבע]\u0006 ה\u0003מלוה נמי\u0004 \u0005[גם כן]\u0006 קיים חשש מעין זה, והוא: \u0003לטרח\u0004 \u0005[שיטרח]\u0006 ה\u0003לוה וליתי\u0004 \u0005[ויביא]\u0006 את החפץ ויוכיח שהמלוה שיקר! ומשיבים: אין זה מתקבל על הדעת, שכן \u0003בשלמא\u0004 \u0005[נניח]\u0006 ה\u0003מלוה\u0004 שממנו נגנב המשכון \u0003ידע מאן קא עייל ונפק בביתיה, ואזיל וטרח ומייתי לה\u0004 \u0005[יודע מי נכנס ויוצא בביתו\u0006 והוא חושד באדם מסויים \u0005והולך וטורח ומביא אותה].\u0006 \u0003אלא\u0004 ה\u0003לוה, מי ידע מאן עייל ונפיק בביתיה\u0004 \u0005[האם יודע הוא מי נכנס ויוצא בביתו]\u0006 של ה","\u0003מלוה,\u0004 ולכן אין לו דרך להגיע אל החפץ הגנוב. \u0003אביי אומר\u0004 תירוץ אחר, שבכל זאת צריך להישבע שאינה ברשותו מהטעם \u0003גזירה שמא יטעון ויאמר לו: אחר שבועה מצאתיה.\u0004 ואילו \u0003רב אשי אמר: זה נשבע וזה נשבע, זה נשבע שאינה ברשותו, וזה נשבע כמה היה שוה. והכי קאמר\u0004 \u0005[וכך אמר\u0006 במשנתנו\u0005]:\u0006 \u0003מי נשבע תחילה\u0004 — \u0003מלוה נשבע תחילה\u0004 שהחפץ אינו ברשותו, \u0003שמא ישבע זה ויוציא הלה את הפקדון.\u0004","\u0003רב הונא בר תחליפא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא אמר: רישא דסיפא תיובתא\u0004 \u0005[ראש החלק האחרון\u0006 בברייתא \u0005קושיה חמורה]\u0006 היא לשיטת \u0003רב הונא,\u0004 ששנינו: אמר בעל המשכון \u0003סלע הלויתני עליו שתים היה שוה. והלה,\u0004 המלוה, \u0003אומר: לא כי, אלא סלע הלויתיך עליו, סלע היה שוה.\u0004 ושנינו כי המלוה \u0003פטור. ואם איתא\u0004 \u0005[ואם יש\u0006 מקום\u0005]\u0006 \u0003ל\u0004דברי \u0003רב הונא\u0004 שצריך להישבע שהחפץ אינו ברשותו, אם כן \u0003מגו דמשתבע\u0004 \u0005[מתוך שנשבע]\u0006 ה\u0003מלוה\u0004 \u0003שאינה ברשותו\u0004 — \u0003לישתבע נמי\u0004 \u0005[שישבע גם כן]\u0006 על ידי \u0003גילגול שבועה כמה היה שוה!\u0004","\u0003אמר רב אשי: אמריתה לשמעתא קמיה\u0004 \u0005[אמרתי את השמועה,\u0006 הסברה, הזו \u0005לפני]\u0006 \u0003רב כהנא ואמר לי: תהא\u0004 \u0005[תוסבר]\u0006 משנתנו \u0003במאמינו,\u0004 שהלווה מאמין למלוה שבאמת אין החפץ עוד בידו. ושואלים: אם מאמין הוא בו, אם כן \u0003ונהמניה\u0004 \u0005[וישיאמין]\u0006 ה\u0003לוה למלוה נמי בהא\u0004 \u0005[גם כן בזה]\u0006 \u0003כמה הוה שוה?\u0004 ודוחים: לדעתו לא שהמלוה משקר ביודעין, אלא \u0003לא קים ליה בגויה\u0004 \u0005[איננו עומד בו,\u0006 אינו יודע את הערך\u0005].\u0006 ושואלים: ומדוע לא נאמר גם להיפך \u0003ונהמניה\u0004 \u0005[ושיאמין]\u0006 ה\u0003מלוה ללוה, דקים ליה בגויה\u0004 \u0005[ש\u0006הוא \u0005עומד,\u0006 יודע, \u0005בו,\u0006 את ערכו\u0005]\u0006 ומדוע אין אומרים גם דבר זה? ומשיבים: \u0003לא מהימן ליה\u0004 \u0005[אין המלוה מאמין לו\u0006 ללוה\u0005].\u0006","ותוהים: \u0003ומאי שנא\u0004 \u0005[ומה שונה]\u0006 שה\u0003לוה דמהימן ליה\u0004 \u0005[מאמין לו]\u0006 \u0003למלוה ומאי שנא\u0004 \u0005[ומה שונה]\u0006 \u0003המלוה שאינו מאמין ללוה?\u0004 ומשיבים: \u0003לוה מקיים ביה\u0004 \u0005[מקיים בו],\u0006 כלומר, סבור שהתקיים \u0003במלוה\u0004 הכתוב \u0003\"תמת ישרים תנחם\"\u0004 (משלי יא,ג) — תמימותם של אנשים מובילה אותם להצלחה וסבור שאם זכה משמים שיש בידו ממון שהוא מלוה לאנשים — מן הסתם אדם הגון הוא. ואילו ה\u0003מלוה מקיים ביה בלוה\u0004 סופו של הכתוב \u0003\"וסלף בגדים ישדם\"\u0004 (שם) — מירמתם של הבוגדים מביאה עליהם שוד ועוני.","מסופר: \u0003ההוא גברא דאפקיד כיפי גביה חבריה\u0004 \u0005[אדם אחד הפקיד תכשיטים אצל חבירו]\u0006 ולאחר זמן \u0003אמר ליה\u0004 \u0005[לו]\u0006 המפקיד: \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי כיפי\u0004 \u0005[\u0006את \u0005התכשיטים]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא ידענא היכא אותבינהו\u0004 \u0005[איני יודע,\u0006 שכחתי, \u0005היכן שמתי אותם].\u0006 \u0003אתא לקמיה\u0004 \u0005[בא\u0006 הדבר \u0005לפני]\u0006 \u0003רב נחמן,\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן לשומר: \u0003כל \"לא ידענא\u0004 \u0005[אינני יודע]\u0006 \u0003\" פשיעותא\u0004 \u0005[רשלנות]\u0006 \u0003היא, זיל שלים\u0004 \u0005[לך שלם].\u0006 \u0003לא שילם.\u0004 \u0003אזל\u0004 \u0005[הלך]\u0006 \u0003רב נחמן אגביה לאפדניה מיניה\u0004 \u0005[\u0006ו\u0005הגבה\u0006 הורה לקחת \u0005ממנו את ארמונו]\u0006 ולמכרו, ולשלם במחירו עבור התכשיטים. \u0003לסוף אישתכח כיפי ואיקור\u0004 \u0005[לבסוף נמצאו\u0006 באמת \u0005התכשיטים ו\u0006לא עוד אלא ש\u0005התייקרו].\u0006 \u0003אמר רב נחמן: הדרי כיפי למרייהו והדרא אפדנא למרה\u0004 \u0005[חוזרים התכשיטים לבעליהם\u0006 הראשון \u0005וחוזר הבית לבעליו]\u0006 ומחזיק הפקדון איננו מרויח מהתייקרות התכשיטים.","\u0003אמר רבא: הוה יתיבנא קמיה\u0004 \u0005[הייתי יושב\u0006 באותו זמן \u0005לפני]\u0006 \u0003רב נחמן\u0004 כתלמיד, \u0003ופרקין\u0004 \u0005[ופרקנו]\u0006 שלמדנו אז פרק \u0003\"המפקיד\" היה\u0004 שבו עוסקים אנו בנושא זה, \u0003ואמרי ליה\u0004 \u0005[ואמרתי לו]:\u0006 הלא שנינו ששומר אשר \u0003שילם ולא רצה לישבע\u0004 הוא זוכה בכפל לכאורה שכיון ששילם נקנה לו גוף החפץ. \u0003ולא אהדר\u0004 \u0005[השיב]\u0006 \u0003לי\u0004 רב נחמן על קושיא זו דבר.","והעיר רבא כאשר סיפר דבר זה: \u0003ושפיר עבד\u0004 \u0005[ויפה עשה]\u0006 ש\u0003לא אהדר\u0004 \u0005[השיב]\u0006 \u0003לי\u0004 משום שהקושיא לא היתה ראויה לתשובה. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 ההבדל — \u0003התם\u0004 \u0005[שם]\u0006 כאשר שילם מעצמו \u0003לא אטרחיה לבי דינא\u0004 \u0005[הטריח אותו לבית הדין],\u0006 ואילו \u0003הכא\u0004 \u0005[כאן],\u0006 \u0003אטרחיה לבי דינא\u0004 \u0005[הטריח אותו לבית הדין]\u0006 כיון ששילם בהכרח בלבד, אין לומר שהקנה לו את החפץ.","ושואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 ש\u0003סבר רב נחמן\u0004 בכלל \u0003ש\u0004\u0003שומא\u0004 \u0005[הערכה]\u0006 ששמים חפץ מסויים עבור תשלום חוב \u0003הדר\u0004 \u0005[\u0006\u0005חוזר],\u0006 שמבטלים את המכירה הפומבית כאשר החייב מוכן לשלם את החוב? ודוחים: אין מזה כל ראיה, שכן \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 \u0003דשומא\u0004 \u0005[שההערכה]\u0006 והמכירה \u0003בטעות הוה\u0004 \u0005[היתה],\u0006 \u0003דקא הוה כיפי מעיקרא\u0004 \u0005[שהרי היו התכשיטים מתחילה]\u0006 בידי שומר הפקדון, ורק נשכח ממנו מקומם.","לגופה של הבעיה בענין חזרה בשומה \u0003אמרי נהרדעי\u0004 \u0005[אמרו\u0006 חכמי \u0005נהרדעא]:\u0006 \u0003שומא\u0004 \u0005[הערכה]\u0006 \u0003הדר\u0004 \u0005[חוזרת\u0006 \u0003ומתבטלת\u0004 \u0003עד תריסר ירחי שתא\u0004 \u0005[שנים עשר ירחי שנה],\u0006 שאם החייב משלם את החוב, מחזירים לו את רכושו שנמכר. \u0003ואמר אמימר: אנא\u0004 \u0005[אני,\u0006 עצמי\u0005]\u0006 \u0003מנהרדעא אנא\u0004 \u0005[אני]\u0006 ובכל זאת \u0003סבירא לי\u0004 \u0005[סבור אני]\u0006 כי \u0003שומא\u0004 \u0003הדר\u0004 \u0005[הערכה חוזרת]\u0006 \u0003לעולם,\u0004 שכל זמן שמחזיר את החוב יכול לקבל את רכושו בחזרה. ומסכמים, \u0003והלכתא\u0004 \u0005[ו\u0006פסק \u0005הלכה\u0006 הוא\u0005]:\u0006 \u0003שומא הדר\u0004 \u0005[הערכה חוזרת]\u0006 ומתבטלת \u0003לעולם,\u0004 \u0003משום שנאמר\u0004 \u0003\"ועשית הישר והטוב\"\u0004 (דברים ו, יח), שוודאי רוצה בעל החפץ בחפץ שלו יותר מאדם אחר, וראוי לדאוג להחזירו לו, ואין לגרום לו צער על ידי עמידה על דקדוקי מקח וממכר. ועוד בבירור שאלות אחדות בנושא זה.","ומקדימים תחילה: \u0003פשיטא\u0004 \u0005[פשוט\u0006 לנו\u0005]\u0006 כי אם \u0003שמו ליה\u0004 \u0005[העריכו לו]\u0006 דבר עבור \u0003בעל\u0004 ה\u0003חוב\u0004 כדי שיוכל לגבות ממנו, \u0003ואזל איהו\u0004 \u0005[והלך הוא]\u0006 המלוה \u0003ושמה\u0004 \u0005[והעריכה],\u0006 נתן את השומא, הזכות הזו לחפץ \u0003לבעל חוב דידיה\u0004 \u0005[שלו],\u0006 שהוא עצמו היה חייב לאחר, \u0003אמרינן ליה\u0004 \u0005[אומרים אנו לו]\u0006 לשני: \u0003לא עדיף את מגברא דאתית מיניה\u0004 \u0005[אין אתה עדיף\u0006 בכוחך \u0005מן האיש\u0006 שמכוחו \u0005באת]\u0006 ולכן, אם הלווה הראשון רוצה להחזיר את הכסף יכול הוא לקבל את הקרקע ממי שמחזיק בה, ואין המחזיק יוכל לומר שלא ממנו קיבל. \u0003זבנה\u0004 \u0005[מכרה]\u0006 מקבל השומה את הקרקע, או \u0003אורתא\u0004 \u0005[הורישה],\u0006 או \u0003יהבה\u0004 \u0005[נתן אותה]\u0006 \u0003במתנה,\u0004 \u0003ודאי הני מעיקרא\u0004 \u0005[אלה\u0006 שקיבלו את הקרקע \u0005מתחילה]\u0006 \u0003אדעתא דארעא נחות ולאו אדעתא דזוזי נחות\u0004 \u0005[על דעת\u0006 לקבל את \u0005הקרקע\u0006 עצמה \u0005ירדו\u0006 לקרקע \u0005ולא על דעת הכספים],\u0006 ולכן אי אפשר לקחת מהם את הקרקע, ואי אפשר לפצותם שלא מרצונם בכסף.","\u0003שמו\u0004 \u0005[העריכו]\u0006 \u0003לה לאשה\u0004 רכוש מסויים \u0003ואינסיבא\u0004 \u0005[ו\u0006אחר כך \u0005התחתנה],\u0006 או להיפך, \u0003או שמו מינה\u0004 \u0005[העריכו ממנה]\u0006 מן ה\u0003אשה\u0004 רכוש מסויים \u0003ואינסיבא\u0004 \u0005[והתחתנה]\u0006 \u0003ומתה,\u0004 אומרים אנו \u0003בעל בנכסי אשתו\u0004 כאשר יורש אותה כ\u0003לוקח\u0004 (קונה) \u0003הוי\u0004 \u0005[הוא\u0006 נחשב\u0005]\u0006 — \u0003לא מיהדר ולא מהדרינן ליה\u0004 \u0005[איננו מחזיר\u0006 מה שקיבל על ידי שומה \u0005ואין אנו מחזירים לו],\u0006 שהוא נחשב כאדם זר לענין זה.","ש\u0003אמר ר' יוסי בר חנינא: באושא התקינו\u0004 תקנה זו: \u0003האשה שמכרה בנכסי מלוג בחיי בעלה,\u0004 שגוף הנכסים שייך לאשה ואולם פירותיהם (רווחים) בתקופת היותם נשואים שייכים לבעל, ולכן אין האשה יכולה למכור אותם בחיי בעלה. ואולם כאשר מכרה את הנכסים \u0003ומתה\u0004 ובעלה יורשה, \u0003הבעל מוציא מיד הלקוחות,\u0004 שהוא טוען שזכותו שלו על הקרקע מוקדמת מזכותם של אחרים, והוא מחזיר להם את הכסף ששילמו."],["\u0003אגביה איהו\u0004 \u0005[הגבה,\u0006 נתן \u0005הוא]\u0006 הלוה בעצמו את הקרקע \u0003ב\u0004עבור \u0003חובו\u0004 בלא שבית דין הכריח אותו, ואחר כך רוצה לשלם את חובו ולקבל את הקרקע, \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה,\u0004 בשאלה זו, \u0003רב אחא ורבינא. חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר:\u0004 \u0003הדרה\u0004 \u0005[חוזרת]\u0006 הקרקע אם ירצה לשלם כסף, \u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר:\u0004 \u0003לא הדרה\u0004 \u0005[אינה חוזרת].\u0006","ומסבירים: \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר לא הדרה\u0004 \u0005[\u0006ש\u0005אינה חוזרת]\u0006 \u0003סבר: האי זביני מעליא\u0004 \u0005[זו, מכירה מעולה,\u0006 גמורה\u0005]\u0006 \u0003היא, דהא מדעתא דנפשיה אגביה\u0004 \u0005[שהרי מדעת עצמו הגבה אותו]\u0006 ולא הכריחוהו, ולכן אינו יכול לחזור בו. \u0003ומאן\u0004 \u0005[מי]\u0006 ש\u0003אמר הדרה\u0004 \u0005[\u0006ש\u0005חוזרת]\u0006 \u0003סבר: לא זביני מעליא הוא\u0004 \u0005[אין זו מכירה מעולה,\u0006 גמורה\u0005],\u0006 \u0003והאי דאגביה מדעתיה\u0004 \u0005[וזה שהגבה מדעתו]\u0006 \u0003ולא אתא לדינא\u0004 \u0005[בא ל\u0006בית \u0005דין]\u0006 שיכריחו אותו — \u0003מחמת כיסופא\u0004 \u0005[בושה]\u0006 \u0003הוא דאגביה\u0004 \u0005[שהגבה אותו],\u0006 שלא רצה להתבזות בבית דין.","ועוד בענין קרקעות שמקבל אדם בשומה עבור חובו, שואלים: \u0003ומאימת אכיל פירי\u0004 \u0005[מאימתי אוכל\u0006 את \u0005פירות\u0006 קרקע זו\u0005]?\u0006 \u0003רבה אמר: מכי מטיא\u0004 \u0005[מכאשר הגיע]\u0006 שטר \u0003אדרכתא לידיה\u0004 \u0005[לידו],\u0006 שבשטר זה כתוב שיכול לקחת לתשלום חובו מנכסי הלווה בכל מקום שהם. \u0003אביי אמר:\u0004 אינו צריך להמתין עד שיבוא לידו, אלא \u0003עדיו בחתומיו זכין לו,\u0004 שמזמן שנחתם שטר זה בבית דין, מיד נעשה כל מה שתפס להיות כשלו לגמרי.","\u0003רבא אמר:\u0004 לא כך, אלא רק \u0003מכי שלימו ימי אכרזתא,\u0004 שגם אחרי שהגיעה האדרכתא לידו ותופס קרקע של הלווה צריך להמתין בקנין ממש עד שיגמרו ימי ההכרזה, שבזה מוכרים מכירה פומבית קרקע זו לתשלום החוב, ורק אז נעשית קרקע זו שלו ממש.","\u0003השוכר פרה מחבירו והשאילה\u0004 השוכר \u0003לאחר, ומתה\u0004 הפרה \u0003כדרכה\u0004 בידי השואל, כיון שהשוכר אינו חייב לשלם אם אירע לבהמה אונס או מוות \u0003ישבע השוכר\u0004 למשכיר \u0003שמתה\u0004 הפרה \u0003כדרכה,\u0004 ואילו \u0003השואל ישלם לשוכר\u0004 דמי פרה, שהרי שאל ממנו פרה, והשואל חייב גם באונסין ומיתה. \u0003אמר ר' יוסי: כיצד הלה,\u0004 השוכר, \u0003עושה סחורה בפרתו של חבירו\u0004 ומרויח ממנה? \u0003אלא תחזור פרה לבעלים,\u0004 שהשוכר לא ישבע כלל, והשואל יחזיר פרה אחרת ליד הבעלים הראשונים.","\u0003אמר לו רב אידי בר אבין לאביי: מכדי\u0004 \u0005[הרי],\u0006 \u0003שוכר במאי קני להאי פרה\u0004 \u0005[במה קונה את הפרה הזו]\u0006 שתיחשב כאילו היתה שלו, עד כדי שהשואל ממנו יתחייב להחזיר לו פרה אחרת תמורתה — \u0003בשבועה,\u0004 שנשבע למשכיר שהפרה מתה כדרכה.","ואולם כיון שהדבר תלוי בשבועה זו, \u0003ונימא ליה\u0004 \u0005[ושיאמר לו]\u0006 ה\u0003משכיר לשוכר: דל אנת ודל\u0004 \u0005[הוצא\u0006 את \u0005עצמך והוצא]\u0006 את \u0003שבועתך,\u0004 ואינני רוצה לעסוק אתך כלל בדין זה, \u0003ואנא משתעינא דינא בהדי\u0004 \u0005[אני אעסוק בדין עם]\u0006 ה\u0003שואל\u0004 ואקבל בחזרה את הפרה. \u0003אמר ליה\u0004 אביי: \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 כי ה\u0003שוכר\u0004 על ידי ה\u0003שבועה הוא דקא קני לה\u0004 \u0005[שקונה אותה]\u0006 להיות כשלו? לא כן, \u0003משעת מיתה\u0004 של הפרה \u0003הוא דקני\u0004 \u0005[שקנה\u0006 אותה\u0005],\u0006 שמשעה שמתה הפרה בידי השואל יש לו זכות לקבל פרה אחרת תמורתה. \u0003ושבועה\u0004 זו שנשבע השוכר למשכיר אינה מעיקר הדין, אלא \u0003כדי להפיס\u0004 (לפייס, להניח) \u0003דעתו של בעל הבית,\u0004 שלא יחשוד את השוכר ברשלנות והזנחה. וכיון שכך, אין לבעל הפרה הראשון בעצם כל מקום למשא ומתן עם השואל, ואינו יכול לקבל את הפרה תמורת ויתור על השבועה.","\u0003אמר ר' זירא:\u0004 לפי שיטת המשנה \u0003פעמים\u0004 אפשר שיקרה \u0003שהבעלים\u0004 הם \u0003משלמין כמה פרות לשוכר. היכי דמי\u0004 \u0005[כיצד היה דבר\u0006 כזה\u0005],\u0006 — כגון: \u0003אגרה מיניה\u0004 \u0005[שכר\u0006 השוכר \u0005ממנו]\u0006 את הפרה ל\u0003מאה יומי\u0004 \u0005[יום],\u0006 \u0003והדר שיילה מיניה תשעין יומי\u0004 \u0005[וחזר\u0006 בעל הפרה \u0005ושאל אותה,\u0006 את הפרה, \u0005ממנו\u0006 מן השוכר \u0005לתשעים יום],\u0006 \u0003הדר אגרה מיניה תמנן יומי\u0004 \u0005[חזר\u0006 השוכר \u0005ושכר אותה\u0006 שנית \u0005ממנו,\u0006 מבעליה, \u0005לשמונים יום]\u0006 \u0003והדר שיילה מיניה שבעין יומי\u0004 \u0005[וחזר\u0006 בעל הפרה \u0005ושאל\u0006 מן השוכר \u0005אותה לשבעים יום]\u0006 \u0003ומתה\u0004 הפרה \u0003בתוך ימי שאלתה, דאכל\u0004 \u0005[שעל כל]\u0006 \u0003שאלה ושאלה מיחייב חדא פרה\u0004 \u0005[\u0006הוא \u0005חייב פרה אחת],\u0006 שהרי מצד ההלכה כאילו שאל ממנו שתי פרות לחוד, ולכן צריך להחזיר לו שתי פרות.","\u0003אמר ליה רב אחא מדיפתי לרבינא\u0004 על שיטה זו: \u0003מכדי חדא פרה\u0004 \u0005[הלא פרה אחת]\u0006 \u0003היא,\u0004 ולא פרות אחדות, \u0003עיילה ואפקה\u0004 \u0005[הכניסה והוציאה]\u0006 בצורות משפטיות שונות, \u0003אפקה\u0004 \u0005[הוציאה]\u0006 \u0003משכירות ועיילה\u0004 \u0005[והכניסה]\u0006 \u0003ל\u0004מעמד של \u0003שאילה, אפקה\u0004 \u0005[הוציאה]\u0006 \u0003מ\u0004מעמד \u0003של\u0004 \u0003שאילה ועיילה\u0004 \u0005[והכניסה]\u0006 \u0003ל\u0004מעמד של \u0003שכירות,\u0004 וכיצד אם כן משלם לו שתי פרות עבור פרה אחת? \u0003אמר\u0004 לו: \u0003ומי איתא\u0004 \u0005[והאם קיימת]\u0006 ה\u0003פרה בעינא\u0004 \u0005[בעינה]\u0006 \u0003דנימא ליה הכי\u0004 \u0005[ש\u0006הוא יכול \u0005לומר לו כך]:\u0006 הרי לך פרתך? שכיון שאיננו יכול להחזיר לו אותה פרה עצמה, אלא חייב להחזיר לו עבור התחייבות שנתחייב לו, הרי מבחינת התחייבויות — שתי פרות יש כאן, ולא אחת.","\u0003מר בר רב אשי אמר\u0004 כעין דברי ר' זירא אבל באופן קיצוני פחות: \u0003אין לו עליהן אלא שתי פרות,\u0004 כלומר, השוכר הזה מקבל מן הבעלים שתי פרות, \u0003חדא\u0004 \u0005[אחת]\u0006 של ה\u0003שאלה וחדא\u0004 \u0005[ואחת]\u0006 של ה\u0003שכירות,\u0004 כי \u0003שום\u0004 \u0005[שם]\u0006 \u0003שאלה אחת היא.\u0004 ואין לומר שיש כאן שתי פרות שאולות ונפרדות, אלא פרה אחת שאולה, \u0003ושום\u0004 \u0005[ושם]\u0006 \u0003שכירות אחת היא.\u0004 ואז, את הפרה של ה\u0003שאלה קני\u0004 \u0005[קונה]\u0006 לעצמו \u0003לגמרי\u0004 וזו של שכירות — \u0003עבד בה ימי שכירותיה\u0004 \u0005[שכירותו]\u0006 כמה שנשאר לו להשלים את הימים ששכר אותה \u0003ומיהדר ליה למרה\u0004 \u0005[\u0006\u0005ומחזיר אותה לבעליה].\u0006","לגבי צד אחר במצבים שנוצרו במשנה זו, \u0003אמר ר' ירמיה:\u0004 אם מתברר שהשוכר והשואל נשבעו לשקר, וחייבים להביא קרבן חטאת על שבועת שקר, הרי \u0003פעמים ששניהם\u0004 חייבים \u0003בחטאת,\u0004"],["\u0003פעמים ששניהם באשם,\u0004 שאדם הנשבע לשקר כדי להרויח ממון מביא קרבן אשם גזילות, \u0003פעמים שהשוכר בחטאת והשואל באשם, פעמים שהשוכר באשם והשואל בחטאת.\u0004","והוא מפרט והולך: \u0003הא כיצד? —\u0004 בכלל, הנשבע שבועת שקר שיש בה \u0003כפירת ממון\u0004 שהוא חייב לשלם מביא קרבן \u0003אשם.\u0004 ואם היה זה \u0003ביטוי שפתים\u0004 שהוא שבועת שקר שאין בה כפירת ממון — הריהו חייב \u0003חטאת.\u0004","ומפרש: \u0003פעמים ששניהם\u0004 חייבים \u0003בחטאת —\u0004 \u0003כגון שמתה\u0004 הבהמה \u0003כדרכה, ואמרו\u0004 השוכר והשואל כי \u0003נאנסה\u0004 (מתה באונס). ומעתה, \u0003שוכר\u0004 ש\u0003בין כך ובין כך מיפטר פטור\u0004 \u0005[נפטר]\u0006 מלשלם, שהרי גם אם מתה כדרכה הוא פטור, נמצא שנשבע השוכר שבועת שקר (לריק) והריהו \u0003בחטאת,\u0004 וה\u0003שואל\u0004 ש\u0003בין כך ובין כך חיובי מיחייב\u0004 \u0005[חייב],\u0006 שגם אם מתה באונס חייב, גם הוא מביא \u0003חטאת,\u0004 שהרי גם הוא נשבע לשקר בלא להרויח דבר.","\u0003פעמים ששניהם באשם\u0004 — \u0003כגון שנגנבה\u0004 הפרה מהשואל, \u0003ואמרו\u0004 שניהם \u0003ש\u0004\u0003\"מתה מחמת מלאכה\", דתרוייהו קא כפרי ממונא\u0004 \u0005[ששניהם כופרים ממון],\u0006 \u0003דהא מיחייבי\u0004 \u0005[שהרי\u0006 היו \u0005חייבים]\u0006 לשלם, ששוכר משלם עבור גניבה, ושואל חייב לשלם גם אם מתה באונס כדרכה \u0003וקא פטרי נפשייהו\u0004 \u0005[והם\u0006 רוצים \u0005לפטור\u0006 את \u0005עצמם]\u0006 בשבועה — הרי זו שבועת כפירת ממון, וכפירתה בקרבן אשם.","\u0003שוכר בחטאת ושואל באשם\u0004 — \u0003כגון שמתה\u0004 הפרה \u0003כדרכה, ואמרו\u0004 שניהם ש\u0003מתה מחמת מלאכה, שוכר\u0004 ש\u0003בין כך ובין כך מיפטר פטור\u0004 \u0005[פטור],\u0006 שהרי פטור מלשלם עבור אונס — \u0003חייב בחטאת,\u0004 שהיתה זו שבועת שקר לריק, \u0003שואל דמיחייב\u0004 \u0005[שמחוייב]\u0006 כש\u0003מתה כדרכה, וקא פטר נפשיה\u0004 \u0005[והוא\u0006 רוצה \u0005לפטור\u0006 את \u0005עצמו]\u0006 כשהוא טוען ש\u0003מתה מחמת מלאכה\u0004 — חייב קרבן \u0003אשם.\u0004","\u0003שוכר\u0004 חייב \u0003באשם ושואל בחטאת —\u0004 \u0003כגון שנגנבה ואמרו מתה כדרכה. שוכר הוא דמיחייב\u0004 \u0005[שחייב]\u0006 \u0003בגניבה ואבידה, וקא פטר נפשיה\u0004 \u0005[\u0006ו\u0005הוא\u0006 רוצה \u0005לפטור\u0006 את \u0005עצמו]\u0006 \u0003במתה כדרכה\u0004 — על כן חייב \u0003באשם,\u0004 ואילו \u0003שואל\u0004 ש\u0003בין כך ובין כך חיובי מיחייב\u0004 \u0005[חייב]\u0006 לשלם הרי הוא מביא קרבן \u0003חטאת,\u0004 ושואלים: בעצם","\u0003מאי קא משמע לן\u0004 \u0005[מה\u0006 חידוש \u0005השמיע לנו]\u0006 ר' ירמיה בסדרה זו של הלכות, שלכאורה היא מובנת מעצמה, לפי הכללים הרגילים! ומסבירים: כי בא \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 מדברי \u0003ר' אמי,\u0004 ש\u0003אמר\u0004 ר' אמי: \u0003כל שבועה שהדיינים משביעים אותה\u0004 — \u0003אין חייבים עליה משום שבועת ביטוי,\u0004 כלומר, משום שבועת שקר, אלא אם כן נשבע על מנת להרויח בכך ממון, \u0003שנאמר: \"או נפש כי תשבע לבטא בשפתים\"\u0004 (ויקרא ה, ד) והוא מפרשו בלשון הדגשה \u0003\"כי תשבע\"\u0004 — \u0003מעצמה,\u0004 ולא כשאחרים משביעים אותו. על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ר' ירמיה שהוא סבור ש\u0003לא\u0004 כדברי \u0003ר' אמי,\u0004 שחייב קרבן בכל מקרה של שבועה שנשבע לשקר.","\u0003אתמר\u0004 \u0005[נאמר]\u0006 שחלקו אמוראים בבעיה הבאה: \u0003שומר שמסר לשומר\u0004 אחר, מה דינו? \u0003רב אמר: פטור, ור' יוחנן אמר: חייב.\u0004","\u0003אמר אביי: לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 של \u0003רב, לא מבעיא\u0004 \u0005[נצרכה]\u0006 לומר שאם היה זה בתחילה \u0003שומר חנם שמסר\u0004 את שמירת החפץ \u0003לשומר שכר, דעלויי עלייה\u0004 \u0005[ש\u0006רי \u0005עילה,\u0006 השביח\u0005]\u0006 את \u0003שמירתו,\u0004 שהרי שומר שכר חייב לשמור בשמירה מעולה יותר, \u0003אלא אפילו\u0004 היה זה \u0003שומר שכר שמסר\u0004 מטעמו \u0003לשומר חנם, דגרועי גרעה\u0004 \u0005[שגרע]\u0006 את \u0003שמירתו,\u0004 בכל זאת \u0003פטור. מאי טעמא\u0004 \u0005[מה טעם]\u0006 — \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003מסרה,\u0004 את הפקדון, \u0003לבן דעת,\u0004 ודבר שנמסר לבן דעת, הרי זו שמירה ראויה לו.","\u0003ולטעמיה\u0004 \u0005[ולטעמו,\u0006 לשיטתו\u0005]\u0006 של \u0003ר' יוחנן, לא מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר ב\u0003שומר שכר שמסר לשומר חנם דגרועי גרעה\u0004 \u0005[שגרע]\u0006 את \u0003שמירתו\u0004 שחייב, \u0003אלא אפילו שומר חנם שמסר לשומר שכר, דעלויי עלייה\u0004 \u0005[שעילה,\u0006 השביח\u0005]\u0006 את \u0003שמירתו\u0004 על ידי כך — \u0003חייב. דאמר ליה\u0004 \u0005[שאומר לו]\u0006 המפקיד לשומר: \u0003אין רצוני שיהא פקדוני ביד אחר,\u0004 ולך מסרתי ולא לאחר.","\u0003אמר רב חסדא: הא\u0004 \u0005[\u0006דבר \u0005זה]\u0006 שמוסרים \u0003בשם\u0004 \u0003רב לאו\u0004 \u0005[לא]\u0006 \u0003בפירוש אתמר\u0004 \u0005[נאמר]\u0006 על ידי רב \u0003אלא מכללא\u0004 \u0005[מכלל,\u0006 מתוך דבריו\u0005]\u0006 נלמד. וכך היה המעשה: \u0003דהנהו גינאי, דכל יומא הוו מפקדי מרייהו גבה דההיא סבתא\u0004 \u0005[אותם גננים שהיו מפקידים בכל יום את מעדריהם אצל זקנה אחת].\u0006 \u0003יומא חד אפקדינהו לגבי חד מינייהו\u0004 \u0005[יום אחד הפקידו אותם,\u0006 את המעדרים, \u0005אצל אחד מהם]\u0006 \u0003שמע\u0004 אותו אדם \u0003קלא בי הלולא נפק אזל\u0004 \u0005[קול בבית החתונה ויצא ללכת\u0006 לשם\u0005].\u0006 \u0003אפקדינהו לגבה דההיא סבתא\u0004 \u0005[\u0006ו\u0005הפקיד אותם,\u0006 את המעדרים, \u0005בידי אותה זקנה]\u0006 \u0003אדאזל ואתא אגנוב מרייהו\u0004 \u0005[עד שהלך ובא\u0006 מן החתונה \u0005נגנבו מעדריהם].\u0006","\u0003אתא לקמיה\u0004 \u0005[בא\u0006 הענין \u0005לפני]\u0006 \u0003רב ופטריה\u0004 \u0005[ופטרו]\u0006 רב את האיש הזה מלשלם, \u0003מאן דחזא\u0004 \u0005[מי שראה]\u0006 את הענין \u0003סבר\u0004 שהטעם היה משום שהוא סובר שהדין ב\u0003שומר שמסר לשומר\u0004 שהוא \u0003פטור. ולא היא,\u0004 לא זה היה הטעם, אלא \u0003שאני התם דכל יומא נמי אינהו גופייהו גבה דההיא סבתא הוו מפקדי להו\u0004 \u0005[שונה שם, שבכל יום גם כן הם עצמם אצל אותה זקנה היו מפקידים]\u0006 ובמקרה זה אינם יכולים לטעון שאין רצונם שיהיה פקדונם בידה, ולכן אין השומר חייב.","מסופר: \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003ר' אמי וקאמר לה להא שמעתא\u0004 \u0005[ואמר את ההלכה הזו\u0006 כולה\u0005].\u0006 \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' אבא בר ממל לר' אמי\u0004 ממה ששנינו במשנתנו: \u0003השוכר פרה מחבירו והשאילה לאחר ומתה\u0004 הפרה \u0003כדרכה\u0004 — \u0003ישבע השוכר שמתה כדרכה והשואל משלם לשוכר. ואם איתא\u0004 \u0005[ואם יש\u0006 מקום\u0005]\u0006 לדברי ר' יוחנן, \u0003לימא ליה\u0004 \u0005[שיאמר לו\u0006 המשכיר\u0005]:\u0006 \u0003אין רצוני שיהא פקדוני ביד אחר,\u0004 ואסור היה לך להשאיל! \u0003אמר\u0004 לו: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003בשנתנו לו הבעלים רשות להשאיל.\u0004","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 השואל \u0003לבעלים בעי לשלומי\u0004 \u0005[היה צריך לשלם],\u0006 שהרי מדעתם הושאל לו החפץ! השיב לו: מדובר כאן באופן ש\u0003אמרו ליה\u0004 \u0005[לו]\u0006 הבעלים לשוכר: \u0003לדעתך,\u0004 כלומר, אנו מתירים לך להשאיל את החפץ לפי שיקול דעתך ועליך אחריותו.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 באופן אחר \u0003רמי בר חמא\u0004 ממה ששנינו: \u0003המפקיד מעות אצל חבירו\u0004 ואותו חבר \u0003צררן והפשילן\u0004 \u0005[שם אותם]\u0006 בבגדו \u0003לאחוריו,\u0004 או \u0003מסרן לבנו ולבתו הקטנים\u0004 שישמרום, או \u0003נעל בפניהם שלא כראוי\u0004 — בכל אלה \u0003חייב,\u0004 לפי \u0003שלא שמר כדרך השומרים.\u0004","ונדייק מן המשנה: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 שמסר לבניו \u0003הקטנים, הא\u0004 \u0005[הרי]\u0006 אם היו אלה \u0003גדולים\u0004 — \u0003פטור. אמאי\u0004 \u0005[מדוע]?\u0006 \u0003נימא ליה\u0004 \u0005[שיאמר לו\u0006 המפקיד\u0005]\u0006 כדברי ר' יוחנן: \u0003אין רצוני שיהא פקדוני ביד אחר!\u0004","\u0003אמר רבא:\u0004 מכאן אין להקשות, כי ברור לנו ש\u0003כל המפקיד\u0004"],["\u0003על דעת אשתו ובניו\u0004 של השומר \u0003הוא מפקיד.\u0004 כלומר, מתוך הנחה שהשומר ימסור את החפצים לאשתו ובניו שישמרום, ולא הוא לבדו ישמור עליהם כל העת, ומלכתחילה מסכים הוא לכך והדבר על דעתו.","\u0003אמרי נהרדעי\u0004 \u0005[אמרו\u0006 חכמי \u0005נהרדעא]:\u0006 \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 שכך הוא מלשון המשנה \u0003דקתני\u0004 \u0005[ששנה בה]:\u0006 \u0003או שמסרן לבנו ולבתו הקטנים\u0004 — \u0003חייב.\u0004 ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם מסר \u0003לבנו ולבתו הגדולים\u0004 — \u0003פטור.\u0004 ואולם \u0003מכלל\u0004 הדברים, מן העובדה שתמיד מדובר כאן בבניו, אפשר לדייק שאם מסר \u0003לאחרים,\u0004 אז \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 אם היו \u0003גדולים ולא שנא\u0004 \u0005[אינה שונה]\u0006 אם היו אלה \u0003קטנים\u0004 — \u0003חייב\u0004 בכל מקרה, \u0003דאם כן,\u0004 כלומר, אם לא לכך נתכוין \u0003ליתני\u0004 \u0005[שישנה]\u0006 \u0003קטנים סתמא\u0004 \u0005[סתם]\u0006 בלשון \"או שמסר לקטנים\" וכיון שהדגיש בניו הקטנים, משמע שלבניו מותר לו למסור, אלא מכיון שקטנים היו אין שמירתם שמירה. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003אמר רבא, הלכתא\u0004 \u0005[הלכה]\u0006 בענין זה היא: \u0003שומר שמסר לשומר\u0004 — \u0003חייב, לא מבעיא\u0004 \u0005[נצרכה]\u0006 לומר שכן הדין ב\u0003שומר שכר שמסר לשומר חנם דגרועי גרעה\u0004 \u0005[שגרע]\u0006 את \u0003שמירתו, אלא אפילו שומר חנם שמסר לשומר שכר\u0004 — \u0003חייב,\u0004 ו\u0003מאי טעמא\u0004 \u0005[מה הטעם],\u0006 לא בדיוק כפי שאמרנו, אלא \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 המפקיד לשומר: \u0003את מהימנת\u0004 \u0005[אתה נאמן]\u0006 \u0003לי בשבועה,\u0004 שלך אני מוכן להאמין אם תשבע ותאמר שהחפץ נגנב או אבד, אבל \u0003האיך לא מהימן\u0004 \u0005[אותו\u0006 אדם \u0005אינו נאמן]\u0006 \u0003לי\u0004 אף \u0003בשבועה\u0004 ולכן אינני רוצה שיהא חפץ שלי בידיו, שאצטרך לסמוך על שבועתו.","\u0003אתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בשאלה הבאה: אם \u0003פשע בה\u0004 (התרשל בשמירת הבהמה) \u0003ויצאת\u0004 (יצאה) הבהמה \u0003לאגם,\u0004 למקום מרעה ליד הנהר שיש בו סכנת גנבים וחיות רעות, \u0003ו\u0004אולם למרות רשלנותו לא נגנבה ולא נטרפה שם אלא \u0003מתה כדרכה. אביי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבה אמר: חייב\u0004 השומר, ו\u0003רבא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבה אמר: פטור.\u0004","ומסבירים ומפרטים: \u0003אביי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבה אמר: חייב,\u0004 והוסיף \u0003כל דיינא דלא דאין כי האי דינא לאו דיינא הוא\u0004 \u0005[כל דיין שאינו דן כדין זה\u0006 שאני אומר \u0005אינו דיין],\u0006 שהדבר פשוט; \u0003לא מבעיא\u0004 \u0005[נצרכה]\u0006 לומר \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 בכלל שכל שהיתה \u0003תחילתו בפשיעה\u0004 אף על פי ש\u0003סופו באונס\u0004 — \u0003חייב,\u0004 שלפי שיטה זו ברור שכאן \u0003חייב. אלא אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאמר]\u0006 שם \u0003פטור, הכא\u0004 \u0005[כאן]\u0006 \u0003חייב\u0004 הוא. \u0003מאי טעמא\u0004 \u0005[מה הטעם],\u0006 — \u0003דאמרינן\u0004 \u0005[שאנו אומרים]:\u0006 \u0003הבלא דאגמא קטלה\u0004 \u0005[ההבל של האגם\u0006 הוא \u0005שהרגה,\u0006 את הפרה\u0005]\u0006 ונמצא שרשלנותו היא שגרמה שמתה הפרה, ולא היה זה אונס גמור.","ואילו \u0003רבא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבה אמר: פטור,\u0004 ואף הוא סבור: \u0003כל דיינא דלא דאין כי האי דינא לאו דיינא הוא\u0004 \u0005[כל דיין שאינו דן כדין זה אינו דיין],\u0006 \u0003לא מיבעיא למאן דאמר\u0004 \u0005[נצרכה ל\u0006דעת \u0005מי שאומר]\u0006 \u0003תחילתו בפשיעה וסופו באונס\u0004 — \u0003פטור,\u0004 שאף כאן מקרה כזה ו\u0003פטור, אלא אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 בכלל \u0003חייב, הכא\u0004 \u0005[כאן]\u0006 \u0003פטור. מאי טעמא\u0004 \u0005[ומה טעם]\u0006 הדבר \u0005—\u0006 \u0003דאמרינן\u0004 לגבי \u0003מלאך המות\u0004 שפגע בה שהרי מתה כדרכה: \u0003מה לי\u0004 אם היתה \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003ומה לי\u0004 אם היתה \u0003התם\u0004 \u0005[שם],\u0006 שוודאי מתה מעצמה, ולא בגלל המקום שהיתה בו, על כן בוודאי פטור.","ומעירים: \u0003ומודי\u0004 \u0005[ומודה]\u0006 \u0003אביי, דאי הדרא לבי מרה\u0004 \u0005[שאם חזרה\u0006 הפרה \u0005לבית בעליה]\u0006 \u0003ומתה\u0004 אחר שהיתה באגם — \u0003פטור. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003דהא הדרא\u0004 \u0005[שהרי חזרה]\u0006 \u0003לה\u0004 \u0003וליכא למימר הבלא דאגמא קטלה\u0004 \u0005[ואין לומר\u0006 ש\u0005הבל האגם הרג אותה],\u0006 שהרי רואים שיכלה לחזור. ומצד שני \u0003מודי\u0004 \u0005[מודה]\u0006 \u0003רבא כל היכא דאיגנבה גנב\u0004 \u0005[שנגנבה]\u0006 \u0003באגם\u0004 \u0005[כל היכן\u0006 שאם \u0005נגנבה הפרה באגם]\u0006 \u0003ו\u0004אחר כך \u0003מתה כדרכה בי\u0004 \u0005[בבית]\u0006 ה\u0003גנב\u0004 — שהשומר \u0003דחייב\u0004 \u0005מתה כדרכה בבית הגנב\u0006 שהשומר \u0005חייב].\u0006 ו\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר\u0005]\u0006 \u0005—\u0006 \u0003דאי שבקה\u0004 \u0005[שאילו היה מניח אותה]\u0006 \u0003מלאך המות\u0004 ולא היתה מתה \u0003—\u0004 \u0003בביתיה דגנבא הוה קיימא\u0004 \u0005[בביתו של הננב היתה נמצאת]\u0006 ונמצא שבגלל רשלנותו נגנבה הפרה ממנו.","\u0003אמר ליה אביי לרבא: לדידך דאמרת\u0004 \u0005[לשיטתך שאתה אומר]\u0006 לגבי \u0003מלאך המות מה לי הכא\u0004 \u0005[כאן]\u0006 \u0003ומה לי התם\u0004 \u0005[שם],\u0006 \u0003האי דאותביה\u0004 \u0005[אותה\u0006 קושיה \u0005שהקשה לו]\u0006 \u0003ר' אבא בר ממל לר' אמי\u0004 בענין שומר שמסר לשומר \u0003ושני ליה\u0004 \u0005[ותירץ לו]\u0006 \u0003בשנתנו לו בעלים רשות להשאיל, ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 טעם זה שאתה אומר: \u0003מלאך המות מה לי הכא\u0004 \u0005[כאן]\u0006 \u0003ומה לי התם\u0004 \u0005[שם],\u0006 שאם אומר אני שהמוות היה קורה בכל מקום, אין כל חשיבות אצל מי היתה מצויה?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לדידכו דמתניתו\u0004 \u0005[לשיטתכם שאתם שונים]\u0006 ומסבירים טעם ששומר שמסר לשומר חייב מפני \u0003\"אין רצוני שיהא פקדוני ביד אחר\"\u0004 אכן, \u0003איכא לאותבה לההיא\u0004 \u0005[יש מקום להקשות\u0006 את הקושיה \u0005ההיא]\u0006 שהקשית, אולם \u0003לדידי דאמינא\u0004 \u0005[לשיטתי שאני אומר]\u0006 שאין שומר רשאי למסור לשומר מן הטעם של \u0003אנת מהימנת\u0004 \u0005[אתה נאמן]\u0006 \u0003לי בשבועה והאיך לא מהימן\u0004 \u0005[והחוטא אינו נאמן]\u0006 \u0003לי בשבועה ליכא לאותבה\u0004 \u0005[אין\u0006 מקום \u0005להקשותה]\u0006 \u0003כלל.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רמי בר חמא\u0004 על אביי ממה ששנינו: \u0003העלה\u0004 את הבהמה \u0003לראשי צוקין ונפלה\u0004 — \u0003אין זה\u0004 קרוי \u0003אונס, וחייב.\u0004 ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אילו \u0003מתה כדרכה הרי זה\u0004 \u0003אונס, ופטור. ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003לימא ליה\u0004 \u0005[שיאמר לו]\u0006 בעל הפרה לשומר: אתה אשם בדבר, כי \u0003אוירא\u0004 \u0005[אויר]\u0006 ה\u0003הר קטלה\u0004 \u0005[הרג אותה],\u0006 \u0003אי נמי אובצנא דהר קטלה\u0004 \u0005[\u0006טרחת \u0005עייפות\u0006 העליה \u0005להר היא שהרגה אותה]!\u0006","ודוחים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003שהעלה\u0004 את הבהמה \u0003למרעה שמן וטוב,\u0004 שאין לומר שמתה מפני אויר ההרים או העייפות שבעליה לשם. ושואלים: \u0003אי הכי\u0004 \u0005[אם כן]\u0006 עשה, שלמקום מרעה שמן וטוב הביאה, הרי לא היתה בכך רשלנות כלל, ואם \u0003נפלה נמי\u0004 \u0005[גם כן]\u0006 מדוע חייב עליה? שהרי הביא אותה למקום טוב, ובאונס מתה! ומשיבים: \u0003שהיה לו לתוקפה\u0004 \u0005[להחזיקה]\u0006 \u0003ולא תקפה\u0004 \u0005[החזיקה],\u0006 ובשל כך משלם.","ומקשים: \u0003אי הכי, אימא רישא\u0004 \u0005[אם כך אמור את ראשה\u0006 של המשנה\u0005]:\u0006 \u0003עלתה\u0004 הבהמה בעצמה \u0003לראשי צוקין ונפלה\u0004 — \u0003הרי זה אונס,\u0004 ולפי ההסבר שנתת \u0003איבעי ליה למיתקפה\u0004 \u0005[היה צריך להחזיק אותה]!\u0006 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003שתקפתו ועלתה, תקפתו וירדה,\u0004 שהבהמה התגברה עליו, ולמרות שהחזיק בה עלתה על ראשי הצוקים, ואף שניסה לשמור אותה שלא תיפול, היא תקפתו וירדה, ושם נפלה.","שנינו במשנה ש\u0003אמר ר' יוסי: כיצד הלה עושה סחורה בפרתו\u0004 של חבירו, שהשוכר מקבל תשלום תמורת פרה שבעצם שייכת לבעלים? \u0003אמר רב יהודה אמר שמואל: הלכה כר' יוסי. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב שמואל בר יהודה לרב יהודה, אמרת לן משמיה\u0004 \u0005[לנו משמו]\u0006 של \u0003שמואל: חלוק היה ר' יוסי\u0004"],["\u0003אף בראשונה,\u0004 שלא רק על משנתנו זו חלק אלא גם על המשנה הראשונה בפרק כשהשומר שילם ולא רצה להישבע אין ר' יוסי מסכים שהשומר מקבל את הכפל, ומאחר שכן ברצוני לברר האם \u0003הלכה כמותו\u0004 אף בראשונה \u0003או אין הלכה כמותו? אמר ליה\u0004 \u0005[לו]\u0006 \u0003חלוק היה ר' יוסי אף בראשונה, והלכה כמותו אף בראשונה.\u0004","\u0003אתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 שחלקו אמוראים בארץ ישראל בשאלה זו. \u0003אמר ר' אלעזר: חלוק היה ר' יוסי אף בראשונה והלכה כמותו אף בראשונה. ור' יוחנן אמר: מודה היה ר' יוסי בראשונה\u0004 לפי \u0003שכבר שילם\u0004 ונקנתה לו הבהמה.","על לשונו של ר' יוחנן תוהים: \u0003שילם\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 \u0003לא שילם\u0004 — \u0003לא? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' חייא רב אבא\u0004 ש\u0003אמר ר' יוחנן\u0004 עצמו: מה שנאמר במשנה שם \"שילם\", \u0003לא \"שילם\" שילם ממש, אלא כיון שאמר \"הריני משלם\", אף על פי שלא שילם.\u0004 ואם כן לדעת ר' יוחנן אינו צריך לשלם ממש! ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 ותקן את הלשון שנאמר בשם ר' יוחנן כך: \u0003מודה היה ר' יוסי בראשונה שכבר אמר \"הריני משלם\".\u0004","\u0003אמר לשנים: גזלתי לאחד מכם מנה\u0004 (מאה דינרים) \u0003ואיני יודע\u0004 מ\u0003איזה מכם\u0004 גזלתי. \u0003או\u0004 אמר לשניים: \u0003אביו של אחד מכם הפקיד לי מנה ואיני יודע איזה הוא\u0004 — הרי זה \u0003נותן לזה מנה ולזה מנה,\u0004 כיון שאין דרך לברר הדבר, והואיל \u0003שהודה מפי עצמו.\u0004","ואולם אם אירע באופן אחר, וכגון ב\u0003שנים שהפקידו\u0004 כסף \u0003אצל\u0004 אדם \u0003אחד, זה\u0004 הפקיד \u0003מנה, וזה,\u0004 האחר, הפקיד בידו \u0003מאתים.\u0004 ואחר כך חזרו ובאו, \u0003זה אומר: שלי\u0004 היו ה\u0003מאתים, וזה אומר שלי\u0004 היו ה\u0003מאתים.\u0004 מה יעשה? \u0003נותן לזה מנה ולזה מנה, והשאר,\u0004 מנה ששניהם תובעים, \u0003יהא מונח עד שיבא אליהו\u0004 ויברר האמת בנבואתו.","\u0003אמר ר' יוסי: אם כן\u0004 הוא עושה \u0003מה הפסיד הרמאי?\u0004 וכיון שהרמאי אינו מפסיד דבר יבוא לטעון לממון חבירו שמא יקבל משהו, והוא לא יודה על האמת. \u0003אלא\u0004 כך יעשה: \u0003הכל,\u0004 כל סכום הפקדון כולו, \u0003יהא מונח עד שיבא אליהו,\u0004 שכיון שמכחישים זה את זה ואין דרך לברר את האמת, שישאר הכל מונח, ומשום כך שמא יודה הרמאי כדי לקבל לפחות את שלו.","\u0003וכן,\u0004 אם הפקידו אצל אדם \u0003שני כלים, אחד יפה\u0004 (שווה) \u0003מנה, ואחד יפה אלף זוז, זה אומר: יפה שלי, וזה אומר: יפה שלי\u0004 — \u0003נותן את הקטן לאחד מהם, ומתוך הגדול נותן דמי קטן לשני, והשאר יהא מונח עד שיבא אליהו.\u0004 אף כאן \u0003אמר ר' יוסי: אם כן מה הפסיד הרמאי? אלא, הכל יהא מונח עד שיבא אליהו\u0004 או שיודה אחד מהם.","ממה שנאמר במשנה שנותן לזה מנה ולזה מנה, \u0003אלמא\u0004 \u0005[מכאן כי]\u0006 \u0003מספיקא מפקינן ממונא\u0004 \u0005[מספק מוציאים אנו ממון],\u0006 \u0003ולא אמרינן אוקי ממונא בחזקת מריה\u0004 \u0005[ואין אנו אומרים: העמד את הממון בחזקת בעליו]\u0006 הראשונים, ולא יתן עד שיוכיחו לו למי חייב.","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 שהרי שנינו בהמשך: \u0003שנים שהפקידו אצל אחד, זה מנה וזה מאתים, זה אומר \"שלי מאתים\" וזה אומר \"שלי מאתים\"\u0004 — \u0003נותן לזה מנה ולזה מנה והשאר יהא מונח עד שיבא אליהו.\u0004","\u0003אמרו לו\u0004 לשואל: מ\u0003פקדון\u0004 על \u0003גזל קא רמית\u0004 \u0005[אתה משליך,\u0006 מקשה\u0005],\u0006 אין הדברים דומים; בענין \u0003גזל דעבד איסורא\u0004 \u0005[שעשה איסור]\u0006 — \u0003קנסוהו רבנן\u0004 \u0005[חכמים]\u0006 שיתן לכל אחד, ב\u0003פקדון\u0004 ש\u0003לא עבד איסורא\u0004 \u0005[עשה איסור]\u0006 — \u0003לא קנסוהו רבנן\u0004 \u0005[חכמים].\u0006","\u0003ורמי\u0004 \u0005[משליכים,\u0006 ומראים סתירה\u0005]\u0006 מדין \u0003פקדון\u0004 ל\u0003פקדון, ורמי\u0004 \u0005[משליכים,\u0006 ומראים סתירה\u0005]\u0006 מדין \u0003גזל\u0004 ל\u0003גזל, פקדון\u0004 על \u0003פקדון\u0004 \u0003, דקתני רישא\u0004 — [\u0005ששנינו בתחילת\u0006 משנתנו:] \u0003או אביו של אחד מכם הפקיד אצלי מנה, ואיני יודע איזה הוא\u0004 — \u0003נותן לזה מנה ולזה מנה. ורמינהי\u0004 \u0005[השלכנו\u0006 והקשינו על כך\u0005]\u0006 ממה שנאמר בסוף \u0003שנים שהפקידו\u0004 אצל אחד נותן רק מנה לכל אחד מן התובעים!","\u0003אמר רבא\u0004 יש לתרץ כך: \u0003רישא\u0004 \u0005[בתחילה]\u0006 \u0003נעשה,\u0004 הרי זה במקרה, \u0003כמי שהפקידו לו בשני כריכות,\u0004 שכל אחד מפקיד בחבילה לעצמו, \u0003דהוה ליה למידק\u0004 \u0005[משהיה לו\u0006 למחזיק הפקדון \u0005לדקדק]\u0006 מי נתן לו איזו חבילה, ואם התרשל ושכח — משלם הכל. ו\u0003סיפא\u0004 \u0005[וסופה]\u0006 \u0003נעשה כמי שהפקידו לו\u0004 שניהם \u0003בכרך\u0004 (בחבילה) \u0003אחד. דלא הוה ליה למידק\u0004 \u0005[שלא היה לו לדקדק\u0006 בדבר\u0005],\u0006 \u0003כגון דאפקידו תרוייהו בהדי הדדי בחד זימנא\u0004 \u0005[כגון שהפקידו שניהם יחד בפעם אחת]\u0006 \u0003דאמר להו\u0004 \u0005[שאומר להם]\u0006 מחזיק הפקדון: \u0003אנת גופייכו לא קפדיתו אהדדי, אנא קפידנא\u0004 \u0005[אתם עצמכם אינכם מקפידים זה על זה,\u0006 וכי \u0005אני אקפיד\u0006 על כך\u0005]?\u0006 ומשום כך אינו חייב לשלם יותר ממה שיכולים הצדדים להוציא בראיה.","ומצד אחר \u0003רמי\u0004 \u0005[משליך,\u0006 מראים סתירה\u0005]\u0006 בין \u0003גזל\u0004 ל\u0003גזל, קתני הכא\u0004 \u0005[שנה פה]:\u0006 \u0003אמר לשנים גזלתי לאחד מכם מנה ואיני יודע איזה מכם, או אביו של אחד מכם הפקיד לי מנה ואיני יודע איזה הוא\u0004 — \u0003נותן לזה מנה ולזה מנה.\u0004","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003גזל\u0004 כסף מאיש \u0003אחד\u0004 מתוך \u0003חמשה, ואינו יודע איזה מהן\u0004 מן החמשה \u0003גזל, זה אומר: אותי גזל, וזה אומר: אותי גזל, מניח\u0004 ה\u0003גזילה ביניהם ומסתלק\u0004 ושיסתדרו הם ביניהם, אלו \u0003דברי ר' טרפון. אלמא\u0004 \u0005[מכאן\u0006 כי\u0005]\u0006 \u0003מספקא לא מפקינן ממונא\u0004 \u0005[מספק אין אנו מוציאים ממון]\u0006 מבעליו, \u0003ואמרינן\u0004 \u0005[ואומרים אנו]\u0006 ככלל: \u0003אוקים ממונא בחזקת מריה\u0004 \u0005[העמד את הממון בחזקת בעליו].\u0006","לפני שבאים לישב את הסתירה שואלים לגבי עיקר הקושיה \u0003וממאי דמתניתין דהכא ר' טרפון היא\u0004 \u0005[ומנין\u0006 שמשנתנו \u0005כאן\u0006 כשיטת \u0005ר' טרפון\u0006 היא\u0005]\u0006 שמא משנתנו כדעת ר' עקיבא החולק עליו שם! ומסבירים: \u0003דקתני עלה דההיא\u0004 \u0005[ששנויה\u0006 ברייתא נוספת על המשנה \u0005ההיא]\u0006 \u0003מודה ר' טרפון באומר לשנים גזלתי לאחד מכם מנה ואיני יודע איזה מכם\u0004 — \u0003שנותן לזה מנה ולזה מנה.\u0004 ואם כן יש מפה לשם לכאורה סתירה!","ומשיבים: \u0003התם דקא תבעי ליה\u0004 \u0005[שם\u0006 שמחזיר רק לאחד מחמישה מדובר \u0005כאשר הם תובעים אותו]\u0006 ומצד הדין אינו צריך לתת אלא מנה אחד, לפי שעליהם חובת הראיה. אבל \u0003הכא\u0004 \u0005[כאן]\u0006 במשנתנו מדובר \u0003בבא לצאת ידי שמים\u0004 שרצונו לחזור בתשובה לצאת גם ידי שמים, שתמחל לו הגזילה, ומשום כך נוהג לפנים משורת הדין כדי להיות בטוח שהחזיר לנגזל. ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 מלשון המשנה, שכן נאמר פה בהסבר: \u0003שהודה מפי עצמו,\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 שכך יש להבין.","בהמשך לבעיה לגבי מחזיר גזלה, מבררים, \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003התם דקא תבעי ליה\u0004 \u0005[שם\u0006 מדובר \u0005שתובעים אותו].\u0006 ושואלים: \u0003והלה\u0004 הגזלן \u0003מה טוען\u0004 על התביעות הללו? \u0003רב יהודה אמר\u0004 בשם \u0003רב: הלה שותק\u0004 לפי שאינו יודע. \u0003רב מתנה אמר\u0004 בשם \u0003רב: הלה\u0004"],["\u0003צווח\u0004 ואומר לכל אחד אני אינני מכירך ואיני מוצא מקום לטענתך. ומעירים: \u0003מאן דאמר\u0004 \u0005[\u0006לדעת \u0005מי שאומר]\u0006 \u0003הלה צווח, אבל\u0004 אם היתה כאן \u0003שתיקה,\u0004 אילו היה שותק, או אומר \"אולי אתה צודק\" הרי היא \u0003כהודאה. ומאן דאמר\u0004 \u0005[ו\u0006לדעת \u0005מי שאומר]\u0006 ש\u0003הלה שותק,\u0004 לדעתו \u0003שתיקה דהכא לאו\u0004 \u0005[של כאן לא]\u0006 \u0003כהודאה הוא,\u0004 שכן \u0003מצי אמר ליה\u0004 \u0005[יכול\u0006 הוא \u0005לומר לו]:\u0006 \u0003האי דשתיקי\u0004 \u0005[זה ששתקתי]\u0006 \u0003לכל חד וחד\u0004 \u0005[אחד ואחד],\u0006 הרי זה משום \u0003דאמינא דלמא האי\u0004 \u0005[שאמרתי\u0006 \u0003שמא זה]\u0004 \u0003הוא,\u0004 אבל אני אינני מודה שאני חייב יותר מאחד.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003מניח גזילה ביניהם ומסתלק.\u0004 ושואלים: \u0003ושקלי לה כולהו ואזלי\u0004 \u0005[ולוקחים אותה כולם והולכים]\u0006 ונמצא שהנגזל האמיתי מפסיד את חלקו? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אבא בר זבדא אמר רב: כל ספק הינוח,\u0004 כלומר, דבר שלא ברור למוצא אם הניחוהו בעליו שם או איבדוהו, \u0003לכתחילה\u0004 — \u0003לא יטול, ואם נטל\u0004 — \u0003לא יחזיר,\u0004 בסימנים בלבד, עד שתהא לו הוכחה בעדים שהתובע הוא אכן בעל האבידה, שהניחה שם. ואם כן, גם כאן צריך היה הגזלן לעכב בידו את הסכום עד שתובא לו ראיה! \u0003אמר רב ספרא:\u0004 הכוונה היא: \u0003ויניח\u0004 בבית דין. כלומר, לא שיניח בפועל את סכום הכסף, אלא כיון שלא נתברר למי הוא, יפקיד את הגזילה בידי בית דין, ויאמר: הרי החזרתי את הגזילה, ומי שיוכיח שהיא שלו יקבלנה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרבא: מי\u0004 \u0005[האם]\u0006 \u0003אמר ר' עקיבא: לא זו הדרך מוציאתו מידי עבירה עד שישלם גזילה לכל חד וחד\u0004 \u0005[אחד ואחד],\u0006 \u0003אלמא\u0004 \u0005[מכאן\u0006 כי\u0005]\u0006 \u0003מספיקא מפקינן ממונא\u0004 \u0005[מספק מוציאים אנו ממון]\u0006 \u0003ולא אמרינן \"אוקים ממונא בחזקת מריה\"\u0004 \u0005[ואין אנו אומרים \"העמד את הכסף בחזקת בעליו\"].\u0006","\u0003ורמינהי\u0004 \u0005[אנו משליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: אדם אשר \u0003נפל הבית עליו ועל אמו\u0004 ולא ברור מי מהם מת קודם, \u0003יורשי הבן אומרים: האם מתה ראשונה,\u0004 וכיון שכן ירש אותה בנה, ורק אחר כך מת, ולכן יורשים הם הכל. ואילו \u0003יורשי האם אומרים: הבן מת ראשון,\u0004 ולכן מגיעה להם את ירושת האם. במקרה זה \u0003אלו ואלו\u0004 גם בית שמאי ובית הלל שנחלקו במקרים דומים \u0003מודים שיחלוקו\u0004 הצדדים בנכסים המסופקים. \u0003ואמר ר' עקיבא:\u0004 אינו כן, אלא \u0003מודה\u0004 אף \u0003אני בזו שהנכסים בחזקתן,\u0004 כלומר, בחזקת מי שהם מגיעים לו לפי הדין, ואין חולקים ביניהם. ואם כן רואים שלשיטת ר' עקיבא עצמו אין מוציאים ממון מן המחזיק בו מחמת הספק!","\u0003אמר ליה:\u0004 אין הדברים דומים, \u0003התם\u0004 \u0005[שם]\u0006 כאשר נפל הבית, טענות \u0003שמא ושמא\u0004 הן, שהרי שני הצדדים אינם יודעים מה בדיוק אירע, ואינם יכולים לטעון טענת ודאי, אלא כל אחד מהם טוען טענת שמא. אבל במקרה של \u0003גזל אחד מחמשה\u0004 — \u0003ברי ושמא\u0004 הוא, שאמנם הגזלן אינו יודע, אבל הנגזל טוען שברור לו כי הצדק עמו. ושואלים: \u0003והא מתניתין דהכא\u0004 \u0005[והרי משנתנו של כאן]\u0006 ש\u0003אמר לשנים: גזלתי לאחד מכם מנה,\u0004 שטענות \u0003שמא ושמא הוא, וקתני\u0004 \u0005[ושנה]\u0006 בכל זאת: \u0003נותן לזה מנה ולזה מנה.\u0004","ושואלים: \u0003וממאי\u0004 \u0005[וממה]\u0006 יודע אתה שכשיטת \u0003ר' עקיבא היא?\u0004 ומשיבים: \u0003דקתני עלה דההיא\u0004 \u0005[ששנויה\u0006 ברייתא מסבירה \u0005עליה]:\u0006 \u0003מודה ר' טרפון באומר לשנים \"גזלתי לאחד מכם מנה ואיני יודע איזה מכם\u0004 הוא הנגזל \u0003\"\u0004שהדין הוא יתן לשניהם, ו\u0003למאן\u0004 \u0005[למי]\u0006 \u0003מודה\u0004 הוא? \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003לר' עקיבא בר פלוגתיה\u0004 \u0005[בן מחלוקתו]?\u0006","ושואלים: \u0003וממאי\u0004 \u0005[וממה]\u0006 לומד אתה שבמשנתנו הטענות ב\u0003שמא ושמא?\u0004 אולי מדובר כאן שהנגזלים טוענים טענת ודאי! ומשיבים: אין הדבר מסתבר, מכמה סיבות, \u0003חדא\u0004 \u0005[אחת]\u0006 ש\u0003לא קתני\u0004 \u0005[שנה]\u0006 \u0003תובעין אותו,\u0004 משמע שהם עצמם אינם בטוחים. \u0003ועוד, הא תני\u0004 \u0005[הרי שנה]\u0006 \u0003ר' חייא\u0004 בברייתא מסבירה: \u0003זה אומר \"איני יודע\" וזה אומר \"איני יודע\",\u0004 הרי שטענת שמא היא.","את הסתירה בשיטת ר' עקיבא מתרצים: \u0003הא אוקימנא לה\u0004 \u0005[הרי כבר העמדנו\u0006 הסברנו \u0005אותה]\u0006 את המשנה, שמדובר כאן \u0003בבא לצאת ידי שמים,\u0004 ולכן נותן אפילו בטענת שמא, אף שמן הדין אינו חייב לתת.","בהמשך לדברים שדנו בהם קודם \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: ומי\u0004 \u0005[והאם]\u0006 \u0003אמר רבא\u0004 ש\u0003כל\u0004 דבר שנמסר \u0003בשתי כריכות\u0004 לחוד \u0003הוה ליה למידק\u0004 \u0005[היה לו\u0006 לנפקד \u0005לדקדק]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא, ואי תימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב פפא: הכל מודים בשנים שהפקידו\u0004 בהמות \u0003אצל\u0004 ה\u0003רועה,\u0004 ואחר כך תובע כל אחד מהם מספר רב יותר של בהמות, \u0003שמניח רועה ביניהן ומסתלק! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 מדובר \u0003כשהפקידו בעדרו של רועה שלא מדעתו,\u0004 ובמקרה כזה ודאי שאין עליו כל אחריות לברר מי מהם הפקיד וכמה הפקיד.","שנינו במשנה את הדין ביחס למפקידים התובעים מנה או מאתיים, \u0003וכן\u0004 בענין \u0003שני כלים אחד יפה מנה ואחד יפה אלף זוז\u0004 שהופקדו אצל אחד וכל אחד מן המפקידים טוען ששלו הכלי הגדול. ומעירים: \u0003וצריכא\u0004 \u0005[ונצרכה]\u0006 להיאמר בשני המקרים, למרות שהם לכאורה זהים.","\u0003דאי אשמועינן הך קמייתא\u0004 \u0005[שאילו היה משמיע לנו\u0006 רק את \u0005זו הראשונה]\u0006 בכספים בלבד, הייתי אומר: \u0003בההיא קאמרי רבנן\u0004 \u0005[אמרו חכמים],\u0006 \u0003משום דליכא פסידא\u0004 \u0005[שאין הפסד בדבר].\u0006 \u0003אבל בהא, דאיכא פסידא\u0004 \u0005[בזו שיש הפסד]\u0006 של \u0003הכלי ה\u0004\u0003גדול\u0004 שצריך לשבור או למכור אותו כדי לשלם מתוכו את הקטן \u0003אימא מודו ליה\u0004 \u0005[אמור שמודים לו]\u0006 \u0003לר' יוסי.\u0004 ולהפך, \u0003ואי אתמר בהא\u0004 \u0005[ואם היה נאמר בזו],\u0006 בכלים, היינו אומרים: \u0003בהא קאמר\u0004 \u0005[בזו\u0006 בלבד \u0005אמר]\u0006 \u0003ר' יוסי, אבל בהך\u0004 \u0005[בההיא,\u0006 בכסף\u0005]\u0006 \u0003אימא מודי להו לרבנן\u0004 \u0005[אמור שמודה להם לחכמים],\u0006 על כן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 להיאמר בשניהם."]]};
